:root {
  --ink: #121417;
  --ink-2: #1b1e22;
  --ink-3: #24282d;
  --parch: #f2e6ca;
  --parch-dim: #cdbf9f;
  --gold: #e7c37a;
  --gold-2: #b8914d;
  --gold-deep: #6f5330;
  --red: #b84633;
  --red-2: #7e2a1f;
  --green: #7ba35a;
  --blue: #4d7fa3;
  --line: rgba(231, 195, 122, 0.28);
  --safe-t: env(safe-area-inset-top, 0px);
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
  --ui-font: "Trebuchet MS", "Avenir Next", "Segoe UI", system-ui, sans-serif;
  --serif: "Iowan Old Style", "Palatino Linotype", "Book Antiqua", Georgia, serif;
}

* { box-sizing: border-box; }
html, body {
  margin: 0;
  padding: 0;
  height: 100%;
  overflow: hidden;
  background: #101418;
  color: var(--parch);
  font-family: var(--ui-font);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
}
body { position: fixed; inset: 0; }
button { font: inherit; color: inherit; border: 0; background: none; padding: 0; cursor: pointer; }
input, textarea { font: inherit; }
.svg-defs { position: absolute; width: 0; height: 0; overflow: hidden; }
.ic { width: 1em; height: 1em; display: inline-block; fill: none; stroke: none; vertical-align: -0.12em; }
.ic use { pointer-events: none; }
.hidden { display: none !important; }

#app { position: fixed; inset: 0; overflow: hidden; }
#scene { position: absolute; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; outline: none; }
#vignette {
  position: absolute; inset: 0; pointer-events: none;
  background:
    radial-gradient(ellipse at 50% 46%, transparent 45%, rgba(8, 10, 12, 0.24) 100%),
    linear-gradient(180deg, rgba(8, 10, 12, 0.16), transparent 16%, transparent 76%, rgba(8, 10, 12, 0.4));
  z-index: 2;
}
#letterbox-top, #letterbox-bottom {
  position: absolute; left: 0; right: 0; height: 0; background: #0b0d0f; z-index: 3;
  transition: height .6s ease;
}
#letterbox-top { top: 0; }
#letterbox-bottom { bottom: 0; }
body.cinematic #letterbox-top, body.cinematic #letterbox-bottom { height: 7vh; }

/* ============ HUD ============ */
#hud { position: absolute; inset: 0; z-index: 10; pointer-events: none; }
#hud > * { pointer-events: none; }
#hud button, #hud #bottombar, #hud #resources, #hud #quest { pointer-events: auto; }

#topbar {
  position: absolute;
  top: calc(8px + var(--safe-t));
  left: calc(10px + var(--safe-l));
  right: calc(10px + var(--safe-r));
  display: flex;
  flex-direction: column;
  gap: 6px;
  max-width: 1180px;
  margin: 0 auto;
}
.topline { display: flex; align-items: center; gap: 10px; }
.brand-small {
  display: flex; align-items: center; gap: 7px;
  color: var(--gold);
  font-family: var(--serif);
  font-size: 15px;
  letter-spacing: .14em;
  text-transform: uppercase;
  text-shadow: 0 2px 8px rgba(0,0,0,.6);
  white-space: nowrap;
}
.brand-small i { color: var(--red); font-style: normal; }
.brand-small .ic { font-size: 20px; }
#phase-pill {
  display: flex; align-items: center; gap: 8px;
  height: 30px; padding: 0 12px;
  margin-left: auto;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(30, 33, 36, .86), rgba(15, 17, 19, .88));
  box-shadow: 0 4px 16px rgba(0,0,0,.3), inset 0 1px rgba(255,255,255,.06);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}
#phase-label { font-size: 10px; letter-spacing: .16em; text-transform: uppercase; color: var(--parch-dim); }
#wave-label { font-size: 12px; font-weight: 700; color: var(--gold); letter-spacing: .04em; }
#phase-pill.combat #phase-label { color: #f0a08d; }
#phase-pill.combat { border-color: rgba(184, 70, 51, .55); }
.top-actions { display: flex; gap: 6px; }
.icon-btn {
  width: 36px; height: 36px;
  display: grid; place-items: center;
  border-radius: 10px;
  border: 1px solid var(--line);
  background: rgba(19, 22, 25, .78);
  color: var(--parch);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  box-shadow: 0 3px 12px rgba(0,0,0,.28);
  transition: background .15s, transform .1s;
}
.icon-btn .ic { font-size: 19px; }
.icon-btn:active { transform: scale(.94); background: rgba(40, 44, 48, .9); }

.resources {
  display: flex;
  gap: 5px;
  align-self: flex-start;
  flex-wrap: nowrap;
  max-width: 100%;
}
.res {
  display: flex; align-items: center; gap: 5px;
  height: 28px;
  padding: 0 8px 0 7px;
  border-radius: 8px;
  background: linear-gradient(180deg, rgba(27, 30, 34, .82), rgba(14, 16, 18, .82));
  border: 1px solid rgba(231,195,122,.17);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  color: var(--parch);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .02em;
  transition: border-color .2s, transform .15s;
  min-width: 0;
}
.res .ic { font-size: 15px; }
.res[data-type="gold"] .ic { color: var(--gold); }
.res[data-type="wood"] .ic { color: #c58e56; }
.res[data-type="stone"] .ic { color: #c3c5c2; }
.res[data-type="food"] .ic { color: #b7cd79; }
.res b { font-weight: 700; font-variant-numeric: tabular-nums; }
.res .delta {
  font-size: 9px; color: #9ec27e; opacity: 0; transform: translateY(3px);
  transition: opacity .3s, transform .3s;
}
.res.gain .delta { opacity: 1; transform: translateY(0); }
.res.flash { border-color: rgba(231,195,122,.6); }
.res.insufficient { color: #ef9d8e; border-color: rgba(184,70,51,.45); }

#wave-progress {
  display: flex; align-items: center; gap: 8px;
  width: min(360px, 100%);
  align-self: center;
  margin-top: 2px;
  padding: 5px 10px;
  border-radius: 999px;
  background: rgba(14, 16, 18, .72);
  border: 1px solid rgba(184,70,51,.35);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
}
.wprog-bar { flex: 1; height: 5px; border-radius: 999px; background: rgba(255,255,255,.12); overflow: hidden; }
.wprog-bar i { display: block; height: 100%; width: 100%; border-radius: inherit; background: linear-gradient(90deg, #b84633, #e08d64); transition: width .3s ease; }
#wprog-text { font-size: 10px; letter-spacing: .08em; color: #edc5b7; white-space: nowrap; text-transform: uppercase; }

#boss-bar {
  position: absolute;
  top: calc(112px + var(--safe-t));
  left: 50%; transform: translateX(-50%);
  width: min(420px, 76vw);
  padding: 7px 12px 9px;
  border-radius: 10px;
  background: rgba(20, 12, 13, .82);
  border: 1px solid rgba(184,70,51,.55);
  box-shadow: 0 6px 24px rgba(0,0,0,.5);
  z-index: 12;
}
.boss-name { display: flex; align-items: center; gap: 6px; font-family: var(--serif); font-size: 13px; letter-spacing: .1em; text-transform: uppercase; color: #f0b7a6; margin-bottom: 5px; }
.boss-name .ic { font-size: 15px; }
.boss-track { height: 8px; border-radius: 99px; overflow: hidden; background: rgba(255,255,255,.1); }
.boss-track i { display: block; height: 100%; width: 100%; background: linear-gradient(90deg, #7e2a1f, #d06a4f); transition: width .25s; }

#quest {
  position: absolute;
  left: calc(12px + var(--safe-l));
  top: calc(116px + var(--safe-t));
  width: 212px;
  padding: 10px 12px 11px;
  border-radius: 10px;
  background: linear-gradient(160deg, rgba(28,31,34,.82), rgba(13,15,17,.78));
  border: 1px solid rgba(231,195,122,.2);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  box-shadow: 0 10px 30px rgba(0,0,0,.25);
  transition: opacity .4s, transform .4s;
}
#quest.done { opacity: 0; transform: translateX(-12px); pointer-events: none; }
.quest-title { font-family: var(--serif); font-size: 11px; letter-spacing: .18em; text-transform: uppercase; color: var(--gold); margin-bottom: 6px; }
#quest-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 5px; }
#quest-list li { display: flex; align-items: center; gap: 7px; font-size: 11.5px; line-height: 1.25; color: #cdc2aa; }
#quest-list li .qbox { width: 12px; height: 12px; border-radius: 3px; border: 1px solid rgba(231,195,122,.4); display: grid; place-items: center; flex: none; }
#quest-list li.complete { color: #8fa883; }
#quest-list li.complete .qbox { background: rgba(123,163,90,.25); border-color: #7ba35a; }
#quest-list li.complete .qbox::after { content: "✓"; font-size: 9px; color: #b8d69e; }

#battle-abilities {
  position: absolute;
  right: calc(12px + var(--safe-r));
  bottom: calc(184px + var(--safe-b));
  display: flex;
  flex-direction: column;
  gap: 9px;
  z-index: 12;
}
.ability {
  position: relative;
  width: 54px; height: 54px;
  border-radius: 50%;
  border: 1px solid rgba(231,195,122,.5);
  background: radial-gradient(circle at 35% 30%, rgba(69,75,80,.96), rgba(19,22,25,.96));
  color: var(--gold);
  box-shadow: 0 6px 18px rgba(0,0,0,.45), inset 0 1px rgba(255,255,255,.08);
  display: grid; place-items: center;
  transition: transform .1s, opacity .2s;
}
.ability .ic { font-size: 23px; }
.ability .key {
  position: absolute; right: -1px; bottom: -1px;
  width: 15px; height: 15px; border-radius: 50%;
  display: grid; place-items: center;
  font-size: 8px; font-weight: 700; color: #d8c9a9;
  background: #1a1d20; border: 1px solid rgba(231,195,122,.3);
}
.ability .cd {
  position: absolute; inset: 0; border-radius: 50%;
  background: conic-gradient(rgba(5,7,9,.78) calc(var(--cd,0) * 1%), transparent 0);
  pointer-events: none;
  opacity: 0;
}
.ability.cooling .cd { opacity: 1; }
.ability.cooling { color: #8f8674; }
.ability.ready { animation: abilityPulse 2.6s infinite; }
.ability:active { transform: scale(.93); }
.ability.targeting { border-color: #f3d493; box-shadow: 0 0 0 3px rgba(231,195,122,.18), 0 0 24px rgba(231,195,122,.35); }
@keyframes abilityPulse {
