/* ============ Bottom build UI ============ */
#bottombar {
  position: absolute;
  left: 0; right: 0; bottom: 0;
  z-index: 11;
  padding: 20px calc(10px + var(--safe-r)) calc(8px + var(--safe-b)) calc(10px + var(--safe-l));
