}
.sel-main { display: flex; align-items: center; gap: 8px; min-width: 0; }
.sel-ic { font-size: 22px; color: var(--gold); flex: none; }
.sel-text { display: flex; align-items: baseline; gap: 8px; min-width: 0; }
.sel-text b { font-family: var(--serif); font-size: 13.5px; letter-spacing: .05em; color: var(--parch); white-space: nowrap; }
.sel-text span { font-size: 11px; color: #a99f8c; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.sel-cost { display: flex; align-items: center; gap: 8px; flex: none; font-size: 11.5px; font-weight: 700; }
.sel-cost span { display: inline-flex; align-items: center; gap: 3px; color: #d6cbb4; }
.sel-cost .ic { font-size: 14px; }
.sel-cost .short { color: #e58d7c; }

#palette-scroll {
  overflow-x: auto; overflow-y: hidden;
  scrollbar-width: none;
  -ms-overflow-style: none;
