.tool-btn:active { transform: scale(.95); }
#btn-wave { margin-left: auto; }
.wave-btn {
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 1px;
  padding: 6px 22px;
  min-width: 150px;
