@keyframes waveGlow {
  0%, 100% { box-shadow: 0 4px 18px rgba(0,0,0,.35), inset 0 1px rgba(255,255,255,.4); }
  50% { box-shadow: 0 4px 22px rgba(231,195,122,.35), 0 0 0 3px rgba(231,195,122,.08), inset 0 1px rgba(255,255,255,.4); }
}

/* ============ Overlays / title ============ */
.overlay {
  position: absolute; inset: 0; z-index: 30;
  display: flex; align-items: center; justify-content: center;
  transition: opacity .45s ease, visibility .45s;
}
.overlay.fade-out { opacity: 0; visibility: hidden; pointer-events: none; }
#title {
  justify-content: flex-start;
  align-items: flex-end;
  padding: 0 calc(6vw + var(--safe-r)) calc(9vh + var(--safe-b)) calc(6vw + var(--safe-l));
}
.title-scrim {
  position: absolute; inset: 0;
  background:
    linear-gradient(85deg, rgba(7,9,11,.82) 0%, rgba(7,9,11,.55) 36%, rgba(7,9,11,.06) 68%, transparent 100%),
    linear-gradient(0deg, rgba(5,7,9,.78), transparent 46%);
