.eyebrow span:last-child { background: linear-gradient(90deg, var(--gold-2), transparent); }
#title h1 {
  margin: 0;
  font-family: var(--serif);
  font-weight: 600;
  font-size: clamp(42px, 7vw, 78px);
  line-height: .93;
