  color: #f5ead2;
  text-shadow: 0 4px 30px rgba(0,0,0,.65);
}
#title h1 .amp {
  display: inline-block;
  color: var(--gold);
  font-style: italic;
  font-size: .64em;
  vertical-align: .08em;
  margin: 0 .06em;
  text-shadow: 0 0 24px rgba(231,195,122,.35);
}
.tagline {
  margin: 15px 0 22px;
  font-family: var(--serif);
  font-size: clamp(14px, 1.9vw, 17px);
  line-height: 1.5;
  color: #c9bea8;
  letter-spacing: .02em;
}
.title-actions { display: flex; flex-wrap: wrap; gap: 8px; max-width: 430px; }
.menu-btn {
  display: flex; align-items: center; justify-content: center; gap: 8px;
  height: 45px; padding: 0 20px;
  border-radius: 7px;
  border: 1px solid rgba(231,195,122,.32);
  background: rgba(20,23,26,.55);
  color: #e6dbc5;
  font-size: 13px; font-weight: 700;
  letter-spacing: .05em;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  transition: background .15s, border-color .15s, transform .1s;
}
.menu-btn .ic { font-size: 18px; color: var(--gold); }
.menu-btn:hover { border-color: rgba(231,195,122,.7); }
.menu-btn:active { transform: scale(.98); }
.menu-btn.primary {
  background: linear-gradient(180deg, #e5c07a, #b78b45);
  border-color: #f0d9a8;
  color: #2a2012;
  box-shadow: 0 6px 22px rgba(0,0,0,.3), inset 0 1px rgba(255,255,255,.45);
}
.menu-btn.primary .ic { color: #3a2b15; }
.menu-btn.hidden { display: none; }
.menu-btn.ghost {
  border-color: rgba(255,255,255,.16);
  background: rgba(20,23,26,.32);
  color: #cdc2ac;
  height: 38px; padding: 0 15px; font-size: 11.5px;
}
.title-foot {
  display: flex; align-items: center; gap: 8px; flex-wrap: wrap;
  margin-top: 20px;
  font-size: 9.5px; letter-spacing: .12em; text-transform: uppercase;
  color: #8f8777;
}
.title-foot .dot { color: #5c574c; }
.title-side {
  position: absolute; right: 4vw; bottom: 13vh; z-index: 2;
  max-width: 190px;
  writing-mode: vertical-rl;
  text-orientation: mixed;
  font-family: var(--serif);
  font-size: 11px;
  letter-spacing: .18em;
  color: rgba(238,224,197,.55);
  text-transform: uppercase;
}
.title-side .title-note span { color: var(--gold); margin-right: 8px; font-size: 20px; }
.title-side .title-note span:first-child { display: none; }

/* ============ Modals ============ */
#modal { z-index: 40; }
.modal-backdrop {
  position: absolute; inset: 0;
  background: radial-gradient(ellipse at 50% 45%, rgba(8,10,12,.62), rgba(4,5,7,.9));
  backdrop-filter: blur(5px);
  -webkit-backdrop-filter: blur(5px);
}
.modal-card {
  position: relative;
  width: min(880px, 92vw);
  max-height: 88dvh;
  overflow-y: auto;
  padding: 26px clamp(18px, 3vw, 34px) 24px;
  border-radius: 13px;
  border: 1px solid rgba(231,195,122,.4);
  background:
    linear-gradient(160deg, rgba(39,41,41,.98), rgba(17,19,21,.99)),
    radial-gradient(ellipse at 50% 0%, rgba(231,195,122,.12), transparent 60%);
  box-shadow: 0 30px 100px rgba(0,0,0,.7), inset 0 1px rgba(255,255,255,.08);
  animation: modalIn .3s cubic-bezier(.2,.9,.3,1) both;
  scrollbar-width: thin;
  scrollbar-color: rgba(231,195,122,.3) transparent;
}
@keyframes modalIn { from { opacity: 0; transform: scale(.96) translateY(8px); } to { opacity: 1; transform: none; } }
.modal-card.narrow { width: min(480px, 92vw); }
.modal-kicker { font-size: 9.5px; letter-spacing: .24em; text-transform: uppercase; color: var(--gold-2); margin-bottom: 4px; }
.modal-title { font-family: var(--serif); font-size: clamp(24px, 4vw, 36px); line-height: 1.1; color: #f4e8d0; margin: 0 0 5px; letter-spacing: .01em; }
.modal-sub { font-size: 12.5px; line-height: 1.55; color: #a99f8c; margin: 0 0 18px; max-width: 600px; }
.modal-close {
  position: absolute; top: 12px; right: 12px;
  width: 32px; height: 32px;
  display: grid; place-items: center;
  border-radius: 50%;
  color: #b6ab96;
  background: rgba(255,255,255,.05);
  border: 1px solid rgba(255,255,255,.08);
}
.modal-close .ic { font-size: 14px; }
.rew-loot { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 18px; }
.loot-chip {
  display: flex; align-items: center; gap: 5px;
  height: 28px; padding: 0 10px;
  border-radius: 7px;
  background: rgba(0,0,0,.22);
  border: 1px solid rgba(231,195,122,.18);
  font-size: 12px; font-weight: 700; color: #e6d7b8;
}
.loot-chip .ic { font-size: 14px; color: var(--gold); }
.upgrade-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 9px; }
.upgrade-card {
  position: relative;
  text-align: left;
  padding: 16px 14px 14px;
  border-radius: 10px;
  border: 1px solid rgba(231,195,122,.24);
  background: linear-gradient(170deg, rgba(55,56,50,.8), rgba(21,23,24,.9));
  color: #d8cbb2;
  transition: transform .15s, border-color .15s, background .15s;
  overflow: hidden;
}
.upgrade-card::after {
  content: ""; position: absolute; inset: 0;
  background: radial-gradient(ellipse at 50% 0%, rgba(231,195,122,.13), transparent 60%);
  opacity: 0; transition: opacity .2s;
}
.upgrade-card:hover { border-color: rgba(231,195,122,.8); transform: translateY(-2px); }
.upgrade-card:hover::after { opacity: 1; }
.upgrade-card .uic { font-size: 25px; color: var(--gold); margin-bottom: 7px; position: relative; z-index: 1; }
.upgrade-card h4 { font-family: var(--serif); font-size: 15px; color: #f0e4cd; margin: 0 0 5px; position: relative; z-index: 1; letter-spacing: .02em; }
.upgrade-card p { font-size: 11px; line-height: 1.45; color: #a99f8d; margin: 0; position: relative; z-index: 1; }
.modal-actions { display: flex; gap: 8px; justify-content: flex-end; align-items: center; margin-top: 18px; flex-wrap: wrap; }
.modal-note { margin-right: auto; font-size: 10px; color: #8d8473; letter-spacing: .04em; }
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 7px;
  height: 40px; padding: 0 18px;
  border-radius: 7px;
  border: 1px solid rgba(231,195,122,.28);
  background: rgba(255,255,255,.05);
  color: #ddd0b7;
  font-size: 12px; font-weight: 700; letter-spacing: .05em;
  transition: background .15s, border-color .15s, transform .1s;
}
.btn .ic { font-size: 16px; }
.btn:active { transform: scale(.98); }
.btn.gold {
  background: linear-gradient(180deg, #e2ba6d, #b5883e);
  border-color: #f0d9a8; color: #2a2012;
  box-shadow: inset 0 1px rgba(255,255,255,.4);
}
.btn.danger { border-color: rgba(184,70,51,.5); color: #eeb0a1; }
.btn.wide { width: 100%; }

.how-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 10px; margin-top: 4px; }
.how-item { padding: 12px 13px; border-radius: 9px; background: rgba(255,255,255,.035); border: 1px solid rgba(255,255,255,.065); }
.how-item h4 { display: flex; align-items: center; gap: 7px; margin: 0 0 4px; font-family: var(--serif); font-size: 14px; color: #eee1c8; }
.how-item h4 .ic { color: var(--gold); font-size: 17px; }
.how-item p { margin: 0; font-size: 11.5px; line-height: 1.5; color: #a89e8b; }
.how-item b { color: #d8cbb1; font-weight: 700; }

.stats-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin: 16px 0 4px; }
.stat { padding: 12px 10px; border-radius: 8px; background: rgba(0,0,0,.2); border: 1px solid rgba(231,195,122,.12); text-align: center; }
.stat b { display: block; font-family: var(--serif); font-size: 24px; color: var(--gold); line-height: 1; margin-bottom: 3px; }
.stat span { font-size: 9px; letter-spacing: .12em; text-transform: uppercase; color: #8f8674; }

.pause-list { display: flex; flex-direction: column; gap: 7px; margin-top: 12px; }
.pause-row { display: flex; align-items: center; justify-content: space-between; padding: 10px 2px; border-bottom: 1px solid rgba(255,255,255,.06); font-size: 12px; color: #b6ab96; }
.pause-row:last-child { border-bottom: 0; }
.switch {
  width: 40px; height: 23px; border-radius: 99px;
  background: rgba(255,255,255,.12); border: 1px solid rgba(255,255,255,.12);
  position: relative; transition: background .2s;
}
.switch::after { content: ""; position: absolute; top: 2px; left: 2px; width: 17px; height: 17px; border-radius: 50%; background: #b9ad96; transition: transform .2s, background .2s; }
.switch.on { background: rgba(123,163,90,.4); border-color: rgba(123,163,90,.5); }
.switch.on::after { transform: translateX(17px); background: #d9e8c3; }

#toast {
  position: absolute;
  left: 50%; bottom: calc(190px + var(--safe-b));
  transform: translateX(-50%) translateY(8px);
  z-index: 50;
  max-width: 86vw;
  padding: 9px 16px;
  border-radius: 999px;
  border: 1px solid rgba(231,195,122,.28);
  background: rgba(16,18,20,.92);
  color: #e6d9c0;
  font-size: 12px;
  letter-spacing: .015em;
  box-shadow: 0 10px 30px rgba(0,0,0,.45);
  opacity: 0;
  transition: opacity .22s, transform .22s;
  pointer-events: none;
  text-align: center;
}
#toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }
#toast.bad { border-color: rgba(184,70,51,.6); color: #f0b4a5; }
#toast.good { border-color: rgba(123,163,90,.5); color: #cbdcb3; }

#rotate-hint {
  position: absolute; left: 50%; top: calc(50% - 20px); transform: translate(-50%, -50%);
  z-index: 60; padding: 10px 18px; border-radius: 999px;
  background: rgba(13,15,17,.9); border: 1px solid rgba(231,195,122,.3);
  font-size: 12px; color: #d8c9ad;
