/* ============ Responsive ============ */
@media (max-width: 760px) {
  #title { padding: 0 calc(22px + var(--safe-r)) calc(7vh + var(--safe-b)) calc(22px + var(--safe-l)); align-items: flex-end; }
  .title-scrim { background: linear-gradient(0deg, rgba(6,8,10,.94) 0%, rgba(6,8,10,.7) 42%, rgba(6,8,10,.05) 78%), linear-gradient(90deg, rgba(6,8,10,.45), transparent); }
