  .tagline { margin: 10px 0 16px; font-size: 13.5px; }
  .title-actions { max-width: none; gap: 7px; }
  .menu-btn { height: 43px; padding: 0 15px; font-size: 12px; flex: 1 1 auto; }
  .menu-btn.ghost { flex: 0 0 auto; height: 34px; }
  .menu-btn .ic { font-size: 16px; }
