  .icon-btn { width: 32px; height: 32px; border-radius: 9px; }
  .icon-btn .ic { font-size: 17px; }
  .top-actions { gap: 5px; }
  .res { height: 26px; padding: 0 7px; gap: 4px; font-size: 11px; flex: 1 1 0; justify-content: center; min-width: 0; }
  .res .ic { font-size: 14px; }
  .res .delta { display: none; }
  .resources { width: 100%; gap: 4px; }
  .resources .res b { overflow: hidden; text-overflow: ellipsis; }
  #wave-progress { width: 100%; }
  #boss-bar { top: calc(104px + var(--safe-t)); }
  #quest { top: calc(108px + var(--safe-t)); left: calc(10px + var(--safe-l)); width: 178px; padding: 8px 10px 9px; }
  #quest-list li { font-size: 10.5px; }
  #battle-abilities { bottom: calc(116px + var(--safe-b)); right: calc(10px + var(--safe-r)); gap: 7px; }
  .ability { width: 48px; height: 48px; }
  .ability .ic { font-size: 20px; }
  .ability .key { display: none; }
  #bottombar { padding: 16px calc(7px + var(--safe-r)) calc(6px + var(--safe-b)) calc(7px + var(--safe-l)); gap: 6px; }
  #selected-info { min-height: 28px; }
  .sel-text span { display: none; }
