#quest-list li .qbox { width: 12px; height: 12px; border-radius: 3px; border: 1px solid rgba(231,195,122,.4); display: grid; place-items: center; flex: none; margin-top: 1px; }
#quest-list li .qtext { flex: 1; min-width: 0; }
#quest-list li .qprog { color: var(--gold); font-size: 9.5px; margin-left: 3px; white-space: nowrap; }
#quest-list li .qreward { display: flex; gap: 4px; margin-top: 2px; font-size: 9px; color: #a79d89; }
#quest-list li .qreward .ic { font-size: 10px; color: var(--gold-2); }
