#quest-list li.complete .qbox::after { content: "✓"; font-size: 9px; color: #b8d69e; }
#rank-progress { margin-top: 8px; padding-top: 7px; border-top: 1px solid rgba(231,195,122,.12); }
.rp-track { height: 4px; border-radius: 99px; background: rgba(255,255,255,.09); overflow: hidden; }
.rp-track i { display: block; height: 100%; width: 0%; border-radius: inherit; background: linear-gradient(90deg, #8b6c3c, #e2bd75); transition: width .4s; }
#rp-label { display: block; margin-top: 4px; font-size: 8.5px; letter-spacing: .07em; text-transform: uppercase; color: #8f8674; }

#hero-hud {
  position: absolute;
  left: calc(12px + var(--safe-l));
  bottom: calc(176px + var(--safe-b));
  z-index: 12;
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 6px 10px 6px 6px;
  border-radius: 10px;
  background: linear-gradient(160deg, rgba(28,31,34,.9), rgba(13,15,17,.86));
  border: 1px solid rgba(231,195,122,.26);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  box-shadow: 0 6px 20px rgba(0,0,0,.35);
  max-width: 220px;
}
#hero-focus {
  width: 35px; height: 35px; flex: none;
  border-radius: 8px;
  display: grid; place-items: center;
  color: #f0d99e;
  background: radial-gradient(circle at 40% 30%, #4a6c8d, #23384c);
  border: 1px solid rgba(231,195,122,.4);
}
#hero-focus .ic { font-size: 20px; }
.hero-info { min-width: 0; }
.hero-name { display: block; font-family: var(--serif); font-size: 10.5px; letter-spacing: .04em; color: #e9dcc1; white-space: nowrap; }
.hero-track { width: 92px; height: 5px; border-radius: 99px; background: rgba(255,255,255,.12); overflow: hidden; margin-top: 3px; }
.hero-track i { display: block; height: 100%; width: 100%; border-radius: inherit; background: linear-gradient(90deg, #6393ba, #a8d0e8); transition: width .2s; }
#hero-state { font-size: 8px; text-transform: uppercase; letter-spacing: .1em; color: #8f8674; align-self: flex-end; white-space: nowrap; }
#hero-hud.dead #hero-focus { filter: grayscale(1) brightness(.6); }
#hero-hud.dead .hero-track i { background: #6b4a44; }

#wave-callout {
  position: absolute;
  left: 50%; top: 38%;
  transform: translate(-50%, -50%);
  z-index: 20;
  text-align: center;
  pointer-events: none;
  width: min(600px, 90vw);
  opacity: 0;
  animation: callout 3.8s ease forwards;
}
.wc-kicker { font-size: 10px; letter-spacing: .32em; text-transform: uppercase; color: #d9a78f; margin-bottom: 4px; text-shadow: 0 2px 10px #000; }
.wc-title { font-family: var(--serif); font-size: clamp(34px, 6vw, 58px); letter-spacing: .08em; color: #f7ecd5; text-shadow: 0 6px 30px rgba(0,0,0,.75); line-height: 1; }
.wc-sub { margin-top: 6px; font-family: var(--serif); font-size: 13px; color: #c8b99c; letter-spacing: .05em; text-shadow: 0 2px 10px #000; }
@keyframes callout {
  0% { opacity: 0; transform: translate(-50%, -46%) scale(.97); }
  12% { opacity: 1; transform: translate(-50%, -50%) scale(1); }
  78% { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -54%) scale(1.01); }
}

#hint-banner {
  position: absolute;
  left: 50%; top: calc(76px + var(--safe-t));
  transform: translateX(-50%);
  z-index: 13;
  padding: 8px 15px;
  border-radius: 999px;
  background: rgba(18,21,24,.88);
  border: 1px solid rgba(231,195,122,.32);
  color: #ddcfb6;
  font-size: 11.5px;
  letter-spacing: .02em;
  white-space: nowrap;
  box-shadow: 0 6px 20px rgba(0,0,0,.4);
  animation: hintIn .35s ease both;
  pointer-events: none;
}
@keyframes hintIn { from { opacity: 0; transform: translate(-50%, -6px); } to { opacity: 1; transform: translate(-50%, 0); } }

