export class FloatingText {
  constructor(scene) {
    this.scene = scene;
    this.items = [];
    this.canvas = document.createElement('canvas');
    this.canvas.width = 256;
    this.canvas.height = 64;
    this.ctx = this.canvas.getContext('2d');
  }
  spawn(text, pos, color = '#f2e6ca', size = 30) {
    const c = document.createElement('canvas');
    c.width = 256; c.height = 64;
    const g = c.getContext('2d');
    g.font = `700 ${size}px Georgia, serif`;
    g.textAlign = 'center';
    g.textBaseline = 'middle';
    g.lineWidth = 6;
    g.strokeStyle = 'rgba(10,12,14,.65)';
    g.strokeText(text, 128, 34);
    g.fillStyle = color;
    g.fillText(text, 128, 34);
    const tex = new THREE.CanvasTexture(c);
    tex.colorSpace = THREE.SRGBColorSpace;
    const mat = new THREE.SpriteMaterial({ map: tex, transparent: true, depthTest: false, depthWrite: false });
    const sprite = new THREE.Sprite(mat);
    sprite.position.copy(pos);
    sprite.scale.set(4, 1, 1);
    sprite.renderOrder = 50;
    this.scene.add(sprite);
    this.items.push({ sprite, life: 1.4, vy: 1.4, mat, tex });
  }
  update(dt) {
    for (let i = this.items.length - 1; i >= 0; i--) {
      const it = this.items[i];
      it.life -= dt;
      it.sprite.position.y += it.vy * dt;
      it.vy *= 0.97;
      it.mat.opacity = Math.max(0, Math.min(1, it.life * 1.8));
      if (it.life <= 0) {
        this.scene.remove(it.sprite);
        it.mat.dispose(); it.tex.dispose();
        this.items.splice(i, 1);
      }
    }
  }
}

// Tiny procedural sound engine — no external assets.
export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.enabled = localStorage.getItem('steelstone_sound') !== 'off';
    this.started = false;
    this.wind = null;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.enabled ? 0.5 : 0;
    this.master.connect(this.ctx.destination);
    this.noiseBuffer = this.makeNoise(2.5);
    this.startWind();
    this.started = true;
  }

  makeNoise(seconds = 2) {
    const ctx = this.ctx;
    const buf = ctx.createBuffer(1, ctx.sampleRate * seconds, ctx.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
    return buf;
  }

  startWind() {
    if (!this.ctx) return;
    const ctx = this.ctx;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.loop = true;
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 320;
    filter.Q.value = 0.6;
    const gain = ctx.createGain();
    gain.gain.value = 0.05;
    src.connect(filter).connect(gain).connect(this.master);
    src.start();
    this.wind = { src, filter, gain };
    // slow LFO on wind
    const lfo = ctx.createOscillator();
    lfo.frequency.value = 0.07;
    const lfoGain = ctx.createGain();
    lfoGain.gain.value = 120;
    lfo.connect(lfoGain).connect(filter.frequency);
    lfo.start();
    this.windLfo = lfo;
  }

  setEnabled(on) {
    this.enabled = on;
    localStorage.setItem('steelstone_sound', on ? 'on' : 'off');
    if (this.master) this.master.gain.setTargetAtTime(on ? 0.5 : 0, this.ctx.currentTime, 0.05);
  }

  toggle() { this.setEnabled(!this.enabled); return this.enabled; }

  tone(freq, dur = 0.15, type = 'sine', gain = 0.1, opts = {}) {
    if (!this.ctx || !this.enabled) return;
    const ctx = this.ctx;
    const t = ctx.currentTime + (opts.delay || 0);
    const o = ctx.createOscillator();
    const g = ctx.createGain();
    o.type = type;
    o.frequency.setValueAtTime(freq, t);
    if (opts.slide) o.frequency.exponentialRampToValueAtTime(Math.max(30, opts.slide), t + dur);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + Math.min(0.02, dur * 0.2));
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    const pan = ctx.createStereoPanner ? ctx.createStereoPanner() : null;
    if (pan) { pan.pan.value = opts.pan || 0; o.connect(g).connect(pan).connect(this.master); }
    else o.connect(g).connect(this.master);
    o.start(t); o.stop(t + dur + 0.05);
  }

  noise(dur = 0.2, freq = 1400, gain = 0.1, opts = {}) {
    if (!this.ctx || !this.enabled) return;
    const ctx = this.ctx;
    const t = ctx.currentTime + (opts.delay || 0);
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const filter = ctx.createBiquadFilter();
    filter.type = opts.type || 'bandpass';
    filter.frequency.setValueAtTime(freq, t);
    if (opts.slide) filter.frequency.exponentialRampToValueAtTime(Math.max(60, opts.slide), t + dur);
    filter.Q.value = opts.q ?? 0.8;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(filter).connect(g).connect(this.master);
    src.start(t); src.stop(t + dur + 0.05);
  }

  click() { this.tone(320, 0.06, 'triangle', 0.045); }
  select() { this.tone(440, 0.07, 'sine', 0.05); this.tone(660, 0.08, 'sine', 0.03, { delay: 0.03 }); }
  error() { this.tone(180, 0.12, 'square', 0.045, { slide: 120 }); }
  build() {
    this.noise(0.18, 700, 0.11, { type: 'lowpass' });
    this.tone(110, 0.18, 'triangle', 0.09, { slide: 70 });
    this.tone(260, 0.08, 'square', 0.025, { delay: 0.02 });
  }
  place() { this.tone(140, 0.12, 'triangle', 0.07, { slide: 95 }); }
  upgrade() {
    [523, 659, 784, 1046].forEach((f, i) => this.tone(f, 0.22, 'triangle', 0.05, { delay: i * 0.055 }));
    this.noise(0.5, 2400, 0.02, { type: 'highpass' });
  }
  raze() { this.noise(0.35, 400, 0.14, { type: 'lowpass', slide: 90 }); this.tone(80, 0.3, 'sawtooth', 0.05, { slide: 45 }); }
  arrow() { this.noise(0.09, 2400, 0.035, { type: 'highpass' }); }
  bolt() { this.noise(0.14, 900, 0.07, { type: 'bandpass' }); this.tone(180, 0.1, 'sawtooth', 0.03, { slide: 90 }); }
  hit() { this.noise(0.07, 800, 0.05, { type: 'bandpass' }); }
  sword() { this.noise(0.1, 1800, 0.04, { type: 'highpass' }); this.tone(240, 0.06, 'triangle', 0.02); }
  boom() {
    this.noise(0.7, 250, 0.26, { type: 'lowpass', slide: 60 });
    this.tone(65, 0.6, 'sine', 0.2, { slide: 32 });
  }
  horn() {
    [196, 247, 294].forEach((f, i) => {
      this.tone(f, 1.1, 'sawtooth', 0.035, { delay: i * 0.03 });
      this.tone(f * 1.005, 1.0, 'triangle', 0.03, { delay: i * 0.03 });
    });
  }
  wave() {
    this.tone(130, 1.3, 'sawtooth', 0.06, { slide: 98 });
    this.tone(196, 1.2, 'triangle', 0.04);
    this.noise(1.2, 300, 0.05, { type: 'lowpass' });
  }
  victory() {
    [523, 659, 784, 1046, 1318].forEach((f, i) => this.tone(f, 0.7, 'triangle', 0.06, { delay: i * 0.12 }));
    this.tone(262, 1.8, 'sine', 0.05, { delay: 0.24 });
  }
  defeat() {
    [330, 294, 247, 196].forEach((f, i) => this.tone(f, 0.6, 'sawtooth', 0.045, { delay: i * 0.18, slide: f * 0.96 }));
  }
  cooldownReady() { this.tone(880, 0.09, 'sine', 0.03); this.tone(1320, 0.12, 'sine', 0.02, { delay: 0.05 }); }
  hero() { this.tone(392, 0.16, 'triangle', 0.045); this.tone(587, 0.2, 'triangle', 0.035, { delay: 0.05 }); }
}

import * as THREE from 'three';
import { GRID, CELL, HALF, SPAWNS } from './defs.js';
import { material, mesh, box, cyl, cone, sphere, rand, makeBanner, COLORS } from './util.js';

export function createWorld(scene, renderer) {
  const isMobile = Math.min(window.innerWidth, window.innerHeight) < 700;
  const timeUniform = { value: 0 };
  const animated = [];

  scene.fog = new THREE.Fog(0xb9c9c4, 150, 330);

  // ---------- lights ----------
  const hemi = new THREE.HemisphereLight(0xbfd9ee, 0x596344, 1.15);
  scene.add(hemi);
  const sun = new THREE.DirectionalLight(0xffe4b8, 2.35);
  sun.position.set(-48, 62, 34);
  sun.castShadow = true;
  const sc = sun.shadow.camera;
  sc.left = -62; sc.right = 62; sc.top = 62; sc.bottom = -62;
  sc.near = 1; sc.far = 180;
  sun.shadow.mapSize.set(isMobile ? 1024 : 2048, isMobile ? 1024 : 2048);
  sun.shadow.bias = -0.0007;
  sun.shadow.normalBias = 0.04;
  scene.add(sun);
  scene.add(sun.target);
  const rim = new THREE.DirectionalLight(0x9bc2d8, 0.45);
  rim.position.set(40, 20, -45);
  scene.add(rim);

  // ---------- sky ----------
  const skyMat = new THREE.ShaderMaterial({
    side: THREE.BackSide,
    depthWrite: false,
    uniforms: {
      uTop: { value: new THREE.Color(0x3d78b0) },
      uMid: { value: new THREE.Color(0x9ec6dd) },
      uHorizon: { value: new THREE.Color(0xf1d6a8) },
      uSun: { value: new THREE.Vector3(-48, 62, 34).normalize() },
    },
    vertexShader: `
      varying vec3 vPos;
      void main() {
        vPos = normalize(position);
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }`,
    fragmentShader: `
      uniform vec3 uTop; uniform vec3 uMid; uniform vec3 uHorizon; uniform vec3 uSun;
      varying vec3 vPos;
      void main() {
        float h = clamp(vPos.y, -0.15, 1.0);
        vec3 col = mix(uHorizon, uMid, smoothstep(-0.02, 0.28, h));
        col = mix(col, uTop, smoothstep(0.25, 0.85, h));
        float sunDot = max(dot(normalize(vPos), normalize(uSun)), 0.0);
        col += vec3(1.0, 0.78, 0.48) * pow(sunDot, 90.0) * 0.65;
        col += vec3(1.0, 0.86, 0.64) * pow(sunDot, 8.0) * 0.18;
        gl_FragColor = vec4(col, 1.0);
      }`,
  });
  const sky = new THREE.Mesh(new THREE.SphereGeometry(360, 24, 16), skyMat);
  sky.frustumCulled = false;
  scene.add(sky);

  // ---------- island ----------
  const top = buildIslandTop();
  scene.add(top);

  const cliffs = buildCliffs();
  scene.add(cliffs);

  // grassy lip + shoreline foam
  const foamGeo = new THREE.RingGeometry(47.5, 62, 64);
  const foamMat = new THREE.MeshBasicMaterial({ color: 0xd7e8df, transparent: true, opacity: 0.16, side: THREE.DoubleSide, depthWrite: false });
  const foam = new THREE.Mesh(foamGeo, foamMat);
  foam.rotation.x = -Math.PI / 2;
  foam.position.y = -7.32;
  scene.add(foam);

  // ---------- water ----------
  const waterMat = new THREE.ShaderMaterial({
    uniforms: { uTime: timeUniform, uDeep: { value: new THREE.Color(0x245b70) }, uShallow: { value: new THREE.Color(0x4f96a3) }, uSun: { value: new THREE.Vector3(-48, 62, 34) } },
    vertexShader: `
      uniform float uTime;
      varying vec3 vWorld;
      varying float vWave;
      void main() {
        vec3 p = position;
        float w = sin(p.x * 0.11 + uTime * 0.55) * 0.14 + sin(p.y * 0.18 - uTime * 0.42) * 0.1 + sin((p.x + p.y) * 0.27 + uTime * 0.9) * 0.05;
        p.z += w;
        vWave = w;
        vec4 world = modelMatrix * vec4(p, 1.0);
        vWorld = world.xyz;
        gl_Position = projectionMatrix * viewMatrix * world;
      }`,
    fragmentShader: `
      uniform float uTime; uniform vec3 uDeep; uniform vec3 uShallow; uniform vec3 uSun;
      varying vec3 vWorld; varying float vWave;
      void main() {
        float bands = sin(vWorld.x * 0.32 + uTime * 0.7) * sin(vWorld.z * 0.27 - uTime * 0.5);
        vec3 col = mix(uDeep, uShallow, 0.35 + bands * 0.13 + vWave * 0.35);
        vec3 viewDir = normalize(cameraPosition - vWorld);
        float fres = pow(1.0 - max(viewDir.y, 0.0), 3.0);
        col = mix(col, vec3(0.58, 0.79, 0.83), fres * 0.32);
        vec3 sunDir = normalize(uSun);
        float glint = pow(max(dot(reflect(-sunDir, vec3(0.0, 1.0, 0.0)), viewDir), 0.0), 72.0);
        col += vec3(1.0, 0.86, 0.62) * glint * 0.45;
        gl_FragColor = vec4(col, 1.0);
      }`,
  });
  const water = new THREE.Mesh(new THREE.PlaneGeometry(520, 520, 96, 96), waterMat);
  water.rotation.x = -Math.PI / 2;
  water.position.y = -7.65;
  water.receiveShadow = false;
  scene.add(water);

  // ---------- trees, rocks, flowers ----------
  const treePositions = [];
  let guard = 0;
  while (treePositions.length < (isMobile ? 48 : 74) && guard++ < 1200) {
    const a = Math.random() * Math.PI * 2;
    const r = rand(34, 46.5);
    const x = Math.cos(a) * r;
    const z = Math.sin(a) * r;
    if (Math.abs(x) < 32 && Math.abs(z) < 32) continue;
    if (SPAWNS.some(s => Math.hypot(x - s.x, z - s.z) < 8)) continue;
    treePositions.push({ x, z, s: rand(0.75, 1.3) });
  }
  const trunkGeo = new THREE.CylinderGeometry(0.16, 0.28, 2.2, 5);
  const trunkMesh = new THREE.InstancedMesh(trunkGeo, material(0x6a4a2d, { roughness: 0.95 }), treePositions.length);
  const leafGeo = new THREE.IcosahedronGeometry(1.7, 0);
  const leafMesh = new THREE.InstancedMesh(leafGeo, material(0x5c8748, { roughness: 0.95 }), treePositions.length * 2);
  const dummy = new THREE.Object3D();
  const treeColors = [0x5c8748, 0x6e9852, 0x4f7b42, 0x7aa15a];
  treePositions.forEach((t, i) => {
    dummy.position.set(t.x, 1.1 * t.s, t.z);
    dummy.rotation.set(0, Math.random() * 6, 0);
    dummy.scale.setScalar(t.s);
    dummy.updateMatrix();
    trunkMesh.setMatrixAt(i, dummy.matrix);
    const c = new THREE.Color(treeColors[i % treeColors.length]);
    leafMesh.setColorAt(i * 2, c);
    dummy.position.set(t.x, 2.9 * t.s, t.z);
    dummy.scale.set(t.s * rand(0.9, 1.25), t.s * rand(0.95, 1.3), t.s * rand(0.9, 1.25));
    dummy.updateMatrix();
    leafMesh.setMatrixAt(i * 2, dummy.matrix);
    dummy.position.set(t.x + 0.3, 4.1 * t.s, t.z - 0.1);
    dummy.scale.setScalar(t.s * rand(0.65, 0.9));
    dummy.updateMatrix();
    leafMesh.setMatrixAt(i * 2 + 1, dummy.matrix);
    leafMesh.setColorAt(i * 2 + 1, c);
  });
  trunkMesh.castShadow = true; trunkMesh.receiveShadow = true;
  leafMesh.castShadow = true; leafMesh.receiveShadow = true;
  leafMesh.instanceColor.needsUpdate = true;
  scene.add(trunkMesh, leafMesh);

  const rockCount = 30;
  const rockMesh = new THREE.InstancedMesh(new THREE.DodecahedronGeometry(1, 0), material(0x948d80, { roughness: 0.95 }), rockCount);
  for (let i = 0; i < rockCount; i++) {
    const a = Math.random() * Math.PI * 2;
    const r = rand(31, 46);
    dummy.position.set(Math.cos(a) * r, rand(0.1, 0.4), Math.sin(a) * r);
    dummy.rotation.set(Math.random() * 3, Math.random() * 3, Math.random() * 3);
    dummy.scale.set(rand(0.6, 1.9), rand(0.5, 1.1), rand(0.6, 1.7));
    dummy.updateMatrix();
    rockMesh.setMatrixAt(i, dummy.matrix);
  }
  rockMesh.castShadow = true; rockMesh.receiveShadow = true;
  scene.add(rockMesh);

  // flowers outside the building grid
  const flowerCount = 150;
  const flowerMesh = new THREE.InstancedMesh(new THREE.IcosahedronGeometry(0.11, 0), new THREE.MeshStandardMaterial({ roughness: 0.9, vertexColors: false }), flowerCount);
  const flowerColors = [0xe8c76e, 0xdf8a8a, 0xc9b6e6, 0xf2e6c4];
  for (let i = 0; i < flowerCount; i++) {
    const a = Math.random() * Math.PI * 2;
    const r = rand(31, 46);
    const x = Math.cos(a) * r, z = Math.sin(a) * r;
    dummy.position.set(x, 0.18 + Math.random() * 0.08, z);
    dummy.rotation.set(0, Math.random() * 3, 0);
    dummy.scale.setScalar(rand(0.7, 1.6));
    dummy.updateMatrix();
    flowerMesh.setMatrixAt(i, dummy.matrix);
    flowerMesh.setColorAt(i, new THREE.Color(flowerColors[i % flowerColors.length]));
  }
  flowerMesh.instanceColor.needsUpdate = true;
  scene.add(flowerMesh);

  // ---------- clouds ----------
  const clouds = [];
  const cloudMat = new THREE.MeshStandardMaterial({ color: 0xf4efe4, roughness: 1, transparent: true, opacity: 0.92, flatShading: true });
  for (let i = 0; i < 9; i++) {
    const g = new THREE.Group();
    const n = 3 + (i % 3);
    for (let k = 0; k < n; k++) {
      const s = rand(2.4, 5.2);
      const m = new THREE.Mesh(new THREE.IcosahedronGeometry(s, 1), cloudMat);
      m.position.set(rand(-4, 4), rand(-0.7, 0.7), rand(-3, 3));
      m.scale.y = rand(0.45, 0.7);
      g.add(m);
    }
    const a = (i / 9) * Math.PI * 2 + rand(-0.3, 0.3);
    const r = rand(85, 170);
    g.position.set(Math.cos(a) * r, rand(26, 44), Math.sin(a) * r);
    g.scale.setScalar(rand(0.7, 1.4));
    g.userData.speed = rand(0.4, 1.1);
    scene.add(g);
    clouds.push(g);
  }

  // ---------- distant isles ----------
  for (let i = 0; i < 3; i++) {
    const a = 1.1 + i * 2.1;
    const r = 150 + i * 25;
    const g = new THREE.Group();
    const c = cone(g, rand(10, 16), rand(9, 15), 0x6b7d63, 0, 2, 0, { seg: 7, matOpts: { roughness: 1 } });
    c.scale.z = 1.4;
    const topDisc = cyl(g, 9, 11, 1, 0x6f9456, 0, 7, 0, { seg: 7 });
    topDisc.scale.z = 1.3;
    const t = cone(g, 2.6, 5, 0x4e7a44, rand(-2, 2), 11, rand(-2, 2), { seg: 5 });
    g.position.set(Math.cos(a) * r, -8, Math.sin(a) * r);
    g.rotation.y = rand(0, 5);
    scene.add(g);
  }

  // ---------- enemy camps ----------
  const camps = SPAWNS.map((s, idx) => makeCamp(scene, s, idx));

  // ---------- birds ----------
  const birds = [];
  const birdMat = new THREE.LineBasicMaterial({ color: 0x2c3236, transparent: true, opacity: 0.7 });
  for (let i = 0; i < 4; i++) {
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute([-0.8, 0.3, 0, 0, 0, 0, 0.8, 0.3, 0], 3));
    const line = new THREE.Line(geo, birdMat);
    line.userData = { a: Math.random() * 6, r: rand(55, 85), y: rand(18, 30), speed: rand(0.03, 0.07) };
    scene.add(line);
    birds.push(line);
  }

  // ---------- ambient animations ----------
  function update(dt, t) {
    timeUniform.value = t;
    foamMat.opacity = 0.13 + Math.sin(t * 0.5) * 0.035;
    for (const c of clouds) {
      c.position.x += c.userData.speed * dt;
      if (c.position.x > 200) c.position.x = -200;
    }
    for (const b of birds) {
      const u = b.userData;
      u.a += u.speed * dt;
      b.position.set(Math.cos(u.a) * u.r, u.y + Math.sin(t * 0.7 + u.a) * 1.5, Math.sin(u.a) * u.r);
      b.rotation.y = -u.a + Math.PI / 2;
    }
    for (const camp of camps) camp.update(dt, t);
  }

  return { update, sun, water, camps, top, isMobile };
}

function buildIslandTop() {
  const seg = 72;
  const rings = 12;
  const positions = [];
  const colors = [];
  const indices = [];
  const rad = (a) => 49.5 + Math.sin(a * 3.1) * 1.4 + Math.sin(a * 5.7 + 1.1) * 0.9 + Math.sin(a * 9.3 + 2) * 0.45;

  positions.push(0, 0.02, 0);
  colors.push(0.44, 0.58, 0.31);
  for (let r = 1; r <= rings; r++) {
    const radF = r / rings;
    for (let s = 0; s < seg; s++) {
      const a = (s / seg) * Math.PI * 2;
      const rr = rad(a) * radF;
      const x = Math.cos(a) * rr;
      const z = Math.sin(a) * rr;
      // gentle rise only near the very edge
      const edge = Math.max(0, (radF - 0.88) / 0.12);
      const y = 0.02 + edge * edge * 0.55 + (Math.sin(a * 7.1) * 0.5 + 0.5) * 0.1 * edge;
      positions.push(x, y, z);
      const n = Math.sin(x * 0.24 + z * 0.13) * 0.5 + 0.5;
      const n2 = Math.sin(x * 0.08 - z * 0.22 + 1.4) * 0.5 + 0.5;
      const c = new THREE.Color(0x6e9751).lerp(new THREE.Color(0x84a965), n * 0.55 + n2 * 0.25);
      colors.push(c.r, c.g, c.b);
    }
  }
  for (let s = 0; s < seg; s++) {
    indices.push(0, 1 + s, 1 + ((s + 1) % seg));
  }
  for (let r = 1; r < rings; r++) {
    for (let s = 0; s < seg; s++) {
      const a = 1 + (r - 1) * seg + s;
      const b = 1 + (r - 1) * seg + ((s + 1) % seg);
      const c = 1 + r * seg + s;
      const d = 1 + r * seg + ((s + 1) % seg);
      indices.push(a, c, b, b, c, d);
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  g.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
  g.setIndex(indices);
  g.computeVertexNormals();
  const mat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.97, metalness: 0 });
  const m = new THREE.Mesh(g, mat);
  m.receiveShadow = true;
  return m;
}

function buildCliffs() {
  const seg = 72;
  const rings = [
    { r: 1.0, y: 0.02, color: new THREE.Color(0x747d4f) },
    { r: 0.99, y: -1.6, color: new THREE.Color(0x8c775e) },
    { r: 1.02, y: -4.6, color: new THREE.Color(0x76614c) },
    { r: 0.96, y: -8.2, color: new THREE.Color(0x665542) },
    { r: 0.9, y: -13.5, color: new THREE.Color(0x4d4538) },
  ];
  const positions = [];
  const colors = [];
  const indices = [];
  const rad = (a) => 49.5 + Math.sin(a * 3.1) * 1.4 + Math.sin(a * 5.7 + 1.1) * 0.9 + Math.sin(a * 9.3 + 2) * 0.45;
  for (let r = 0; r < rings.length; r++) {
    for (let s = 0; s < seg; s++) {
      const a = (s / seg) * Math.PI * 2;
      const rr = rad(a) * rings[r].r * (1 + Math.sin(a * 11 + r * 1.7) * 0.012);
      positions.push(Math.cos(a) * rr, rings[r].y, Math.sin(a) * rr);
      const c = rings[r].color.clone();
      const v = Math.sin(a * 9 + r) * 0.06;
      c.offsetHSL(0, 0, v);
      colors.push(c.r, c.g, c.b);
    }
  }
  for (let r = 0; r < rings.length - 1; r++) {
    for (let s = 0; s < seg; s++) {
      const a = r * seg + s;
      const b = r * seg + ((s + 1) % seg);
      const c = (r + 1) * seg + s;
      const d = (r + 1) * seg + ((s + 1) % seg);
      indices.push(a, b, c, b, d, c);
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  g.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
  g.setIndex(indices);
  g.computeVertexNormals();
  const mat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 1, flatShading: true });
  const m = new THREE.Mesh(g, mat);
  m.receiveShadow = true;
  return m;
}

function makeCamp(scene, spawn, idx) {
  const g = new THREE.Group();
  g.position.set(spawn.x, 0, spawn.z);
  g.rotation.y = Math.atan2(-spawn.x, -spawn.z) + Math.PI;
  const banner = makeBanner('red', 1.05);
  banner.group.position.set(4.5, 0, 1);
  g.add(banner.group);
  const tentColors = [0x6f5b46, 0x5d4c3b, 0x7a644c];
  for (let i = 0; i < 3; i++) {
    const t = new THREE.Group();
    t.position.set(-3.5 + i * 3.4, 0, -1.2 + (i % 2) * 2.5);
    t.rotation.y = rand(-0.5, 0.5);
    cone(t, 1.9, 2.7, tentColors[i], 0, 1.35, 0, { seg: 4 });
    box(t, 0.9, 1.45, 0.06, 0x34281d, 0, 0.7, 1.05);
    g.add(t);
  }
  const fire = new THREE.Group();
  fire.position.set(0, 0, 3.5);
  for (let i = 0; i < 5; i++) {
    const a = (i / 5) * Math.PI * 2;
    sphere(fire, 0.34, 0x6b6258, Math.cos(a) * 0.8, 0.2, Math.sin(a) * 0.8);
  }
  const flame = cone(fire, 0.4, 1.2, 0xff9b4a, 0, 0.75, 0, { seg: 5 });
  flame.material = new THREE.MeshBasicMaterial({ color: 0xffa24a, transparent: true, opacity: 0.9 });
  g.add(fire);
  const glow = new THREE.PointLight(0xff8c3a, 6, 12, 2);
  glow.position.set(0, 1.2, 3.5);
  g.add(glow);
  scene.add(g);
  return {
    group: g,
    update(dt, t) {
      flame.scale.setScalar(0.85 + Math.sin(t * 9 + idx) * 0.16);
      glow.intensity = 5 + Math.sin(t * 12 + idx * 2) * 1.6;
      banner.flag.rotation.y = Math.sin(t * 2.1 + idx) * 0.18;
    },
  };
}

import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import {
  GRID, CELL, HALF, KEEP_I, KEEP_J, KEEP_W, KEEP_H,
  STRUCTURES, maxHpFor, productionFor, happinessFor, workerCostFor,
  populationFor, garrisonFor, cellKey,
} from './defs.js';
import {
  material, mesh, box, cyl, cone, sphere, plane, gableRoof, addCrenellations,
  makeBanner, makeRoadTexture, rand, COLORS, basic,
} from './util.js';
import { dustBurst, sparkBurst, fireBurst } from './fx.js';

const wallVariantCache = new Map();

function coloredBoxGeo(w, h, d, x, y, z, color) {
  const g = new THREE.BoxGeometry(w, h, d);
  g.translate(x, y, z);
  const c = new THREE.Color(color);
  const count = g.attributes.position.count;
  const arr = new Float32Array(count * 3);
  for (let i = 0; i < count; i++) { arr[i * 3] = c.r; arr[i * 3 + 1] = c.g; arr[i * 3 + 2] = c.b; }
  g.setAttribute('color', new THREE.BufferAttribute(arr, 3));
  return g;
}

function wallGeometry(mask) {
  if (wallVariantCache.has(mask)) return wallVariantCache.get(mask);
  // bits: 1=N(-z) 2=E(+x) 4=S(+z) 8=W(-x)
  const parts = [];
  parts.push(coloredBoxGeo(CELL * 1.01, 0.55, CELL * 1.01, 0, 0.275, 0, 0xb7ae9a));
  parts.push(coloredBoxGeo(CELL * 0.98, 2.1, CELL * 0.98, 0, 1.6, 0, 0xd6cdb8));
  parts.push(coloredBoxGeo(CELL * 1.00, 0.22, CELL * 1.00, 0, 2.76, 0, 0xc8bfab));
  const colors = [0xe4dbc6, 0xdcd3be];
  const addMerlonRow = (side, idx) => {
    const w = side === 'n' || side === 's' ? CELL : 0.34;
    const d = side === 'n' || side === 's' ? 0.34 : CELL;
    const x = side === 'e' ? CELL / 2 - 0.09 : side === 'w' ? -CELL / 2 + 0.09 : 0;
    const z = side === 'n' ? -CELL / 2 + 0.09 : side === 's' ? CELL / 2 - 0.09 : 0;
    parts.push(coloredBoxGeo(w, 0.5, d, x, 3.1, z, colors[idx % 2]));
    // inner lower parapet lip
    const lipW = side === 'n' || side === 's' ? CELL : 0.18;
    const lipD = side === 'n' || side === 's' ? 0.18 : CELL;
    const lx = side === 'e' ? CELL / 2 - 0.36 : side === 'w' ? -CELL / 2 + 0.36 : 0;
    const lz = side === 'n' ? -CELL / 2 + 0.36 : side === 's' ? CELL / 2 - 0.36 : 0;
    parts.push(coloredBoxGeo(lipW, 0.3, lipD, lx, 2.93, lz, 0xcfc6b2));
    // crenellations
    const n = 4;
    for (let k = 0; k < n; k++) {
      const t = -CELL / 2 + (CELL / (n + 0.2)) * (k + 0.6) + 0.1;
      if (side === 'n' || side === 's') {
        parts.push(coloredBoxGeo(0.4, 0.48, 0.32, t, 3.58, z, colors[(k + idx) % 2]));
      } else {
        parts.push(coloredBoxGeo(0.32, 0.48, 0.4, x, 3.58, t, colors[(k + idx) % 2]));
      }
    }
  };
  let idx = 0;
  if (!(mask & 1)) addMerlonRow('n', idx++);
  if (!(mask & 2)) addMerlonRow('e', idx++);
  if (!(mask & 4)) addMerlonRow('s', idx++);
  if (!(mask & 8)) addMerlonRow('w', idx++);
  // corner buttresses on fully exposed pillars
  if (mask === 0) {
    for (const [sx, sz] of [[-1, -1], [1, -1], [1, 1], [-1, 1]]) {
      parts.push(coloredBoxGeo(0.38, 2.7, 0.38, sx * (CELL / 2 - 0.02), 1.35, sz * (CELL / 2 - 0.02), 0xc7bda8));
    }
  }
  const g = mergeGeometries(parts, false);
  parts.forEach(p => p.dispose());
  wallVariantCache.set(mask, g);
  return g;
}

function makeFlagTextureMap() { return null; }

export class Castle {
  constructor(scene, fx, audio) {
    this.scene = scene;
    this.fx = fx;
    this.audio = audio;
    this.game = null;
    this.structures = [];
    this.byId = new Map();
    this.nextId = 1;
    this.cells = new Array(GRID * GRID).fill(null);
    this.roads = new Map();
    this.banners = [];
    this.windmills = [];
    this.bonuses = { masonry: 0 };
    this.wallDirty = true;
    this.wallInstances = [];
    this.roadMesh = null;
    this.roadDirty = true;
    this.selection = null;
    this.selectedRing = this.makeSelectionRing();
    this.ghost = this.makeGhost();
    this.fireTimer = 0;
    this.time = 0;

    this.initWalls();
    this.initRoads();
  }

  // ---------------- instanced walls & roads ----------------
  initWalls() {
    const baseMat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.92, metalness: 0.02, flatShading: true });
    for (let mask = 0; mask < 16; mask++) {
      const geo = wallGeometry(mask);
      const m = new THREE.InstancedMesh(geo, baseMat, 260);
      m.count = 0;
      m.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
      m.castShadow = true;
      m.receiveShadow = true;
      m.frustumCulled = false;
      m.userData.mask = mask;
      this.scene.add(m);
      this.wallInstances.push(m);
    }
  }

  initRoads() {
    const tex = makeRoadTexture();
    const mat = new THREE.MeshStandardMaterial({ map: tex, roughness: 0.95, metalness: 0.01 });
    const geo = new THREE.BoxGeometry(CELL * 0.985, 0.11, CELL * 0.985);
    this.roadMesh = new THREE.InstancedMesh(geo, mat, GRID * GRID);
    this.roadMesh.count = 0;
    this.roadMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.roadMesh.receiveShadow = true;
    this.roadMesh.castShadow = false;
    this.roadMesh.frustumCulled = false;
    this.scene.add(this.roadMesh);
  }

  rebuildWalls() {
    const buckets = Array.from({ length: 16 }, () => []);
    for (const st of this.structures) {
      if (st.type !== 'wall') continue;
      buckets[this.wallMask(st.i, st.j)].push(st);
    }
    const dummy = new THREE.Object3D();
    const color = new THREE.Color();
    for (let mask = 0; mask < 16; mask++) {
      const mesh = this.wallInstances[mask];
      const list = buckets[mask];
      mesh.count = list.length;
      list.forEach((st, idx) => {
        const w = this.cellCenter(st.i, st.j);
        dummy.position.set(w.x, 0, w.z);
        dummy.rotation.set(0, 0, 0);
        dummy.scale.set(1, 1, 1);
        dummy.updateMatrix();
        mesh.setMatrixAt(idx, dummy.matrix);
        const dmg = st.hp / st.maxHp;
        const base = 0.78 + ((st.id * 37) % 13) / 60;
        color.setRGB(base * (0.55 + dmg * 0.45), base * (0.5 + dmg * 0.5), base * (0.46 + dmg * 0.5));
        mesh.setColorAt(idx, color);
        st.wallSlot = { mesh, index: idx };
      });
      mesh.instanceMatrix.needsUpdate = true;
      if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
    }
    this.wallDirty = false;
  }

  rebuildRoads() {
    const dummy = new THREE.Object3D();
    let idx = 0;
    for (const road of this.roads.values()) {
      const w = this.cellCenter(road.i, road.j);
      dummy.position.set(w.x, 0.075, w.z);
      dummy.rotation.set(0, 0, 0);
      dummy.scale.set(1, 1, 1);
      dummy.updateMatrix();
      this.roadMesh.setMatrixAt(idx++, dummy.matrix);
    }
    this.roadMesh.count = idx;
    this.roadMesh.instanceMatrix.needsUpdate = true;
    this.roadDirty = false;
  }

  wallMask(i, j) {
    let mask = 0;
    if (this.isWall(i, j - 1)) mask |= 1;
    if (this.isWall(i + 1, j)) mask |= 2;
    if (this.isWall(i, j + 1)) mask |= 4;
    if (this.isWall(i - 1, j)) mask |= 8;
    return mask;
  }

  isWall(i, j) {
    if (i < 0 || j < 0 || i >= GRID || j >= GRID) return false;
    const s = this.cells[cellKey(i, j)];
    return !!s && s.type === 'wall';
  }

  updateWallColor(st) {
    if (!st.wallSlot) return;
    const { mesh, index } = st.wallSlot;
    const color = new THREE.Color();
    const dmg = st.hp / st.maxHp;
    const base = 0.78 + ((st.id * 37) % 13) / 60;
    color.setRGB(base * (0.55 + dmg * 0.45), base * (0.5 + dmg * 0.5), base * (0.46 + dmg * 0.5));
    mesh.setColorAt(index, color);
    if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
  }

  // ---------------- helpers ----------------
  cellCenter(i, j) {
    return { x: (i + 0.5) * CELL - HALF, z: (j + 0.5) * CELL - HALF };
  }

  centerOf(st) {
    return this.cellCenter(st.i + (st.w - 1) / 2, st.j + (st.h - 1) / 2);
  }

  getStructureAt(i, j) {
    if (i < 0 || j < 0 || i >= GRID || j >= GRID) return null;
    return this.cells[cellKey(i, j)];
  }

  getStructureAtWorld(x, z) {
    const i = Math.floor((x + HALF) / CELL);
    const j = Math.floor((z + HALF) / CELL);
    return this.getStructureAt(i, j);
  }

  canPlace(type, i, j) {
    const def = STRUCTURES[type];
    if (!def) return { ok: false, reason: 'Unknown building' };
    if (!def.road && this.structures.length >= 140) return { ok: false, reason: 'Castle is at capacity' };
    if (i < 0 || j < 0 || i + def.w > GRID || j + def.h > GRID) return { ok: false, reason: 'Outside the island' };
    if (def.road) {
      if (this.roads.has(cellKey(i, j))) return { ok: false, reason: 'Road already paved' };
      if (this.cells[cellKey(i, j)]) return { ok: false, reason: 'Blocked by a building' };
      return { ok: true };
    }
    for (let a = 0; a < def.w; a++) {
      for (let b = 0; b < def.h; b++) {
        const s = this.cells[cellKey(i + a, j + b)];
        if (s) return { ok: false, reason: 'Something is already built here' };
      }
    }
    // keep a one-tile breathing space around buildings, except walls/roads
    if (type !== 'wall' && type !== 'gate' && type !== 'tower') {
      for (let a = -1; a <= def.w; a++) {
        for (let b = -1; b <= def.h; b++) {
          if (a >= 0 && a < def.w && b >= 0 && b < def.h) continue;
          const s = this.getStructureAt(i + a, j + b);
          if (s && s.type === 'keep') return { ok: false, reason: 'Leave room around the keep' };
        }
      }
    }
    return { ok: true };
  }

  // ---------------- building / demolishing ----------------
  place(type, i, j, opts = {}) {
    const def = STRUCTURES[type];
    if (!def) return null;
    if (def.road) return this.paintRoad(i, j, opts);
    if (!opts.force) {
      const valid = this.canPlace(type, i, j);
      if (!valid.ok) return null;
    }
    const level = opts.level || 1;
    const st = {
      id: this.nextId++, type, i, j, w: def.w, h: def.h,
      level,
      maxHp: this.calcMaxHp(type, level),
      hp: opts.hp ?? this.calcMaxHp(type, level),
      group: null, bar: null, height: 4,
      aimGroup: null, arm: null, muzzleY: 2,
      smokeTimer: 0, spawnAnim: opts.animate === false ? 1 : 0,
      selected: false,
      wallSlot: null,
    };
    if (opts.hp != null) st.hp = Math.min(st.hp, st.maxHp);
    for (let a = 0; a < def.w; a++) for (let b = 0; b < def.h; b++) this.cells[cellKey(i + a, j + b)] = st;
    // remove roads underneath
    let removedRoad = false;
    for (let a = 0; a < def.w; a++) for (let b = 0; b < def.h; b++) {
      if (this.roads.delete(cellKey(i + a, j + b))) removedRoad = true;
    }
    if (removedRoad) this.roadDirty = true;

    const c = this.centerOf(st);
    st.group = type === 'keep' ? this.buildKeep(st) : this.buildVisual(type, level, st);
    st.group.position.set(c.x, 0, c.z);
    this.scene.add(st.group);
    if (st.spawnAnim < 1) st.group.scale.y = 0.05;

    this.structures.push(st);
    this.byId.set(st.id, st);
    if (type === 'wall') this.wallDirty = true;
    if (type === 'wall' || type === 'gate') this.markNeighborWalls(i, j);
    if (!opts.quiet) {
      dustBurst(this.fx, new THREE.Vector3(c.x, 0.5, c.z), 0xc6b89b, 16, 2.2);
      this.audio?.build();
    }
    if (type === 'keep') this.ensureBar(st, true);
    this.game?.onCityChanged();
    return st;
  }

  paintRoad(i, j, opts = {}) {
    if (i < 0 || j < 0 || i >= GRID || j >= GRID) return null;
    const key = cellKey(i, j);
    if (this.roads.has(key) || this.cells[key]) return null;
    this.roads.set(key, { i, j });
    this.roadDirty = true;
    if (!opts.quiet) this.audio?.place();
    return { type: 'road', i, j };
  }

  removeRoad(i, j, opts = {}) {
    const key = cellKey(i, j);
    if (!this.roads.delete(key)) return false;
    this.roadDirty = true;
    if (!opts.quiet) this.audio?.place();
    return true;
  }

  markNeighborWalls(i, j) {
    this.wallDirty = true;
  }

  removeStructure(st, opts = {}) {
    if (!st || st.type === 'keep') return false;
    const def = STRUCTURES[st.type];
    for (let a = 0; a < st.w; a++) for (let b = 0; b < st.h; b++) {
      const key = cellKey(st.i + a, st.j + b);
      if (this.cells[key] === st) this.cells[key] = null;
    }
    this.structures = this.structures.filter(s => s !== st);
    this.byId.delete(st.id);
    if (st.group) {
      const c = this.centerOf(st);
      dustBurst(this.fx, new THREE.Vector3(c.x, 0.8, c.z), 0xb3a487, 26, 3.2);
      this.scene.remove(st.group);
      st.group.traverse(o => { if (o.isMesh) o.geometry?.dispose?.(); });
    }
    if (st.bar) { this.scene.remove(st.bar.group); st.bar = null; }
    if (st.type === 'wall') {
      this.wallDirty = true;
      // refresh neighbours in next rebuild
    }
    if (this.selection === st) this.select(null);
    if (!opts.quiet) this.audio?.raze();
    this.game?.onCityChanged();
    return true;
  }

  upgrade(st) {
    const def = STRUCTURES[st.type];
    if (!def || !def.maxLevel || st.level >= def.maxLevel) return false;
    st.level++;
    st.maxHp = this.calcMaxHp(st.type, st.level);
    st.hp = st.maxHp;
    const c = this.centerOf(st);
    if (st.group) {
      this.scene.remove(st.group);
      st.group.traverse(o => { if (o.isMesh) o.geometry?.dispose?.(); });
    }
    st.group = this.buildVisual(st.type, st.level, st);
    st.group.position.set(c.x, 0, c.z);
    st.group.scale.y = 0.72;
    this.scene.add(st.group);
    sparkBurst(this.fx, new THREE.Vector3(c.x, st.height * 0.6, c.z), 0xffd27a, 30);
    dustBurst(this.fx, new THREE.Vector3(c.x, 0.5, c.z), 0xd9c9a8, 16, 2.4);
    if (st.bar) this.updateBar(st);
    this.game?.onCityChanged();
    return true;
  }

  calcMaxHp(type, level) {
    return Math.round(maxHpFor(type, level) * (1 + (this.bonuses.masonry || 0)));
  }

  applyMasonry() {
    for (const st of this.structures) {
      const oldMax = st.maxHp;
      const newMax = this.calcMaxHp(st.type, st.level);
      if (newMax > oldMax) {
        st.hp += (newMax - oldMax);
        st.maxHp = newMax;
      }
      this.updateBar(st);
    }
  }

  // ---------------- combat damage ----------------
  damage(st, amount, source) {
    if (!st || st.hp <= 0) return;
    st.hp = Math.max(0, st.hp - amount);
    if (st.type === 'wall') this.updateWallColor(st);
    if (st.type === 'keep') this.ensureBar(st, true);
    if (st.hp > 0) {
      if (st.hp < st.maxHp && !st.bar) this.ensureBar(st, st.type === 'keep');
      this.updateBar(st);
      if (Math.random() < 0.28) {
        const c = this.centerOf(st);
        this.fx.burst(new THREE.Vector3(c.x + rand(-1, 1), 1 + Math.random() * st.height, c.z + rand(-1, 1)), {
          count: 3, color: 0xc9bda3, speed: 2, life: 0.7, size: 5, gravity: -2, drag: 1, up: 0.4, alpha: 0.7,
        });
      }
    } else {
      if (st.type === 'keep') {
        this.game?.onKeepDestroyed();
        return;
      }
      const c = this.centerOf(st);
      dustBurst(this.fx, new THREE.Vector3(c.x, 0.8, c.z), 0xb3a487, 30, 3.6);
      sparkBurst(this.fx, new THREE.Vector3(c.x, 1.4, c.z), 0xd9a24c, 12);
      this.soundCrumble();
      this.removeStructure(st, { quiet: true });
      this.game?.onStructureDestroyed?.(st);
    }
  }

  soundCrumble() {
    this.audio?.raze();
  }

  repairAll(frac) {
    let healed = 0;
    for (const st of this.structures) {
      if (st.hp >= st.maxHp) continue;
      const add = Math.min(st.maxHp - st.hp, st.maxHp * frac);
      st.hp += add;
      healed += add;
      this.updateBar(st);
      if (st.type === 'wall') this.updateWallColor(st);
    }
    if (healed > 0) this.game?.onCityChanged();
    return healed;
  }

  ensureBar(st, force = false) {
    if (st.bar) return st.bar;
    const w = st.type === 'keep' ? 4.4 : Math.max(1.8, Math.min(3, (st.w + st.h) * 0.55));
    const group = new THREE.Group();
    const bgMat = basic(0x15181a, { transparent: true, opacity: 0.72, depthTest: false, depthWrite: false });
    const bg = new THREE.Mesh(new THREE.PlaneGeometry(w, st.type === 'keep' ? 0.34 : 0.2), bgMat);
    bg.renderOrder = 90;
    const fillMat = basic(0x78af5a, { depthTest: false, depthWrite: false });
    const fill = new THREE.Mesh(new THREE.PlaneGeometry(w - 0.08, st.type === 'keep' ? 0.24 : 0.11), fillMat);
    fill.position.z = 0.002;
    fill.renderOrder = 91;
    group.add(bg, fill);
    group.renderOrder = 90;
    group.visible = false;
    this.scene.add(group);
    st.bar = { group, fill, fillMat, bgMat, w, force };
    this.updateBar(st);
    return st.bar;
  }

  updateBar(st) {
    if (!st.bar) return;
    const ratio = Math.max(0, st.hp / st.maxHp);
    st.bar.fill.scale.x = Math.max(0.02, ratio);
    st.bar.fill.position.x = -(st.bar.w - 0.08) * (1 - ratio) / 2;
    const c = st.bar.fillMat.color;
    if (ratio > 0.55) c.setHex(0x78af5a);
    else if (ratio > 0.28) c.setHex(0xd2a84a);
    else c.setHex(0xc45542);
    st.bar.group.visible = st.hp < st.maxHp || st.type === 'keep';
  }

  // ---------------- city stats ----------------
  stats() {
    let capacity = 10;
    let used = 0;
    let happiness = 55;
    const production = { gold: 0, wood: 0, stone: 0, food: 0 };
    let garrison = 0;
    for (const st of this.structures) {
      const def = STRUCTURES[st.type];
      capacity += populationFor(st.type, st.level);
      used += workerCostFor(st.type, st.level);
      happiness += happinessFor(st.type, st.level);
      garrison += garrisonFor(st.type, st.level);
      const prod = productionFor(st.type, st.level);
      for (const [k, v] of Object.entries(prod)) production[k] += v;
    }
    const popPenalty = Math.max(0, (used - 36) * 0.25);
    happiness = Math.max(5, Math.min(100, happiness - popPenalty));
    return { capacity, used, happiness, production, garrison: Math.min(8, garrison) };
  }

  splendor(wavesSurvived = 0) {
    let score = 15 + wavesSurvived * 25 + this.roads.size * 0.2;
    for (const st of this.structures) {
      if (st.type === 'wall') score += 0.8;
      else if (st.type === 'keep') score += 10;
      else score += 5 + st.level * 4 + (STRUCTURES[st.type].tower ? 3 : 0);
    }
    return Math.round(score);
  }

  // ---------------- serialization ----------------
  serialize() {
    return {
      structures: this.structures.map(st => ({ type: st.type, i: st.i, j: st.j, level: st.level, hp: Math.round(st.hp) })),
      roads: [...this.roads.values()].map(r => [r.i, r.j]),
    };
  }

  reset(opts = {}) {
    this.clearAll();
    const st = this.place('keep', KEEP_I, KEEP_J, { force: true, quiet: true, animate: false });
    if (st) st.hp = st.maxHp = this.calcMaxHp('keep', 1);
    this.wallDirty = true;
    this.roadDirty = true;
    return st;
  }

  load(data) {
    this.clearAll();
    if (data?.structures?.length) {
      for (const s of data.structures) {
        const def = STRUCTURES[s.type];
        if (!def) continue;
        this.place(s.type, s.i, s.j, { force: true, quiet: true, animate: false, level: s.level || 1, hp: s.hp });
      }
    }
    if (!this.getStructureAt(KEEP_I, KEEP_J)) {
      this.place('keep', KEEP_I, KEEP_J, { force: true, quiet: true, animate: false });
    }
    if (data?.roads) {
      for (const [i, j] of data.roads) this.paintRoad(i, j, { quiet: true });
    }
    // place() may have removed roads under structures; re-add only valid ones
    this.wallDirty = true;
    this.roadDirty = true;
    this.game?.onCityChanged();
  }

  clearAll() {
    for (const st of [...this.structures]) {
      if (st.group) {
        this.scene.remove(st.group);
        st.group.traverse(o => { if (o.isMesh) o.geometry?.dispose?.(); });
      }
      if (st.bar) this.scene.remove(st.bar.group);
    }
    this.structures = [];
    this.byId.clear();
    this.cells.fill(null);
    this.roads.clear();
    this.banners = [];
    this.windmills = [];
    this.selection = null;
    this.selectedRing.visible = false;
    this.wallDirty = true;
    this.roadDirty = true;
  }

  // ---------------- visual builders ----------------
  buildVisual(type, level, st) {
    switch (type) {
      case 'tower': return this.buildTower(level, st);
      case 'gate': return this.buildGate(level, st);
      case 'house': return this.buildHouse(level, st);
      case 'farm': return this.buildFarm(level, st);
      case 'lumber': return this.buildLumber(level, st);
      case 'quarry': return this.buildQuarry(level, st);
      case 'market': return this.buildMarket(level, st);
      case 'tavern': return this.buildTavern(level, st);
      case 'chapel': return this.buildChapel(level, st);
      case 'garden': return this.buildGarden(level, st);
      case 'barracks': return this.buildBarracks(level, st);
      case 'ballista': return this.buildBallista(level, st);
      case 'catapult': return this.buildCatapult(level, st);
      default: return new THREE.Group();
    }
  }

  addFlag(group, kind = 'blue', scale = 1, x = 0, y = 0, z = 0) {
    const banner = makeBanner(kind, scale);
    banner.group.position.set(x, y, z);
    group.add(banner.group);
    this.banners.push(banner);
    return banner;
  }

  buildTower(level, st) {
    const g = new THREE.Group();
    const h = 6.6 + level * 1.05;
    cyl(g, 2.45, 2.75, 0.7, COLORS.stoneDark, 0, 0.35, 0, { seg: 12 });
    cyl(g, 2.05, 2.35, h, COLORS.stone, 0, 0.7 + h / 2, 0, { seg: 12 });
    cyl(g, 2.55, 2.55, 0.34, COLORS.stoneLight, 0, h + 0.9, 0, { seg: 12 });
    // merlons
    const topY = h + 1.08;
    for (let k = 0; k < 9; k++) {
      const a = (k / 9) * Math.PI * 2;
      box(g, 0.56, 0.58, 0.42, COLORS.stoneLight, Math.cos(a) * 2.28, topY + 0.29, Math.sin(a) * 2.28, { ry: -a });
    }
    // door and windows
    box(g, 1.02, 1.8, 0.16, COLORS.woodDark, 0, 1.55, 2.22);
    box(g, 1.18, 2.0, 0.1, COLORS.stoneLight, 0, 1.6, 2.29);
    box(g, 0.96, 1.65, 0.2, COLORS.woodDark, 0, 1.5, 2.34, { cast: false });
    for (let k = 0; k < 3; k++) {
      const a = 0.55 + k * 1.5;
      box(g, 0.52, 0.95, 0.12, 0x3b3630, Math.cos(a) * 2.12, 3.2 + k * 0.6, Math.sin(a) * 2.12, { ry: -a, cast: false });
    }
    // little archer silhouette
    if (level >= 2) {
      cyl(g, 0.18, 0.24, 0.95, 0x6d7f92, 0.9, h + 1.3, 0.3, { seg: 5 });
      sphere(g, 0.18, 0xd8b38c, 0.9, h + 1.95, 0.3, { detail: 0 });
    }
    if (level >= 2) this.addFlag(g, 'blue', 0.75, 0, h + 1.15, 0);
    // wooden hoarding at level 3
    if (level >= 3) {
      cyl(g, 2.9, 2.9, 0.28, COLORS.woodDark, 0, h * 0.55, 0, { seg: 12 });
      for (let k = 0; k < 12; k++) {
        const a = (k / 12) * Math.PI * 2;
        box(g, 0.18, 0.8, 0.18, COLORS.wood, Math.cos(a) * 2.6, h * 0.55 + 0.5, Math.sin(a) * 2.6);
      }
    }
    st.height = topY + 1.4;
    st.muzzleY = topY + 0.5;
    return g;
  }

  buildGate(level, st) {
    const g = new THREE.Group();
    box(g, 2.65, 3.3, 2.65, COLORS.stone, 0, 1.65, 0);
    box(g, 2.8, 0.4, 2.8, COLORS.stoneDark, 0, 0.2, 0);
    addCrenellations(g, 2.65, 2.65, 3.3, { n: 4, color: COLORS.stoneLight });
    box(g, 1.45, 2.25, 0.24, 0x2c2620, 0, 1.3, 1.34, { cast: false });
    box(g, 0.66, 2.1, 0.16, COLORS.woodDark, -0.36, 1.18, 1.46);
    box(g, 0.66, 2.1, 0.16, COLORS.woodDark, 0.36, 1.18, 1.46);
    for (const sx of [-0.36, 0.36]) box(g, 0.1, 1.9, 0.05, 0x3a3a3a, sx, 1.18, 1.56, { cast: false });
    box(g, 1.2, 0.12, 0.12, 0x3a3a3a, 0, 1.05, 1.56);
    if (level >= 2) this.addFlag(g, 'blue', 0.65, 0.85, 3.15, 0.8);
    if (level >= 3) {
      box(g, 2.1, 0.5, 0.1, COLORS.stoneLight, 0, 3.0, 1.34);
      sphere(g, 0.12, 0xd9b467, 0, 3.25, 1.4, { detail: 0 });
    }
    st.height = 4.2;
    return g;
  }

  buildHouse(level, st) {
    const g = new THREE.Group();
    const wallH = 2.2 + (level - 1) * 0.32;
    box(g, 4.7, 0.3, 4.3, COLORS.stoneDark, 0, 0.15, 0);
    box(g, 4.45, wallH, 4.05, COLORS.plaster, 0, wallH / 2 + 0.3, 0);
    // timber frame
    const timber = COLORS.timber;
    for (const sx of [-1, 1]) for (const sz of [-1, 1]) box(g, 0.19, wallH, 0.19, timber, sx * 2.1, wallH / 2 + 0.3, sz * 1.9);
    for (const sz of [-1, 1]) {
      box(g, 4.45, 0.16, 0.12, timber, 0, wallH + 0.22, sz * 2.03);
      box(g, 4.45, 0.16, 0.12, timber, 0, 0.48, sz * 2.03);
      for (const sx of [-1.1, 1.1]) box(g, 0.15, wallH, 0.12, timber, sx, wallH / 2 + 0.3, sz * 2.03);
    }
    // diagonal braces
    for (const sx of [-1, 1]) {
      const b = box(g, 0.13, 1.4, 0.1, timber, sx * 1.55, wallH * 0.62, 2.06, { rz: sx * 0.55 });
      b.castShadow = false;
    }
    // roof
    gableRoof(g, 5.35, 4.95, 2.2, COLORS.roof, 0, wallH + 0.35, 0);
