    sphere(g, 0.7, 0xcbb36b, 2.6, 0.6, -2.4, { detail: 1, scale: new THREE.Vector3(1, 0.8, 1) });
    sphere(g, 0.55, 0xbca45d, 2.9, 0.5, -1.2, { detail: 1, scale: new THREE.Vector3(1.1, 0.75, 1) });
