input.content:
import * as THREE from 'three';
import {
  RESOURCES, START_RESOURCES, TICK, STRUCTURES, BUILD_ORDER, TOTAL_WAVES, WAVES,
  QUESTS, UPGRADES, RANKS, rankForSplendor, costFor, upgradeCostFor,
  workerCostFor, populationFor, garrisonFor, towerStatsFor,
  cellKey, worldToCell, HALF, CELL, GRID,
} from './defs.js';
import { UI } from './ui.js';
import { Combat } from './units.js';

const CAMPAIGN_KEY = 'steelstone_campaign_v2';
const SANDBOX_KEY = 'steelstone_sandbox_v2';
const BEST_KEY = 'steelstone_best_v2';

export class Game {
  constructor({ scene, camera, renderer, world, castle, fx, audio, controls }) {
    this.scene = scene;
    this.camera = camera;
    this.renderer = renderer;
    this.world = world;
    this.castle = castle;
    this.fx = fx;
    this.audio = audio;
    this.controls = controls;
    this.castle.game = this;
    this.controls.game = this;

    this.state = 'title';
    this.previousState = null;
    this.sandbox = false;
    this.wave = 1;
    this.wavesSurvived = 0;
    this.resources = { ...START_RESOURCES };
    this.upgrades = [];
    this.rankIndex = 0;
    this.bestWave = Number(localStorage.getItem(BEST_KEY) || 0);
    this.quests = { active: [], done: [] };
    this.tool = 'camera';
    this.selectedType = null;
    this.selectedStructure = null;
    this.undoStack = [];
    this.lastPaintCell = null;
    this.aimingVolley = false;
    this.cooldowns = { volley: 0, horn: 0, repair: 0 };
    this.cooldownMax = { volley: 25, horn: 45, repair: 35 };
    this.tickTimer = TICK;
    this.time = 0;
    this.questTimer = 0;
    this.rankTimer = 0;
    this.saveDirty = false;
    this.saveTimer = 0;
    this.snapshot = null;
    this.heroHintShown = false;
    this.completed = false;
    this.timeScale = 1;

    this.combat = new Combat(scene, castle, fx, audio, {
      onWaveComplete: n => this.onWaveComplete(n),
      onBossSpawn: e => this.onBossSpawn(e),
      onBossKilled: e => this.onBossKilled(e),
      onKill: e => this.onEnemyKilled(e),
      onBoom: amt => this.shake(amt),
    });
    this.combat.callbacks.heroHpMult = 1;
    this.combat.callbacks.heroDmgMult = 1;

    castle.reset();
    this.ui = new UI(this);
    this.enterTitle(true);
  }

  // ---------------------------------------------------------- state
  enterTitle(first = false) {
    this.state = 'title';
    this.combat.clear();
    this.castle.select(null);
    this.ui.closeModal(true);
    this.ui.showHUD(false);
    this.ui.showTitle(true);
    this.controls.setCinematic(true);
    this.ui.updateTitle();
    if (!first) this.saveNow();
  }

  startNewCampaign(resetConfirmed = false) {
    if (this.hasCampaignSave() && !resetConfirmed) {
      this.ui.showConfirm('Found a new city?', 'Your current campaign save will be replaced. The old castle cannot be recovered.', 'Found New City', () => this.startNewCampaign(true));
      return;
    }
    this.castle.reset();
    this.combat.clear();
    this.resources = { ...START_RESOURCES };
    this.wave = 1;
    this.wavesSurvived = 0;
    this.upgrades = [];
    this.rankIndex = 0;
    this.bestWave = this.bestWave || 0;
    this.quests = { active: [], done: [] };
    this.completed = false;
    this.sandbox = false;
    this.tool = 'camera';
    this.selectedType = null;
    this.selectedStructure = null;
    this.undoStack = [];
    this.aimingVolley = false;
    this.cooldowns = { volley: 0, horn: 0, repair: 0 };
    this.tickTimer = TICK;
    this.time = 0;
    this.ensureQuests();
    this.state = 'build';
    this.ui.closeModal(true);
    this.ui.showTitle(false);
    this.ui.showHUD(true);
    this.ui.setBuildMode();
    this.controls.setCinematic(false);
    this.controls.focusHome(true);
    this.saveNow();
    this.updateRank(true);
    this.ui.toast('Your banners rise over a new island. Build your city.', 'good');
    this.ui.hint('Pick a building below, then tap the island to place it.', 9000);
    setTimeout(() => { if (this.state === 'build') this.ui.hint('The Wall tool paints a line — drag across the grass.', 8000); }, 10000);
    setTimeout(() => { if (this.state === 'build') this.ui.hint('When your castle is ready, press Begin Wave.', 8000); }, 20000);
  }

  continueCampaign() {
    const data = this.readSave(CAMPAIGN_KEY);
    if (!data) { this.ui.toast('No saved castle was found.', 'bad'); return; }
    if (data.completed) {
      this.startSandbox(data);
      return;
    }
    this.loadState(data);
    this.sandbox = false;
    this.state = 'build';
    this.completed = false;
    this.ui.closeModal(true);
    this.ui.showTitle(false);
    this.ui.showHUD(true);
    this.ui.setBuildMode();
    this.controls.setCinematic(false);
    this.controls.focusHome(true);
    this.ensureQuests();
    this.ui.toast(`Welcome back. Wave ${this.wave} awaits.`, 'good');
    this.updateRank(true);
  }

  startSandbox(data = null) {
    const save = data || this.readSave(SANDBOX_KEY);
    if (save && save.city) {
      this.loadState(save);
      this.resources = save.resources || { gold: 50000, wood: 50000, stone: 50000, food: 50000 };
    } else {
      this.castle.reset();
      this.resources = { gold: 50000, wood: 50000, stone: 50000, food: 50000 };
      this.wave = 1;
      this.wavesSurvived = save?.wavesSurvived || 0;
      this.upgrades = [];
      this.rankIndex = 0;
      this.quests = { active: [], done: [] };
      this.ensureQuests();
    }
    this.sandbox = true;
    this.state = 'sandbox';
    this.completed = false;
    this.combat.clear();
    this.tool = 'camera';
    this.selectedType = null;
    this.undoStack = [];
    this.cooldowns = { volley: 0, horn: 0, repair: 0 };
    this.tickTimer = TICK;
    this.ui.closeModal(true);
    this.ui.showTitle(false);
    this.ui.showHUD(true);
    this.ui.setBuildMode();
    this.controls.setCinematic(false);
    this.controls.focusHome(true);
    this.saveNow();
    this.updateRank(true);
    this.ui.toast('Free Build — no raiders will come. Raise whatever you dream.', 'good');
    this.ui.hint('Stone, wood and coin are plentiful here. Every street is yours.', 8000);
  }

  loadState(data) {
    this.resources = { ...START_RESOURCES, ...(data.resources || {}) };
    this.wave = data.wave || 1;
    this.wavesSurvived = data.wavesSurvived || 0;
    this.upgrades = Array.isArray(data.upgrades) ? data.upgrades : [];
    this.rankIndex = data.rankIndex || 0;
    this.quests = data.quests && Array.isArray(data.quests.active) ? data.quests : { active: [], done: [] };
    this.bestWave = Math.max(this.bestWave, data.bestWave || 0, data.wavesSurvived || 0);
    this.completed = !!data.completed;
    this.combat.clear();
    this.castle.clearAll();
    if (data.city) this.castle.load(data.city);
    else this.castle.reset();
    this.castle.applyMasonry();
    this.ensureQuests();
    this.undoStack = [];
    this.snapshot = null;
    this.castle.select(null);
    this.ui?.markCityDirty();
  }

  hasCampaignSave() {
    const d = this.readSave(CAMPAIGN_KEY);
    return !!(d && d.city);
  }

  getSaveInfo(key = CAMPAIGN_KEY) {
    return this.readSave(key);
  }

  readSave(key) {
    try {
      const raw = localStorage.getItem(key);
      if (!raw) return null;
      return JSON.parse(raw);
    } catch { return null; }
  }

  saveNow() {
    if (this.state === 'title' || this.state === 'paused' || this.state === 'defeat') return;
    if (this.state === 'combat') return;
    const payload = {
      version: 2,
      resources: { ...this.resources },
      wave: this.wave,
      wavesSurvived: this.wavesSurvived,
      upgrades: [...this.upgrades],
      rankIndex: this.rankIndex,
      quests: { active: [...this.quests.active], done: [...this.quests.done] },
      city: this.castle.serialize(),
      bestWave: this.bestWave,
      completed: this.completed,
      updated: Date.now(),
    };
    try {
      localStorage.setItem(this.sandbox ? SANDBOX_KEY : CAMPAIGN_KEY, JSON.stringify(payload));
      localStorage.setItem(BEST_KEY, String(this.bestWave));
      this.saveDirty = false;
    } catch {}
  }

  saveSoon() {
    this.saveDirty = true;
    this.saveTimer = 1.2;
  }

  // ---------------------------------------------------------- economy
  canAfford(cost) {
    if (this.sandbox) return true;
    for (const [k, v] of Object.entries(cost || {})) {
      if ((this.resources[k] || 0) < v) return false;
    }
    return true;
  }

  missingResources(cost) {
    const miss = {};
    for (const [k, v] of Object.entries(cost || {})) {
      const have = this.resources[k] || 0;
      if (have < v) miss[k] = Math.ceil(v - have);
    }
    return miss;
  }

  spend(cost) {
    if (this.sandbox) return;
    for (const [k, v] of Object.entries(cost || {})) {
      this.resources[k] = Math.max(0, (this.resources[k] || 0) - v);
    }
    this.ui?.markResourcesDirty();
  }

  grant(cost, silent = false) {
    for (const [k, v] of Object.entries(cost || {})) {
      this.resources[k] = (this.resources[k] || 0) + v;
    }
    this.ui?.markResourcesDirty();
    if (!silent) this.ui?.pulseAll();
  }

  stats() { return this.castle.stats(); }

  productionMultiplier() {
    const st = this.stats();
    let factor = 0.8 + st.happiness / 250;
    if (this.hasUpgrade('bounty')) factor *= 1.4;
    factor *= 1 + this.rankIndex * 0.02;
    return factor;
  }

  tickEconomy() {
    const st = this.castle.stats();
    const mult = this.productionMultiplier();
    const gained = {};
    for (const [k, v] of Object.entries(st.production)) {
      if (v <= 0) continue;
      let amount = v * mult;
      if (k === 'gold' && this.hasUpgrade('tax')) amount *= 1.5;
      this.resources[k] = (this.resources[k] || 0) + amount;
      gained[k] = Math.round(amount * 10) / 10;
    }
    if (Object.keys(gained).length) {
      this.ui?.markResourcesDirty();
      this.ui?.pulseResources(Object.keys(gained));
    }
    this.tickTimer = TICK;
  }

  getCost(type) {
    let cost = { ...costFor(type, 1) };
    if (this.hasUpgrade('stone') && (type === 'wall' || type === 'gate')) {
      cost.stone = Math.max(1, Math.round((cost.stone || 0) * 0.75));
    }
    return cost;
  }

  getUpgradeCost(st) {
    let cost = upgradeCostFor(st);
    if (!cost) return null;
    if (this.hasUpgrade('stone') && (st.type === 'wall' || st.type === 'gate')) {
      cost.stone = Math.max(1, Math.round((cost.stone || 0) * 0.75));
    }
    return cost;
  }

  canStaff(type, level = 1, oldLevel = 0) {
    if (this.sandbox) return true;
    const stats = this.stats();
    const delta = workerCostFor(type, level) - workerCostFor(type, oldLevel);
    if (delta <= 0) return true;
    return stats.used + delta <= stats.capacity;
  }

  staffMissing(type, level = 1, oldLevel = 0) {
    const stats = this.stats();
    const delta = workerCostFor(type, level) - workerCostFor(type, oldLevel);
    return Math.max(0, stats.used + delta - stats.capacity);
  }

  hasUpgrade(id) { return this.upgrades.includes(id); }

  combatBonuses() {
    return {
      towerDamageMult: (this.hasUpgrade('fletch') ? 1.25 : 1) * (1 + this.rankIndex * 0.04),
      fireRateMult: this.hasUpgrade('rapid') ? 1.2 : 1,
      siegeDamageMult: this.hasUpgrade('siege') ? 1.35 : 1,
      heroHpMult: (this.hasUpgrade('medic') ? 1.4 : 1) * (this.hasUpgrade('hero') ? 1.3 : 1),
      heroDmgMult: (this.hasUpgrade('hero') ? 1.5 : 1),
    };
  }

  // ---------------------------------------------------------- tools & build
  selectBuild(type) {
    if (this.state === 'combat' || this.state === 'reward' || this.state === 'victory' || this.state === 'defeat') return;
    if (type === 'keep') return;
    this.tool = 'build';
    this.selectedType = type;
    this.aimingVolley = false;
    this.castle.select(null);
    this.selectedStructure = null;
    this.ui.closeModal(true);
    this.ui.setTool('build', type);
    this.ui.updateSelected();
    this.audio.select();
    const def = STRUCTURES[type];
    if (def.road) this.ui.hint('Drag across the grass to pave a road.', 4500);
    else if (type === 'wall') this.ui.hint('Drag across the grass to raise a wall line.', 4500);
  }

  selectCamera() {
    this.tool = 'camera';
    this.selectedType = null;
    this.castle.hideGhost();
    this.castle.select(null);
    this.selectedStructure = null;
    this.ui.closeModal(true);
    this.ui.setTool('camera');
    this.audio.click();
  }

  selectDemolish() {
    if (this.state === 'combat') return;
    if (this.tool === 'demolish') { this.selectCamera(); return; }
    this.tool = 'demolish';
    this.selectedType = null;
    this.selectedStructure = null;
    this.castle.select(null);
    this.castle.hideGhost();
    this.ui.closeModal(true);
    this.ui.setTool('demolish');
    this.ui.hint('Tap or drag across buildings to raze them. Half the cost is refunded.', 5000);
    this.audio.select();
  }

  get isPaintTool() {
    return this.tool === 'demolish' || (this.tool === 'build' && (this.selectedType === 'wall' || this.selectedType === 'road' || this.selectedType === 'gate'));
  }

  updateGhostAt(point) {
    if ((this.state !== 'build' && this.state !== 'sandbox')) { this.castle.hideGhost(); return; }
    if (this.tool !== 'build' || !this.selectedType) { this.castle.hideGhost(); return; }
    const { i, j } = worldToCell(point.x, point.z);
    const def = STRUCTURES[this.selectedType];
    const valid = this.castle.canPlace(this.selectedType, i, j).ok && this.canAfford(this.getCost(this.selectedType));
    this.castle.updateGhost(this.selectedType, i, j, valid);
    this.lastGhost = { i, j };
  }

  onTap(point) {
    this.audio.init();
    if (this.state === 'title' || this.state === 'paused' || this.state === 'reward' || this.state === 'victory' || this.state === 'defeat') return;
    if (this.state === 'combat') {
      if (this.aimingVolley) {
        this.castVolley(point);
        return;
      }
      if (this.combat.commandHero(point)) {
        if (!this.heroHintShown) {
          this.heroHintShown = true;
          this.ui.toast('Captain Aldric answers your command.', 'good');
        }
      } else {
        this.ui.toast('The captain is recovering from his wounds.', 'bad');
      }
      return;
    }
    const { i, j } = worldToCell(point.x, point.z);
    if (this.tool === 'build') {
      this.tryPlace(this.selectedType, i, j);
    } else if (this.tool === 'demolish') {
      this.demolishAt(i, j);
    } else {
      const st = this.castle.getStructureAt(i, j);
      if (st) this.inspect(st);
      else if (this.selectedStructure) this.clearSelection();
    }
  }

  onPointerGround(point) {
    if (this.state === 'build' || this.state === 'sandbox') {
      if (this.tool === 'build') this.updateGhostAt(point);
      else this.castle.hideGhost();
    }
  }

  startPaint(point) {
    if (!this.isPaintTool) return false;
    this.audio.init();
    this.lastPaintCell = null;
    if (this.tool === 'demolish') this.paintDemolish(point);
    else this.paintBuild(point);
    return true;
  }

  dragPaint(point) {
    if (!this.isPaintTool) return;
    if (this.tool === 'demolish') this.paintDemolish(point);
    else this.paintBuild(point);
  }

  endPaint() {
    this.lastPaintCell = null;
    this.ui?.markResourcesDirty();
  }

  paintBuild(point) {
    const { i, j } = worldToCell(point.x, point.z);
    const key = `${i}:${j}`;
    if (this.lastPaintCell === key) return;
    this.lastPaintCell = key;
    this.updateGhostAt(point);
    const cost = this.getCost(this.selectedType);
    if (!this.castle.canPlace(this.selectedType, i, j).ok) return;
    if (!this.canAfford(cost)) { this.ui.toast('Not enough resources.', 'bad'); return; }
    if (this.selectedType !== 'road' && !this.canStaff(this.selectedType, 1)) {
      this.ui.toast(`Need ${this.staffMissing(this.selectedType, 1)} more population — raise a house.`, 'bad');
      return;
    }
    const st = this.castle.place(this.selectedType, i, j, { force: true });
    if (!st) return;
    this.spend(cost);
    this.undoStack.push({ type: this.selectedType, i, j, cost });
    if (this.undoStack.length > 40) this.undoStack.shift();
    this.audio.place();
    this.saveSoon();
    this.ui.markCityDirty();
  }

  paintDemolish(point) {
    const { i, j } = worldToCell(point.x, point.z);
    const key = `${i}:${j}`;
    if (this.lastPaintCell === key) return;
    this.lastPaintCell = key;
    this.demolishAt(i, j, true);
  }

  tryPlace(type, i, j) {
    if (!type) return;
    if (this.state !== 'build' && this.state !== 'sandbox') return;
    if (this.castle.structures.length >= 140) { this.ui.toast('Your castle is at capacity.', 'bad'); return; }
    const valid = this.castle.canPlace(type, i, j);
    if (!valid.ok) { this.audio.error(); this.ui.toast(valid.reason, 'bad'); return; }
    const cost = this.getCost(type);
    if (!this.canAfford(cost)) {
      this.audio.error();
      const missing = this.missingResources(cost);
      const txt = Object.entries(missing).map(([k, v]) => `${Math.ceil(v)} ${RESOURCES[k].name.toLowerCase()}`).join(', ');
      this.ui.toast(`You need ${txt}.`, 'bad');
      return;
    }
    if (type !== 'road' && !this.canStaff(type, 1)) {
      this.audio.error();
      this.ui.toast(`Not enough workers. Build a house for ${this.staffMissing(type, 1)} more people.`, 'bad');
      return;
    }
    const st = this.castle.place(type, i, j, { force: true });
    if (!st) return;
    this.spend(cost);
    this.undoStack.push({ type, i, j, cost });
    if (this.undoStack.length > 40) this.undoStack.shift();
    this.audio.place();
    this.saveSoon();
    this.ui.markCityDirty();
    this.checkQuests();
    if (!this.defsHintShown && type === 'house') {
      this.defsHintShown = true;
    }
  }

  demolishAt(i, j, quiet = false) {
    const st = this.castle.getStructureAt(i, j);
    if (st) {
      if (st.type === 'keep') { this.ui.toast('The keep cannot be razed.', 'bad'); return; }
      const refund = this.refundFor(st);
      this.castle.removeStructure(st);
      this.grant(refund, true);
      if (this.selectedStructure === st) this.clearSelection();
      this.saveSoon();
      this.ui.markCityDirty();
      if (!quiet) {
        this.ui.toast(`Razed ${STRUCTURES[st.type].name}. Recovered ${this.costText(refund)}.`, 'good');
        this.audio.raze();
      }
      return;
    }
    const key = cellKey(i, j);
    if (this.castle.roads.has(key)) {
      this.castle.removeRoad(i, j, { quiet: quiet });
      if (!this.sandbox) this.resources.stone += 1;
      this.saveSoon();
      this.ui.markCityDirty();
    }
  }

  refundFor(st) {
    const def = STRUCTURES[st.type];
    const refund = {};
    const add = (cost, factor) => {
      for (const [k, v] of Object.entries(cost || {})) refund[k] = (refund[k] || 0) + Math.floor(v * factor);
    };
    add(costFor(st.type, 1), 0.5);
    for (let l = 1; l < st.level; l++) add(costFor(st.type, l + 1), 0.35);
    return refund;
  }

  costText(cost) {
    return Object.entries(cost).filter(([, v]) => v > 0).map(([k, v]) => `${Math.floor(v)} ${RESOURCES[k].name.toLowerCase()}`).join(' · ');
  }

  undo() {
    if (this.state === 'combat') return;
    const last = this.undoStack.pop();
    if (!last) { this.ui.toast('Nothing to undo.', 'bad'); return; }
    if (last.type === 'road') {
      this.castle.removeRoad(last.i, last.j, { quiet: true });
    } else {
      const st = this.castle.getStructureAt(last.i, last.j);
      if (!st) { this.ui.toast('That structure is already gone.', 'bad'); return; }
      this.castle.removeStructure(st, { quiet: true });
    }
    this.grant(last.cost, true);
    if (this.selectedStructure) this.clearSelection();
    this.audio.place();
    this.saveSoon();
    this.ui.markCityDirty();
    this.ui.toast('Last build undone.', 'good');
  }

  inspect(st) {
    this.selectedStructure = st;
    this.castle.select(st);
    this.ui.showBuilding(st);
    this.audio.select();
  }

  clearSelection() {
    this.selectedStructure = null;
    this.castle.select(null);
    this.ui.closeModal(true);
  }

  upgradeSelected() {
    const st = this.selectedStructure;
    if (!st) return;
    const def = STRUCTURES[st.type];
    if (!def.maxLevel || st.level >= def.maxLevel) return;
    const cost = this.getUpgradeCost(st);
    if (!this.canAfford(cost)) {
      this.audio.error();
      this.ui.toast('Not enough resources for that upgrade.', 'bad');
      return;
    }
    if (!this.canStaff(st.type, st.level + 1, st.level)) {
      this.audio.error();
      this.ui.toast(`Upgrading needs ${this.staffMissing(st.type, st.level + 1, st.level)} more population.`, 'bad');
      return;
    }
    this.spend(cost);
    this.castle.upgrade(st);
    this.audio.upgrade();
    this.shake(0.18);
    this.ui.toast(`${def.name} upgraded to level ${st.level}.`, 'good');
    this.ui.showBuilding(st);
    this.saveSoon();
    this.ui.markCityDirty();
    this.checkQuests();
    this.updateRank();
  }

  repairStructure(st) {
    if (!st || st.hp >= st.maxHp) return;
    const missing = st.maxHp - st.hp;
    const cost = { gold: Math.max(8, Math.round(missing * 0.055 + 8)) };
    if (!this.canAfford(cost)) { this.audio.error(); this.ui.toast('Not enough gold for repairs.', 'bad'); return; }
    this.spend(cost);
    st.hp = st.maxHp;
    this.castle.updateBar(st);
    if (st.type === 'wall') this.castle.updateWallColor(st);
    this.audio.upgrade();
    this.ui.toast(`${STRUCTURES[st.type].name} repaired for ${cost.gold} gold.`, 'good');
    this.ui.showBuilding(st);
    this.saveSoon();
  }

  repairAll() {
    if (this.state === 'combat') return;
    const damaged = this.castle.structures.some(s => s.hp < s.maxHp);
    if (!damaged) { this.ui.toast('Everything is already standing firm.', 'good'); return; }
    const cost = { gold: 60, wood: 40, stone: 40 };
    if (!this.canAfford(cost)) { this.audio.error(); this.ui.toast('You need 60 gold, 40 wood and 40 stone to repair the city.', 'bad'); return; }
    this.spend(cost);
    const healed = this.castle.repairAll(0.3);
    this.audio.upgrade();
    this.ui.toast(`Repairs complete — ${Math.round(healed)} hit points restored.`, 'good');
    this.saveSoon();
    this.ui.markCityDirty();
    if (this.selectedStructure) this.ui.showBuilding(this.selectedStructure);
  }

  // ---------------------------------------------------------- waves
  beginWave() {
    if (this.state !== 'build') return;
    if (this.wave > TOTAL_WAVES) { this.showVictory(); return; }
    if (this.wave > 1 && this.castle.structures.length < 4) {
      this.ui.toast('Raise some defenses before sounding the horn.', 'bad');
    }
    this.closeSelection();
    this.ui.closeModal(true);
    this.tool = 'camera';
    this.selectedType = null;
    this.ui.setTool('camera');
    this.castle.hideGhost();
    this.snapshot = {
      city: this.castle.serialize(),
      resources: { ...this.resources },
      wave: this.wave,
      wavesSurvived: this.wavesSurvived,
      upgrades: [...this.upgrades],
      rankIndex: this.rankIndex,
      quests: { active: [...this.quests.active], done: [...this.quests.done] },
      completed: this.completed,
    };
    this.saveNow();
    this.state = 'combat';
    this.cooldowns = { volley: 0, horn: 0, repair: 0 };
    this.aimingVolley = false;
    this.combat.startWave(this.wave, this.combatBonuses());
    this.ui.enterCombat();
    this.audio.wave();
    setTimeout(() => this.audio.horn(), 250);
    const wave = WAVES[this.wave - 1];
    this.ui.callout(`WAVE ${this.wave}`, wave?.name || 'The enemy approaches', wave?.sub || '', 'combat');
    this.heroHintShown = false;
    setTimeout(() => {
      if (this.state === 'combat') this.ui.hint('Tap the ground to command Captain Aldric. Towers fire on their own.', 7000);
    }, 2400);
  }

  onWaveComplete(n) {
    if (this.state !== 'combat') return;
    this.combat.active = false;
    this.state = 'reward';
    this.wavesSurvived = Math.max(this.wavesSurvived, n);
    this.bestWave = Math.max(this.bestWave, n);
    try { localStorage.setItem(BEST_KEY, String(this.bestWave)); } catch {}
    this.wave = n + 1;
    const loot = { gold: 80 + n * 25, wood: 50 + n * 18, stone: 60 + n * 22, food: 35 + n * 12 };
    this.grant(loot, true);
    this.updateRank(true);
    this.checkQuests(true);
    this.audio.victory();
    this.shake(0.2);
    if (n >= TOTAL_WAVES) {
      this.completed = true;
      this.wave = TOTAL_WAVES;
      this.saveNowForced();
      this.showVictory();
      return;
    }
    this.ui.showReward(n, loot, this.rewardChoices());
    this.saveDirty = true;
  }

  saveNowForced() {
    const state = this.state;
    this.state = 'build';
    this.saveNow();
    this.state = state;
  }

  rewardChoices() {
    const pool = UPGRADES.filter(u => !this.hasUpgrade(u.id));
    for (let i = pool.length - 1; i > 0; i--) {
      const j = (Math.random() * (i + 1)) | 0;
      [pool[i], pool[j]] = [pool[j], pool[i]];
    }
    const out = pool.slice(0, 3);
    while (out.length < 3) out.push({ id: 'spoils', name: 'Spoils of War', icon: 'i-coin', desc: 'Gain 250 gold, 160 wood and 160 stone immediately.' });
    return out;
  }

  pickUpgrade(id) {
    if (this.state !== 'reward') return;
    if (id === 'spoils') {
      this.grant({ gold: 250, wood: 160, stone: 160 });
    } else {
      if (!this.upgrades.includes(id)) this.upgrades.push(id);
      if (id === 'chest') this.grant({ gold: 300, wood: 250, stone: 250 });
      if (id === 'mason') this.castle.applyMasonry();
      if (id === 'medic') this.castle.repairAll(0.25);
    }
    this.audio.upgrade();
    this.ui.closeModal(true);
    this.combat.clear();
    this.state = 'build';
    this.ui.setBuildMode();
    this.saveNow();
    this.ui.markCityDirty();
    this.checkQuests(true);
    this.updateRank(true);
    this.ui.toast('Boon chosen. The next wave will be harder.', 'good');
  }

  onDefeat() {
    if (this.state !== 'combat') return;
    this.state = 'defeat';
    this.combat.active = false;
    this.combat.hero.group.visible = false;
    this.combat.hero.ring.visible = false;
    this.audio.defeat();
    this.shake(0.8);
    this.ui.showDefeat();
  }

  onKeepDestroyed() {
    this.onDefeat();
  }

  retryWave() {
    if (!this.snapshot) { this.startNewCampaign(true); return; }
    this.restoreSnapshot();
    this.audio.click();
    this.ui.closeModal(true);
    this.ui.toast('The keep is rebuilt. Try a different defense.', 'good');
  }

  restoreSnapshot() {
    if (!this.snapshot) return;
    const s = this.snapshot;
    this.resources = { ...s.resources };
    this.wave = s.wave;
    this.wavesSurvived = s.wavesSurvived;
    this.upgrades = [...s.upgrades];
    this.rankIndex = s.rankIndex;
    this.quests = { active: [...s.quests.active], done: [...s.quests.done] };
    this.castle.clearAll();
    this.castle.load(s.city);
    this.castle.applyMasonry();
    this.combat.clear();
    this.state = 'build';
    this.completed = s.completed;
    this.undoStack = [];
    this.tool = 'camera';
    this.selectedType = null;
    this.selectedStructure = null;
    this.castle.select(null);
    this.ui.showHUD(true);
    this.ui.setBuildMode();
    this.ui.markCityDirty();
    this.controls.setCinematic(false);
    this.controls.focusHome(true);
    this.saveNow();
    this.updateRank(true);
  }

  showVictory() {
    this.state = 'victory';
    this.completed = true;
    this.combat.active = false;
    this.saveNowForced();
    this.ui.showVictory();
    this.audio.victory();
  }

  keepBuilding() {
    this.completed = true;
    this.sandbox = true;
    this.state = 'sandbox';
    this.combat.clear();
    this.tool = 'camera';
    this.ui.closeModal(true);
    this.ui.setBuildMode();
    this.ui.showHUD(true);
    this.saveNow();
    this.ui.toast('Your castle endures. Free Build is now yours.', 'good');
    this.controls.setCinematic(false);
  }

  // ---------------------------------------------------------- hero / abilities
  useAbility(id) {
    if (this.state !== 'combat') return;
    if (this.cooldowns[id] > 0) {
      this.ui.toast(`${id === 'volley' ? 'Arrow Volley' : id === 'horn' ? 'War Horn' : 'Repair'} is not ready yet.`, 'bad');
      return;
    }
    if (id === 'volley') {
      this.aimingVolley = !this.aimingVolley;
      this.ui.setAimingVolley(this.aimingVolley);
      if (this.aimingVolley) this.ui.hint('Tap the battlefield to loose the volley.', 4000);
      return;
    }
    if (id === 'horn') {
      this.combat.activateHorn();
      this.cooldowns.horn = this.cooldownMax.horn;
      this.ui.callout('WAR HORN', 'Arrows fly faster', 'Towers deal more damage for 12 seconds', 'buff');
      this.ui.toast('War horns sound across the walls!', 'good');
      this.shake(0.25);
      return;
    }
    if (id === 'repair') {
      this.combat.healAll(0.22);
      this.cooldowns.repair = this.cooldownMax.repair;
      this.ui.toast('Masons rush the walls. All structures repaired 22%.', 'good');
      this.audio.upgrade();
    }
  }

  castVolley(point) {
    if (!this.aimingVolley) return;
    this.aimingVolley = false;
    this.ui.setAimingVolley(false);
    this.combat.castVolley(point);
    this.cooldowns.volley = this.cooldownMax.volley;
    this.audio.horn();
    this.ui.callout('ARROW VOLLEY', 'The sky darkens', 'A rain of arrows falls on the enemy', 'combat');
    this.shake(0.15);
  }

  focusHero() {
    if (!this.combat.hero.group.visible) { this.ui.toast('Captain Aldric is recovering.', 'bad'); return; }
    this.controls.focusOn(new THREE.Vector3(this.combat.hero.x, 0, this.combat.hero.z), 40);
    this.audio.click();
  }

  onEnemyKilled(e) {
    const bounty = e.boss ? 150 : e.type === 'ram' ? 14 : e.type === 'shield' ? 4 : e.type === 'berserk' ? 3 : 2;
    this.resources.gold = (this.resources.gold || 0) + bounty;
    this.ui?.markResourcesDirty();
    if (e.boss) {
      this.shake(0.6);
      this.ui.toast('Warlord Gruk has fallen!', 'good');
      this.ui.hideBoss();
    }
  }

  onBossSpawn(e) {
    this.ui.showBoss();
    this.audio.horn();
    this.ui.callout('WARLORD GRUK', 'The horde parts', 'A champion of the north enters the field', 'boss');
    this.shake(0.5);
  }

  onBossKilled() {
    this.ui.hideBoss();
    this.audio.victory();
  }

  shake(amount) {
    this.controls?.shake(amount);
  }

  // ---------------------------------------------------------- quests / ranks
  ensureQuests() {
    if (!this.quests) this.quests = { active: [], done: [] };
    if (!Array.isArray(this.quests.active)) this.quests.active = [];
    if (!Array.isArray(this.quests.done)) this.quests.done = [];
    for (const q of [...this.quests.active]) {
      if (!QUESTS.find(x => x.id === q)) this.quests.active = this.quests.active.filter(x => x !== q);
    }
    for (const q of QUESTS) {
      if (this.quests.active.length >= 3) break;
      if (this.quests.done.includes(q.id) || this.quests.active.includes(q.id)) continue;
      this.quests.active.push(q.id);
    }
  }

  questProgress(q) {
    const goal = q.goal;
    if (goal.kind === 'count') {
      if (goal.type === 'road') return { cur: Math.min(this.castle.roads.size, goal.n), n: goal.n };
      const cur = this.castle.structures.filter(s => s.type === goal.type).length;
      return { cur: Math.min(cur, goal.n), n: goal.n };
    }
    if (goal.kind === 'roads') return { cur: Math.min(this.castle.roads.size, goal.n), n: goal.n };
    if (goal.kind === 'population') { const c = this.castle.stats().capacity; return { cur: Math.min(c, goal.n), n: goal.n }; }
    if (goal.kind === 'upgrades') {
      const c = this.castle.structures.filter(s => s.level >= 2).length;
      return { cur: Math.min(c, goal.n), n: goal.n };
    }
    if (goal.kind === 'happiness') { const h = Math.round(this.castle.stats().happiness); return { cur: Math.min(h, goal.n), n: goal.n }; }
    if (goal.kind === 'splendor') { const s = this.castle.splendor(this.wavesSurvived); return { cur: Math.min(s, goal.n), n: goal.n }; }
    if (goal.kind === 'wave') return { cur: Math.min(this.wavesSurvived, goal.n), n: goal.n };
    return { cur: 0, n: goal.n };
  }

  checkQuests(force = false) {
    if (!force && this.state === 'combat') return;
    this.ensureQuests();
    let changed = false;
    for (const id of [...this.quests.active]) {
      const q = QUESTS.find(x => x.id === id);
      if (!q) { continue; }
      const p = this.questProgress(q);
      if (p.cur >= p.n) {
        this.quests.active = this.quests.active.filter(x => x !== id);
        this.quests.done.push(id);
        this.grant(q.reward, true);
        this.ui?.toast(`Goal complete: ${q.title}. Reward: ${this.costText(q.reward)}.`, 'good');
        changed = true;
      }
    }
    if (changed) {
      this.ensureQuests();
      this.ui?.markQuestsDirty();
      this.saveSoon();
    }
    this.ui?.markQuestsDirty();
  }

  updateRank(force = false) {
    if (this.state === 'title' || this.state === 'paused') return;
    this.rankTimer -= 1;
    if (!force && this.rankTimer > 0) return;
    this.rankTimer = 1.0;
    const score = this.castle.splendor(this.wavesSurvived);
    const rank = rankForSplendor(score);
    if (rank.index > this.rankIndex) {
      let total = { gold: 0, wood: 0, stone: 0, food: 0 };
      for (let i = this.rankIndex + 1; i <= rank.index; i++) {
        const r = RANKS[i];
        if (r.reward) for (const [k, v] of Object.entries(r.reward)) total[k] = (total[k] || 0) + v;
      }
      this.rankIndex = rank.index;
      this.grant(total, true);
      this.audio.victory();
      this.shake(0.25);
      this.ui.callout(rank.name.toUpperCase(), 'Your settlement grows', `A new chapter for your castle · ${this.costText(total)}`, 'rank');
      this.ui.toast(`Your city is now a ${rank.name}. Rank bonus: +${rank.index * 4}% tower damage.`, 'good');
      this.saveSoon();
      this.ui.markQuestsDirty();
    }
    this.ui?.updateRank(score, rank);
  }

  // ---------------------------------------------------------- pause / abandon
  pause() {
    if (this.state === 'title' || this.state === 'paused' || this.state === 'reward' || this.state === 'victory' || this.state === 'defeat') return;
    this.previousState = this.state;
    this.state = 'paused';
    if (this.previousState === 'build' || this.previousState === 'sandbox') this.saveNow();
    this.ui.showPause();
  }

  resume() {
    if (this.state !== 'paused') return;
    this.state = this.previousState || 'build';
    this.ui.closeModal(true);
    this.controls.setCinematic(false);
  }

  returnToTitle() {
    if (this.state === 'combat') {
      if (this.snapshot) this.restoreSnapshot();
    }
    if (this.state === 'build' || this.state === 'sandbox') this.saveNow();
    this.combat.clear();
    this.selectedStructure = null;
    this.castle.select(null);
    this.state = 'title';
    this.ui.closeModal(true);
    this.ui.showHUD(false);
    this.ui.showTitle(true);
    this.ui.updateTitle();
    this.controls.setCinematic(true);
  }

  toggleSound() {
    this.audio.init();
    const on = this.audio.toggle();
    this.ui.updateSound(on);
    this.ui.toast(on ? 'Sound on.' : 'Sound muted.', 'good');
  }

  // ---------------------------------------------------------- main update
  update(dt) {
    this.time += dt;
    if (this.state === 'title' || this.state === 'paused') {
      if (this.saveDirty) {
        this.saveTimer -= dt;
        if (this.saveTimer <= 0) this.saveNow();
      }
      return;
    }

    for (const k of Object.keys(this.cooldowns)) this.cooldowns[k] = Math.max(0, this.cooldowns[k] - dt);

    if (this.state !== 'reward' && this.state !== 'victory' && this.state !== 'defeat') {
      this.tickTimer -= dt;
      if (this.tickTimer <= 0) this.tickEconomy();
    }

    if (this.state === 'combat') {
      this.combat.update(dt, this.combatBonuses());
      this.ui.updateCombat();
    }

    if (this.state === 'build' || this.state === 'sandbox' || this.state === 'reward') {
      this.questTimer -= dt;
      if (this.questTimer <= 0) {
        this.questTimer = 0.7;
        this.checkQuests(this.state === 'reward');
      }
      this.rankTimer -= dt;
      if (this.rankTimer <= 0) this.updateRank();
    }

    if (this.saveDirty) {
      this.saveTimer -= dt;
      if (this.saveTimer <= 0 && (this.state === 'build' || this.state === 'sandbox')) this.saveNow();
    }

    this.ui.tick(dt);
  }

  onCityChanged() {
    if (this.state === 'title') return;
    this.ui?.markCityDirty();
    this.saveSoon();
  }

  onStructureDestroyed(st) {
    if (this.selectedStructure === st) this.clearSelection();
    this.ui?.markCityDirty();
  }
}

import {
  RESOURCES, STRUCTURES, BUILD_ORDER, QUESTS, WAVES, TOTAL_WAVES, RANKS,
  rankForSplendor, workerCostFor, populationFor, happinessFor, garrisonFor,
  towerStatsFor, productionFor, upgradeCostFor,
} from './defs.js';

const $ = (sel, root = document) => root.querySelector(sel);
const $$ = (sel, root = document) => [...root.querySelectorAll(sel)];

function icon(name, cls = 'ic') {
  return `<svg class="${cls}"><use href="#${name}"/></svg>`;
}

function round(n) { return Math.floor(n + 0.0001); }

export class UI {
  constructor(game) {
    this.game = game;
    this.el = {
      title: $('#title'),
      hud: $('#hud'),
      modal: $('#modal'),
      modalCard: $('#modal-card'),
      resources: $('#resources'),
      phasePill: $('#phase-pill'),
      phaseLabel: $('#phase-label'),
      waveLabel: $('#wave-label'),
      waveProgress: $('#wave-progress'),
      wprogFill: $('#wprog-fill'),
      wprogText: $('#wprog-text'),
      bossBar: $('#boss-bar'),
      bossFill: $('#boss-fill'),
      quest: $('#quest'),
      questList: $('#quest-list'),
      rankLabel: $('#rank-label'),
      rpFill: $('#rp-fill'),
      rpLabel: $('#rp-label'),
      abilities: $('#battle-abilities'),
      heroHud: $('#hero-hud'),
      heroFill: $('#hero-fill'),
      heroState: $('#hero-state'),
      targetHint: $('#target-hint'),
      bottombar: $('#bottombar'),
      palette: $('#palette'),
      selName: $('#sel-name'),
      selDesc: $('#sel-desc'),
      selCost: $('#sel-cost'),
      selIcon: $('.sel-ic'),
      btnWave: $('#btn-wave'),
      waveMain: $('#wave-btn-main'),
      waveSub: $('#wave-btn-sub'),
      btnCamera: $('#tool-camera'),
      btnUndo: $('#btn-undo'),
      btnDemolish: $('#btn-demolish'),
      btnRepair: $('#btn-repair'),
      btnSound: $('#btn-sound'),
      btnMenu: $('#btn-menu'),
      toast: $('#toast'),
      callout: $('#wave-callout'),
      hint: $('#hint-banner'),
      best: $('#best-label'),
      btnContinue: $('#btn-continue'),
      titleFoot: $('.title-foot'),
    };
    this.resourceEls = {};
    this.resourceState = {};
    this.cardEls = {};
    this.resourcesDirty = true;
    this.cityDirty = true;
    this.questsDirty = true;
    this.modalOpen = false;
    this.modalCloseable = true;
    this.howFromPause = false;
    this.currentRank = rankForSplendor(0);
    this.waveButtonState = '';
    this.toastTimer = null;
    this.hintTimer = null;
    this.calloutTimer = null;

    this.buildResources();
    this.buildPalette();
    this.bind();
    this.updateSound(game.audio.enabled);
    this.markQuestsDirty();
    this.updateResources();
    this.updateQuests();
    this.updateTitle();
    this.setBuildMode();
  }

  // ---------------------------------------------------------- DOM build
  buildResources() {
    const defs = [
      ['gold', 'i-coin'], ['wood', 'i-wood'], ['stone', 'i-stone'], ['food', 'i-food'],
    ];
    let html = '';
    for (const [key, ic] of defs) {
      html += `<div class="res" data-type="${key}" title="${RESOURCES[key].name}"><svg class="ic"><use href="#${ic}"/></svg><b id="res-${key}">0</b><span class="delta"></span></div>`;
    }
    html += `<div class="res city" data-type="pop" title="Population: workers / housing"><svg class="ic"><use href="#i-people"/></svg><b id="res-pop">0/10</b></div>`;
    html += `<div class="res city" data-type="happy" title="Happiness: boosts resource production"><svg class="ic"><use href="#i-happy"/></svg><b id="res-happy">55</b></div>`;
    this.el.resources.innerHTML = html;
    for (const key of ['gold', 'wood', 'stone', 'food', 'pop', 'happy']) {
      this.resourceEls[key] = $(`#res-${key}`);
    }
  }

  buildPalette() {
    let html = '';
    for (const type of BUILD_ORDER) {
      const def = STRUCTURES[type];
      if (!def || def.hidden) continue;
      const costs = Object.entries(def.cost).map(([k, v]) =>
        `<span class="c"><svg class="ic"><use href="#${RESOURCES[k].icon}"/></svg>${v}</span>`).join('');
      html += `<button class="build-card" data-type="${type}" data-cat="${def.category}" title="${def.name} — ${def.desc}">
        ${icon(def.icon)}
        <span class="name">${def.name.replace('Stone ', '').replace('Cobbled ', '').replace('Archer ', '')}</span>
        <span class="cost">${costs}</span>
      </button>`;
    }
    this.el.palette.innerHTML = html;
    $$('.build-card', this.el.palette).forEach(el => {
      this.cardEls[el.dataset.type] = el;
      el.addEventListener('click', () => {
        this.game.audio.init();
        this.game.selectBuild(el.dataset.type);
      });
    });
  }

  bind() {
    const g = this.game;
    $('#btn-play').addEventListener('click', () => { g.audio.init(); g.audio.click(); g.startNewCampaign(); });
    $('#btn-continue').addEventListener('click', () => { g.audio.init(); g.audio.click(); g.continueCampaign(); });
    $('#btn-sandbox').addEventListener('click', () => { g.audio.init(); g.audio.click(); g.startSandbox(); });
    $('#btn-how').addEventListener('click', () => { g.audio.init(); g.audio.click(); this.showHowTo(); });
    this.el.btnSound.addEventListener('click', () => g.toggleSound());
    this.el.btnMenu.addEventListener('click', () => { g.audio.init(); g.audio.click(); g.pause(); });
    this.el.btnWave.addEventListener('click', () => { g.audio.init(); g.audio.click(); g.beginWave(); });
    this.el.btnCamera.addEventListener('click', () => g.selectCamera());
    this.el.btnUndo.addEventListener('click', () => g.undo());
    this.el.btnDemolish.addEventListener('click', () => g.selectDemolish());
    this.el.btnRepair.addEventListener('click', () => {
      g.audio.init();
      if (g.state === 'combat') g.useAbility('repair');
      else g.repairAll();
    });
    $('#ability-volley').addEventListener('click', () => g.useAbility('volley'));
    $('#ability-horn').addEventListener('click', () => g.useAbility('horn'));
    $('#ability-repair').addEventListener('click', () => g.useAbility('repair'));
    $('#cancel-target').addEventListener('click', () => {
      g.aimingVolley = false;
      this.setAimingVolley(false);
    });
    $('#hero-focus').addEventListener('click', () => g.focusHero());

    this.el.modal.querySelector('.modal-backdrop').addEventListener('click', () => {
      if (this.modalCloseable) this.escapeModal();
    });

    window.addEventListener('keydown', e => this.onKey(e));
  }

  onKey(e) {
    const g = this.game;
    if (e.target && e.target.matches && e.target.matches('input, textarea')) return;
    if (e.key === 'Escape') {
      if (this.modalOpen) {
        if (this.modalCloseable) this.escapeModal();
        else if (g.state === 'paused') g.resume();
        return;
      }
      if (g.aimingVolley) { g.aimingVolley = false; this.setAimingVolley(false); return; }
      if (g.state === 'combat') { g.pause(); return; }
      if (g.state === 'build' || g.state === 'sandbox') { g.selectCamera(); return; }
    }
    if (this.modalOpen) return;
    if (g.state === 'title') return;
    const k = e.key.toLowerCase();
    if ((e.ctrlKey || e.metaKey) && k === 'z') { e.preventDefault(); g.undo(); return; }
    if (k === 'v') { g.selectCamera(); return; }
    if (k === 'x') { g.selectDemolish(); return; }
    if (k === 'q' && g.state === 'combat') { g.useAbility('volley'); return; }
    if (k === 'w') {
      if (g.state === 'combat') { g.useAbility('horn'); return; }
      e.preventDefault(); g.beginWave(); return;
    }
    if (k === 'e') {
      e.preventDefault();
      if (g.state === 'combat') g.useAbility('repair');
      else g.repairAll();
      return;
    }
    if (k === ' ' && g.state === 'build') { e.preventDefault(); g.beginWave(); return; }
    if (k >= '1' && k <= '9') {
      const idx = Number(k) - 1;
      const type = BUILD_ORDER[idx];
      if (type) g.selectBuild(type);
    }
  }

  // ---------------------------------------------------------- screen state
  showHUD(show) {
    this.el.hud.classList.toggle('hidden', !show);
  }

  showTitle(show) {
    if (show) {
      this.el.title.classList.remove('hidden', 'fade-out');
      this.el.title.style.display = 'flex';
      this.el.title.style.pointerEvents = '';
      this.updateTitle();
    } else {
      this.el.title.classList.add('fade-out');
      setTimeout(() => {
        if (this.el.title.classList.contains('fade-out')) {
          this.el.title.classList.add('hidden');
          this.el.title.style.display = 'none';
        }
      }, 450);
    }
  }

  updateTitle() {
    const save = this.game.getSaveInfo();
    const sandbox = this.game.getSaveInfo('steelstone_sandbox_v2');
    if (this.el.btnContinue) {
      const show = !!(save && save.city);
      this.el.btnContinue.classList.toggle('hidden', !show);
      const label = this.el.btnContinue.querySelector('span');
      if (show && label) label.textContent = save.completed ? 'Continue Castle' : `Continue · Wave ${save.wave || 1}`;
    }
    const best = Math.max(this.game.bestWave || 0, save?.wavesSurvived || 0, sandbox?.wavesSurvived || 0);
    this.el.best.textContent = best > 0 ? `Best defense: Wave ${best} / ${TOTAL_WAVES}` : 'Best defense: —';
    if (save?.completed) this.el.best.textContent = `Campaign complete · Best defense: all ${TOTAL_WAVES} waves`;
  }

  setBuildMode() {
    const g = this.game;
    this.el.bottombar.classList.remove('hidden', 'combat');
    this.el.bottombar.style.display = '';
    this.el.abilities.classList.add('hidden');
    this.el.heroHud.classList.add('hidden');
    this.el.waveProgress.classList.add('hidden');
    this.el.bossBar.classList.add('hidden');
    this.el.quest.classList.remove('hidden');
    this.el.quest.classList.remove('done');
    this.el.phasePill.classList.remove('combat');
    this.showHUD(true);
    this.el.btnWave.style.display = g.sandbox ? 'none' : '';
    this.el.btnWave.classList.toggle('ready', !g.sandbox && g.state === 'build');
    this.updatePhase();
    this.updateWaveButton();
    this.setTool(g.tool, g.selectedType);
    this.markResourcesDirty();
    this.markCityDirty();
    this.markQuestsDirty();
    this.setAimingVolley(false);
    this.updateSound(g.audio.enabled);
    setTimeout(() => this.el.quest.classList.remove('hidden'), 10);
  }

  enterCombat() {
    const g = this.game;
    this.el.bottombar.classList.add('hidden');
    this.el.abilities.classList.remove('hidden');
    this.el.heroHud.classList.remove('hidden');
    this.el.waveProgress.classList.remove('hidden');
    this.el.quest.classList.add('hidden');
    this.el.phasePill.classList.add('combat');
    this.el.btnWave.classList.remove('ready');
    this.el.targetHint.classList.add('hidden');
    this.setAimingVolley(false);
    this.updatePhase();
    this.updateWaveProgress();
    this.updateHeroHud();
    this.updateAbilities();
    this.el.bossBar.classList.add('hidden');
    this.game.castle.hideGhost();
    this.game.castle.select(null);
    this.game.ui.closeModal(true);
  }

  updatePhase() {
    const g = this.game;
    if (g.state === 'combat') {
      this.el.phaseLabel.textContent = 'Under Siege';
      this.el.waveLabel.textContent = `Wave ${g.wave} / ${TOTAL_WAVES}`;
      this.el.phasePill.classList.add('combat');
    } else if (g.state === 'sandbox') {
      this.el.phaseLabel.textContent = 'Free Build';
      this.el.waveLabel.textContent = 'No sieges';
      this.el.phasePill.classList.remove('combat');
    } else if (g.state === 'title') {
      this.el.phaseLabel.textContent = 'Build Phase';
      this.el.waveLabel.textContent = `Wave ${g.wave} / ${TOTAL_WAVES}`;
    } else {
      this.el.phaseLabel.textContent = 'Build Phase';
      this.el.waveLabel.textContent = `Wave ${Math.min(g.wave, TOTAL_WAVES)} / ${TOTAL_WAVES}`;
      this.el.phasePill.classList.remove('combat');
    }
  }

  updateWaveButton() {
    const g = this.game;
    if (g.sandbox) { this.el.btnWave.style.display = 'none'; return; }
    this.el.btnWave.style.display = '';
    this.el.waveMain.textContent = g.wave === TOTAL_WAVES ? 'Final Wave' : 'Begin Wave';
    const wave = WAVES[Math.min(g.wave, TOTAL_WAVES) - 1];
    const total = wave ? Object.values(wave.comp).reduce((a, b) => a + b, 0) : 0;
    this.el.waveSub.textContent = wave ? `Wave ${g.wave} · ${total} enemies` : 'The raiders are coming';
    this.el.btnWave.classList.toggle('ready', g.state === 'build');
  }

  setTool(tool, type) {
    this.el.btnCamera.classList.toggle('active', tool === 'camera');
    this.el.btnDemolish.classList.toggle('active', tool === 'demolish');
    for (const [t, el] of Object.entries(this.cardEls)) {
      el.classList.toggle('selected', tool === 'build' && t === type);
    }
    this.updateSelected();
  }

  updateSelected() {
    const g = this.game;
    if (g.tool === 'build' && g.selectedType) {
      const def = STRUCTURES[g.selectedType];
      this.el.selIcon.innerHTML = `<use href="#${def.icon}"/>`;
      this.el.selName.textContent = def.name;
      this.el.selDesc.textContent = def.desc;
      this.el.selCost.innerHTML = this.costHTML(g.getCost(g.selectedType), true, true);
    } else if (g.tool === 'demolish') {
      this.el.selIcon.innerHTML = `<use href="#i-hammer"/>`;
      this.el.selName.textContent = 'Raze';
      this.el.selDesc.textContent = 'Tap or drag to remove buildings. Half the cost is recovered.';
      this.el.selCost.innerHTML = '<span style="color:#a99f8c">Keep is permanent</span>';
    } else {
      this.el.selIcon.innerHTML = `<use href="#i-eye"/>`;
      this.el.selName.textContent = 'Inspect & Camera';
      this.el.selDesc.textContent = 'Drag to look around. Tap a building to inspect or upgrade it.';
      this.el.selCost.innerHTML = '<span style="color:#a99f8c">Two fingers to pan & zoom</span>';
    }
  }

  costHTML(cost, check = false, includeZero = false) {
    const g = this.game;
    const parts = [];
    for (const [k, v] of Object.entries(cost || {})) {
      if (!includeZero && v <= 0) continue;
      const short = check && !g.sandbox && (g.resources[k] || 0) < v;
      parts.push(`<span class="${short ? 'short' : ''}">${icon(RESOURCES[k].icon)}${Math.ceil(v)}</span>`);
    }
    return parts.join('');
  }

  // ---------------------------------------------------------- resources / city
  markResourcesDirty() { this.resourcesDirty = true; this.cityDirty = true; }
  markCityDirty() { this.cityDirty = true; }
  markQuestsDirty() { this.questsDirty = true; }

  pulseAll() {
    for (const key of ['gold', 'wood', 'stone', 'food']) this.pulseResource(key);
  }

  pulseResources(keys) {
    for (const key of keys) this.pulseResource(key);
  }

  pulseResource(key) {
    const el = this.resourceEls[key];
    if (!el) return;
    el.classList.add('flash');
    setTimeout(() => el.classList.remove('flash'), 380);
  }

  updateResources() {
    const g = this.game;
    const st = g.castle.stats();
    for (const key of ['gold', 'wood', 'stone', 'food']) {
      const val = round(g.resources[key] || 0);
      if (this.resourceEls[key]) this.resourceEls[key].textContent = val;
    }
    if (this.resourceEls.pop) {
      this.resourceEls.pop.textContent = `${st.used}/${st.capacity}`;
      this.resourceEls.pop.parentElement?.classList.toggle('crowded', st.used / Math.max(1, st.capacity) > 0.9);
    }
    if (this.resourceEls.happy) {
      this.resourceEls.happy.textContent = `${Math.round(st.happiness)}`;
      this.resourceEls.happy.parentElement?.classList.toggle('unhappy', st.happiness < 35);
    }
    this.resourcesDirty = false;
  }

  updateCity() {
    const g = this.game;
    this.updateResources();
    for (const [type, el] of Object.entries(this.cardEls)) {
      const cost = g.getCost(type);
      el.classList.toggle('unaffordable', !g.canAfford(cost));
    }
    this.updateSelected();
    this.updatePhase();
    if (g.state !== 'combat') this.updateWaveButton();
    this.cityDirty = false;
  }

  // ---------------------------------------------------------- quests & rank
  updateQuests() {
    const g = this.game;
    g.ensureQuests();
    let html = '';
    for (const id of g.quests.active.slice(0, 3)) {
      const q = QUESTS.find(x => x.id === id);
      if (!q) continue;
      const p = g.questProgress(q);
      const rewards = Object.entries(q.reward).map(([k, v]) =>
        `<span title="${RESOURCES[k].name}">${icon(RESOURCES[k].icon)}${v}</span>`).join('');
      html += `<li>
        <span class="qbox"></span>
        <span class="qtext">${q.title}<span class="qprog">${Math.min(p.cur, p.n)}/${p.n}</span>
          <span class="qreward">${rewards}</span>
        </span>
      </li>`;
    }
    this.el.questList.innerHTML = html;
    const score = g.castle.splendor(g.wavesSurvived);
    const rank = rankForSplendor(score);
    this.currentRank = rank;
    this.el.rankLabel.textContent = rank.name;
    const next = rank.next;
    const span = next ? Math.max(1, next.min - rank.min) : 1;
    const prog = next ? Math.max(0, Math.min(1, (score - rank.min) / span)) : 1;
    this.el.rpFill.style.width = `${prog * 100}%`;
    this.el.rpLabel.textContent = next ? `${score} splendor · ${Math.max(0, next.min - score)} to ${next.name}` : `${score} splendor · legendary`;
    this.questsDirty = false;
  }

  updateRank(score, rank) {
    this.currentRank = rank;
    this.el.rankLabel.textContent = rank.name;
    const next = rank.next;
    const span = next ? Math.max(1, next.min - rank.min) : 1;
    const prog = next ? Math.max(0, Math.min(1, (score - rank.min) / span)) : 1;
    this.el.rpFill.style.width = `${prog * 100}%`;
    this.el.rpLabel.textContent = next ? `${score} splendor · ${Math.max(0, next.min - score)} to ${next.name}` : `${score} splendor · legendary`;
  }

  // ---------------------------------------------------------- combat HUD
  updateCombat() {
    this.updateWaveProgress();
    this.updateAbilities();
    this.updateHeroHud();
    this.updateBoss();
    if (this.resourcesDirty) this.updateResources();
  }

  updateWaveProgress() {
    const g = this.game;
    const wave = WAVES[g.wave - 1];
    if (!wave) return;
    const total = Object.values(wave.comp).reduce((a, b) => a + b, 0);
    const remaining = g.combat.queue.length + g.combat.enemies.filter(e => e.hp > 0).length;
    this.el.wprogFill.style.width = `${Math.max(0, Math.min(100, (remaining / total) * 100))}%`;
    this.el.wprogText.textContent = `${remaining} of ${total} remaining`;
  }

  updateAbilities() {
    const g = this.game;
    for (const id of ['volley', 'horn', 'repair']) {
      const el = $(`#ability-${id}`);
      if (!el) continue;
      const cd = g.cooldowns[id] || 0;
      const max = g.cooldownMax[id] || 1;
      const ratio = Math.max(0, Math.min(1, cd / max));
      el.classList.toggle('cooling', cd > 0);
      el.classList.toggle('ready', cd <= 0);
      el.style.setProperty('--cd', (ratio * 100).toFixed(1));
      el.classList.toggle('targeting', id === 'volley' && g.aimingVolley);
    }
  }

  updateHeroHud() {
    const g = this.game;
    if (!g.combat) return;
    const hero = g.combat.hero;
    this.el.heroHud.classList.remove('hidden');
    const ratio = hero.maxHp ? Math.max(0, hero.hp / hero.maxHp) : 0;
    this.el.heroFill.style.width = `${ratio * 100}%`;
    this.el.heroHud.classList.toggle('dead', !hero.alive);
    if (!hero.alive) this.el.heroState.textContent = `Fallen · ${Math.ceil(hero.respawnTimer)}s`;
    else if (hero.target) this.el.heroState.textContent = 'Fighting';
    else if (hero.hasCommand) this.el.heroState.textContent = 'Moving';
    else this.el.heroState.textContent = 'Guarding';
  }

  updateBoss() {
    const g = this.game;
    const b = g.combat?.boss;
    if (!b || b.hp <= 0) {
      this.el.bossBar.classList.add('hidden');
      return;
    }
    this.el.bossBar.classList.remove('hidden');
    this.el.bossFill.style.width = `${Math.max(0, b.hp / b.maxHp) * 100}%`;
  }

  showBoss() { this.el.bossBar.classList.remove('hidden'); }
  hideBoss() { this.el.bossBar.classList.add('hidden'); }

  setAimingVolley(on) {
    this.el.targetHint.classList.toggle('hidden', !on);
    this.el.abilities.classList.toggle('targeting-mode', on);
    if (on) this.el.abilities.classList.remove('hidden');
  }

  updateSound(on) {
    if (!this.el.btnSound) return;
    this.el.btnSound.innerHTML = `<svg class="ic"><use href="#${on ? 'i-sound' : 'i-muted'}"/></svg>`;
    this.el.btnSound.setAttribute('aria-label', on ? 'Mute sound' : 'Enable sound');
  }

  tick(dt) {
    if (this.resourcesDirty) this.updateResources();
    if (this.cityDirty) this.updateCity();
    if (this.questsDirty && this.game.state !== 'combat') this.updateQuests();
    if (this.game.state === 'combat') this.updateAbilities();
  }

  // ---------------------------------------------------------- toast / callout
  toast(text, kind = '') {
    this.el.toast.textContent = text;
    this.el.toast.className = `show ${kind}`.trim();
    clearTimeout(this.toastTimer);
    this.toastTimer = setTimeout(() => {
      this.el.toast.className = this.el.toast.className.replace('show', '').trim();
    }, 3400);
  }

  hint(text, ms = 6000) {
    this.el.hint.textContent = text;
    this.el.hint.classList.remove('hidden');
    this.el.hint.style.animation = 'none';
    void this.el.hint.offsetWidth;
    this.el.hint.style.animation = '';
    clearTimeout(this.hintTimer);
    this.hintTimer = setTimeout(() => this.el.hint.classList.add('hidden'), ms);
  }

  callout(title, kicker = '', sub = '', kind = '') {
    const el = this.el.callout;
    el.innerHTML = `<div class="wc-kicker">${kicker}</div><div class="wc-title">${title}</div><div class="wc-sub">${sub}</div>`;
    el.classList.remove('hidden');
    el.style.animation = 'none';
    void el.offsetWidth;
    el.style.animation = '';
    clearTimeout(this.calloutTimer);
    this.calloutTimer = setTimeout(() => el.classList.add('hidden'), 3800);
  }

  // ---------------------------------------------------------- modal plumbing
  openModal(html, opts = {}) {
    this.el.modalCard.className = `modal-card ${opts.className || ''}`.trim();
    this.el.modalCard.innerHTML = html;
    this.el.modal.classList.remove('hidden');
    this.modalOpen = true;
    this.modalCloseable = opts.closeable !== false;
    if (opts.onMount) opts.onMount(this.el.modalCard);
    $$('[data-close]', this.el.modalCard).forEach(btn => btn.addEventListener('click', () => this.escapeModal()));
  }

  closeModal(force = false) {
    this.el.modal.classList.add('hidden');
    this.modalOpen = false;
    if (force) this.el.modalCard.innerHTML = '';
  }

  escapeModal() {
    const g = this.game;
    if (g.state === 'paused') {
      if (this.howFromPause) { this.howFromPause = false; g.resume(); this.el.modal.classList.add('hidden'); this.modalOpen = false; return; }
      g.resume();
      return;
    }
    this.closeModal(true);
    if (g.selectedStructure) g.clearSelection();
  }

  // ---------------------------------------------------------- building modal
  showBuilding(st) {
    const g = this.game;
    const def = STRUCTURES[st.type];
    const level = st.level;
    const stStats = g.castle.stats();
    const rows = [];
    const hpPct = Math.max(0, Math.min(100, (st.hp / st.maxHp) * 100));
    rows.push(`<div class="bld-stat"><span>${icon('i-shield')}Integrity</span><b>${Math.ceil(st.hp)} / ${st.maxHp}</b></div>`);
    if (def.population) rows.push(`<div class="bld-stat"><span>${icon('i-people')}Population</span><b>+${populationFor(st.type, level)} capacity</b></div>`);
    if (def.workers) rows.push(`<div class="bld-stat"><span>${icon('i-people')}Workers</span><b>${workerCostFor(st.type, level)}</b></div>`);
    const prod = productionFor(st.type, level);
    if (Object.keys(prod).length) {
      const txt = Object.entries(prod).map(([k, v]) => `${icon(RESOURCES[k].icon)} +${(Math.round(v * 10) / 10)}`).join(' ');
      rows.push(`<div class="bld-stat"><span>${icon('i-farm')}Per 6s</span><b>${txt}</b></div>`);
    }
    if (def.happiness) rows.push(`<div class="bld-stat"><span>${icon('i-happy')}Happiness</span><b>+${happinessFor(st.type, level)}</b></div>`);
    if (def.garrison) rows.push(`<div class="bld-stat"><span>${icon('i-captain')}Garrison</span><b>${garrisonFor(st.type, level)} guards</b></div>`);
    const tower = towerStatsFor(st.type, level);
    if (tower) {
      rows.push(`<div class="bld-stat"><span>${icon('i-tower')}Damage</span><b>${Math.round(tower.damage)} per shot</b></div>`);
      rows.push(`<div class="bld-stat"><span>${icon('i-eye')}Range</span><b>${tower.range.toFixed(1)}</b></div>`);
    }

    let upgradeHTML = '';
    if (def.maxLevel && level < def.maxLevel) {
      const cost = g.getUpgradeCost(st);
      const missingWorkers = g.staffMissing(st.type, level + 1, level);
      const canAfford = g.canAfford(cost);
      const canStaff = missingWorkers <= 0;
      const nextProd = productionFor(st.type, level + 1);
      const prodDiff = Object.keys(nextProd).length
        ? Object.entries(nextProd).map(([k, v]) => {
          const cur = productionFor(st.type, level)[k] || 0;
          return `${RESOURCES[k].name} +${Math.round((v - cur) * 10) / 10}/6s`;
        }).join(' · ')
        : '';
      const extra = def.happiness ? ` · Happiness +${Math.round(happinessFor(st.type, level + 1) - happinessFor(st.type, level))}` : '';
      const towerNext = towerStatsFor(st.type, level + 1);
      const towerTxt = towerNext ? ` · Damage ${Math.round(towerNext.damage)} · Range ${towerNext.range.toFixed(1)}` : '';
      upgradeHTML = `<div class="bld-up">
        <h4>${icon('i-upgrade')}Upgrade to level ${level + 1}</h4>
        <p>${prodDiff || 'Stronger structure'}${extra}${towerTxt}<br/>
        Costs ${g.costText(cost)}${def.workers ? ` · +1 worker` : ''}${missingWorkers > 0 ? ` · <span style="color:#e08b7b">needs ${missingWorkers} more population</span>` : ''}.</p>
        <div class="up-cost">${this.costHTML(cost, true)}</div>
      </div>`;
    } else if (def.maxLevel) {
      upgradeHTML = `<div class="bld-up"><h4>${icon('i-star')}Masterwork</h4><p>This building is at its highest level. It stands as a monument to your city.</p></div>`;
    }

    const html = `
      <button class="modal-close" data-close aria-label="Close">${icon('i-x')}</button>
      <div class="bld-head">
        <div class="bld-art">${icon(def.icon)}</div>
        <div class="bld-headtext">
          <div class="modal-kicker">${def.category} · Level ${level}${def.maxLevel ? ` / ${def.maxLevel}` : ''}</div>
          <h2 class="modal-title">${def.name}</h2>
        </div>
      </div>
      <p class="modal-sub">${def.desc}</p>
      <div class="bld-stats">${rows.join('')}</div>
      ${upgradeHTML}
      <div class="bld-actions">
        ${def.maxLevel && level < def.maxLevel ? `<button class="btn gold" data-upgrade ${(!g.canAfford(g.getUpgradeCost(st)) || g.staffMissing(st.type, level + 1, level) > 0) ? 'disabled style="opacity:.45"' : ''}>${icon('i-upgrade')}Upgrade</button>` : ''}
        <button class="btn" data-repair ${st.hp >= st.maxHp ? 'disabled style="opacity:.45"' : ''}>${icon('i-repair')}Repair</button>
        ${st.type !== 'keep' ? `<button class="btn demolish" data-demolish>${icon('i-hammer')}Raze</button>` : ''}
        <button class="btn" data-close>${icon('i-x')}Close</button>
      </div>
      <div class="modal-note" style="margin-top:10px;font-size:10px;color:#8d8473">${def.workers ? `Employs ${workerCostFor(st.type, level)} of your ${stStats.capacity} people. ` : ''}${st.type === 'tower' || st.type === 'ballista' || st.type === 'catapult' ? 'Fires automatically during a siege.' : ''}</div>
    `;
    this.openModal(html, {
      closeable: true,
      className: 'narrow',
      onMount: card => {
        const up = $('[data-upgrade]', card);
        if (up) up.addEventListener('click', () => g.upgradeSelected());
        const rep = $('[data-repair]', card);
        if (rep) rep.addEventListener('click', () => g.repairStructure(st));
        const dem = $('[data-demolish]', card);
        if (dem) dem.addEventListener('click', () => {
          g.demolishAt(st.i, st.j);
          g.clearSelection();
        });
      },
    });
  }

  // ---------------------------------------------------------- reward / end modals
  showReward(wave, loot, choices) {
    const g = this.game;
    const lootHTML = Object.entries(loot).map(([k, v]) =>
      `<span class="loot-chip">${icon(RESOURCES[k].icon)}+${v}</span>`).join('');
    const cards = choices.map(u => `
      <button class="upgrade-card" data-upgrade="${u.id}">
        <div class="uic">${icon(u.icon)}</div>
        <h4>${u.name}</h4>
        <p>${u.desc}</p>
      </button>`).join('');
    const html = `
      <div class="modal-kicker">Wave ${wave} survived</div>
      <h2 class="modal-title">The line holds.</h2>
      <p class="modal-sub">Your people cheer from the battlements. Choose a permanent boon before the next raid — the enemy will return stronger.</p>
      <div class="rew-loot">${lootHTML}</div>
      <div class="upgrade-grid">${cards}</div>
      <div class="modal-actions"><span class="modal-note">Choose one boon. It applies immediately.</span></div>
    `;
    this.openModal(html, {
      closeable: false,
      onMount: card => {
        $$('[data-upgrade]', card).forEach(btn => btn.addEventListener('click', () => g.pickUpgrade(btn.dataset.upgrade)));
      },
    });
    this.el.quest.classList.add('hidden');
  }

  showVictory() {
    const g = this.game;
    const st = g.castle.stats();
    const score = g.castle.splendor(g.wavesSurvived);
    const html = `
      <div class="rankup-card">
        <div class="rankup-crest">${icon('i-crown')}</div>
        <div class="modal-kicker">The campaign is won</div>
        <h2 class="modal-title">Warlord Gruk has fallen.</h2>
        <p class="modal-sub">Your castle city stands unbroken after all ${TOTAL_WAVES} waves. The island is yours — and so is the next chapter. Keep every wall, street and tower in Free Build.</p>
        <div class="stats-grid">
          <div class="stat"><b>${TOTAL_WAVES}</b><span>Waves held</span></div>
          <div class="stat"><b>${g.castle.structures.length}</b><span>Structures</span></div>
          <div class="stat"><b>${score}</b><span>Splendor</span></div>
        </div>
        <div class="modal-actions" style="justify-content:center;margin-top:18px">
          <button class="btn gold" data-keep>${icon('i-hammer')}Keep Building</button>
          <button class="btn" data-title>${icon('i-crown')}Return to Title</button>
        </div>
      </div>`;
    this.openModal(html, {
      closeable: false,
      className: 'narrow',
      onMount: card => {
        $('[data-keep]', card).addEventListener('click', () => { this.closeModal(true); g.keepBuilding(); });
        $('[data-title]', card).addEventListener('click', () => { this.closeModal(true); g.returnToTitle(); });
      },
    });
  }

  showDefeat() {
    const g = this.game;
    const score = g.castle.splendor(g.wavesSurvived);
    const html = `
      <div class="rankup-card">
        <div class="rankup-crest" style="color:#d98b7c;border-color:rgba(184,70,51,.55);background:radial-gradient(circle at 40% 30%,rgba(184,70,51,.25),rgba(0,0,0,.3))">${icon('i-skull')}</div>
        <div class="modal-kicker">The keep has fallen</div>
        <h2 class="modal-title" style="color:#f0c3b7">Your city burns.</h2>
        <p class="modal-sub">The raiders broke through and put the keep to the torch. The island remembers what you built — return to the planning table and try a different defense.</p>
        <div class="stats-grid">
          <div class="stat"><b>${g.wavesSurvived}</b><span>Waves held</span></div>
          <div class="stat"><b>${g.castle.structures.length}</b><span>Structures</span></div>
          <div class="stat"><b>${score}</b><span>Splendor</span></div>
        </div>
        <div class="modal-actions" style="justify-content:center;margin-top:18px">
          <button class="btn gold" data-retry>${icon('i-undo')}Retry Wave</button>
          <button class="btn" data-title>Return to Title</button>
        </div>
        <div class="modal-note" style="text-align:center;margin-top:10px">Retry restores your castle exactly as it stood before the wave.</div>
      </div>`;
    this.openModal(html, {
      closeable: false,
      className: 'narrow',
      onMount: card => {
        $('[data-retry]', card).addEventListener('click', () => g.retryWave());
        $('[data-title]', card).addEventListener('click', () => { this.closeModal(true); g.returnToTitle(); });
      },
    });
  }

  // ---------------------------------------------------------- misc modals
  showPause() {
    const g = this.game;
    const sound = g.audio.enabled;
    const html = `
      <button class="modal-close" data-close aria-label="Resume">${icon('i-x')}</button>
      <div class="modal-kicker">${g.sandbox ? 'Free build' : 'Campaign'}</div>
      <h2 class="modal-title">Paused</h2>
      <p class="modal-sub">${g.sandbox ? 'Your city is quiet. The sea is calm.' : `Wave ${Math.min(g.wave, TOTAL_WAVES)} of ${TOTAL_WAVES} · ${g.wavesSurvived} survived`}</p>
      <div class="pause-list">
        <div class="pause-row"><span>Sound</span><button class="switch ${sound ? 'on' : ''}" data-sound aria-label="Toggle sound"></button></div>
      </div>
      <div class="modal-actions">
        <button class="btn gold" data-resume>${icon('i-play')}Resume</button>
        <button class="btn" data-how>${icon('i-eye')}How to Play</button>
      </div>
      <div class="modal-actions" style="margin-top:8px">
        <button class="btn" data-title>Save & Return to Title</button>
        <button class="btn danger" data-restart>New City</button>
      </div>
      <div class="modal-note" style="margin-top:12px">Press Esc to resume. Your campaign is autosaved while you build.</div>
    `;
    this.openModal(html, {
      closeable: true,
      className: 'narrow',
      onMount: card => {
        $('[data-resume]', card).addEventListener('click', () => g.resume());
        $('[data-sound]', card).addEventListener('click', e => {
          const on = g.audio.toggle();
          e.currentTarget.classList.toggle('on', on);
          this.updateSound(on);
        });
        $('[data-how]', card).addEventListener('click', () => { this.howFromPause = true; this.showHowTo(); });
        $('[data-title]', card).addEventListener('click', () => { this.closeModal(true); g.returnToTitle(); });
        $('[data-restart]', card).addEventListener('click', () => {
          this.showConfirm('Found a new city?', 'This campaign castle and its progress will be lost.', 'Abandon & Rebuild', () => {
            this.closeModal(true);
            g.state = 'title';
            g.startNewCampaign(true);
          });
        });
      },
    });
  }

  showHowTo() {
    const html = `
      <button class="modal-close" data-close aria-label="Close">${icon('i-x')}</button>
      <div class="modal-kicker">Field manual</div>
      <h2 class="modal-title">Build it your way.</h2>
      <p class="modal-sub">Steel &amp; Stone is a free-form castle-city builder with real sieges. There is no correct castle — only the one you can hold.</p>
      <div class="how-grid">
        <div class="how-item"><h4>${icon('i-hand')}Place & paint</h4><p>Choose a building from the bottom bar, then tap the island. <b>Walls, gates and roads paint</b> while you drag. Tap <b>Camera</b> to look around and inspect.</p></div>
        <div class="how-item"><h4>${icon('i-house')}Grow a city</h4><p>Houses add <b>population</b>; farms, lumber camps, quarries and markets employ workers and produce resources every 6 seconds. Happiness boosts output.</p></div>
        <div class="how-item"><h4>${icon('i-upgrade')}Upgrade everything</h4><p>Tap any building with the Camera tool to inspect it. Spend resources to upgrade it — more output, more hit points, better towers.</p></div>
        <div class="how-item"><h4>${icon('i-captain')}Command the captain</h4><p>During a siege, <b>tap the ground</b> to send Captain Aldric there. He fights on his own, cleaves nearby raiders, and revives if he falls.</p></div>
        <div class="how-item"><h4>${icon('i-tower')}Hold the line</h4><p>Towers and siege engines fire automatically. Raiders path toward your keep and will break the cheapest route — gates attract them, walls slow them.</p></div>
        <div class="how-item"><h4>${icon('i-horn')}Use your boons</h4><p>Q volleys arrows, W sounds the war horn, E repairs the walls. After every wave, choose a permanent boon for your castle.</p></div>
      </div>
      <div class="modal-actions">
        <span class="modal-note">Tip: houses first, then economy, then walls and towers.</span>
        <button class="btn gold" data-close>Understood</button>
      </div>
    `;
    this.openModal(html, {
      closeable: true,
      className: '',
      onMount: card => {
        $$('[data-close]', card).forEach(btn => btn.addEventListener('click', () => {
          if (this.howFromPause) {
            this.howFromPause = false;
            this.showPause();
          } else {
            this.closeModal(true);
          }
        }));
      },
    });
  }

  showConfirm(title, text, confirmLabel, onConfirm) {
    const html = `
      <button class="modal-close" data-close aria-label="Cancel">${icon('i-x')}</button>
      <div class="modal-kicker">A new beginning</div>
      <h2 class="modal-title">${title}</h2>
      <p class="modal-sub">${text}</p>
      <div class="modal-actions">
        <button class="btn" data-close>Cancel</button>
        <button class="btn gold" data-confirm>${confirmLabel}</button>
      </div>`;
    this.openModal(html, {
      closeable: true,
      className: 'narrow',
      onMount: card => {
        $$('[data-close]', card).forEach(btn => btn.addEventListener('click', () => this.closeModal(true)));
        $('[data-confirm]', card).addEventListener('click', () => { this.closeModal(true); onConfirm(); });
      },
    });
  }
}

