export function rankForSplendor(score) {
  let idx = 0;
  for (let i = 0; i < RANKS.length; i++) if (score >= RANKS[i].min) idx = i;
  return { index: idx, ...RANKS[idx], next: RANKS[idx + 1] || null };
}

