// ------------------------------------------------------------------
// The War for Vareth — six crowns, one heir
// ------------------------------------------------------------------
export const PROLOGUE = {
  kicker: 'The Chronicle · Prologue',
  title: 'The Last Heir',
  lead: 'Vareth is broken.',
  body: [
    'Six crowns knelt to Warlord Gruk and his Iron Horde. The Ashbourne line was put to the sword, its castles given to the fire. You are the last heir — a name whispered in fishing villages, a banner without a wall.',
    'They gave you an island no one wanted: grey rock, a broken keep, and a handful of exiles who still believe. Raise a city from the grass. Feed it. Fortify it. When the warlords come to stamp out the last ember, break them on your walls — and their lands will kneel to the crown they mocked.',
    'You do not need to save the world. You need to take it, one siege at a time.',
  ],
  oath: '“Stone remembers. Steel answers. The Ashbourne banner rises again.”',
  cta: 'Take Up the Crown',
};

export const REGIONS = [
  {
    id: 'home', name: 'The Home Shore', short: 'Home Shore', from: 1, to: 2,
    x: 16, y: 74, icon: 'i-house', flag: 'blue',
    tag: 'Chapter I',
    lore: 'A grey island, a broken keep, and the last oath of House Ashbourne. Every raider that falls here feeds the legend.',
    claim: 'The Home Shore is yours. Exiles gather beneath your banner — and your name crosses the water for the first time.',
  },
  {
    id: 'greenvale', name: 'Greenvale', short: 'Greenvale', from: 3, to: 4,
    x: 34, y: 47, icon: 'i-farm', flag: 'green',
    tag: 'Chapter II',
    lore: 'The old kingdom\'s granary. Its shield wall was bought with Gruk\'s silver; its fields will feed your armies instead.',
    claim: 'Greenvale swears to you. Grain carts roll toward your island, and the first true kingdom answers your call.',
  },
  {
    id: 'ashen', name: 'The Ashen March', short: 'Ashen March', from: 5, to: 6,
    x: 55, y: 66, icon: 'i-tent', flag: 'red',
    tag: 'Chapter III',
    lore: 'Burned orchards and berserker camps. The north has tasted blood and wants more. Give it steel instead.',
    claim: 'The Ashen March has a new lord. Berserker banners are cut down and hung from your walls.',
  },
  {
    id: 'frostfang', name: 'Frostfang Pass', short: 'Frostfang', from: 7, to: 7,
    x: 71, y: 29, icon: 'i-tower', flag: 'blue',
    tag: 'Chapter IV',
    lore: 'The only road to the Iron Citadel. Snow, stone, and an army that has never broken. Beyond it waits the warlord himself.',
    claim: 'Frostfang falls. The road to Gruk\'s throne lies open, and the north holds its breath.',
  },
  {
    id: 'citadel', name: 'Citadel of Gruk', short: 'Iron Citadel', from: 8, to: 8,
    x: 87, y: 48, icon: 'i-skull', flag: 'red',
    tag: 'Chapter V',
    lore: 'The Iron Horde\'s throne. Break the Warlord and every crown on the map will answer to yours.',
    claim: 'Warlord Gruk is dead. The Iron Horde scatters. Six crowns wait for the last Ashbourne to speak.',
  },
];

export function regionForWave(wave) {
  return REGIONS.find(r => wave >= r.from && wave <= r.to) || REGIONS[REGIONS.length - 1];
}

export function isRegionConquered(region, wavesSurvived) {
  return wavesSurvived >= region.to;
}

export const CHRONICLES = [
  'The first raiders break on your new walls. Exiles gather beneath your banner.',
  'The Home Shore is yours. Your name crosses the water for the first time.',
  'Shieldmen kneel or die. Greenvale\'s granaries are open to your people.',
  'Greenvale swears to you. Grain carts roll toward your island.',
  'The berserkers\' fury breaks. The Ashen March has a new lord.',
  'The north is yours. Only the pass and the citadel remain.',
  'Frostfang falls. The road to Gruk\'s throne lies open.',
  'Warlord Gruk is dead. The world bends the knee.',
];

export const VICTORY = {
  kicker: 'The Chronicle · Finale',
  title: 'The World Bends the Knee',
  body: 'The Iron Horde is broken. Six crowns send envoys to your island — not to demand tribute, but to swear. The last heir has become the first sovereign of a united Vareth. Your castle city, raised from a grey rock and a broken keep, is now the seat of the world.',
  oath: '“They gave us an island no one wanted. We gave them a world.”',
};

