252:   // ---------------------------------------------------------- economy
253:   canAfford(cost) {
254:     if (this.sandbox) return true;
255:     for (const [k, v] of Object.entries(cost || {})) {
256:       if ((this.resources[k] || 0) < v) return false;
257:     }
258:     return true;
259:   }
260: 
261:   missingResources(cost) {
262:     const miss = {};
263:     for (const [k, v] of Object.entries(cost || {})) {
264:       const have = this.resources[k] || 0;
265:       if (have < v) miss[k] = Math.ceil(v - have);
266:     }
267:     return miss;
268:   }
269: 
270:   spend(cost) {
271:     if (this.sandbox) return;
272:     for (const [k, v] of Object.entries(cost || {})) {
273:       this.resources[k] = Math.max(0, (this.resources[k] || 0) - v);
274:     }
275:     this.ui?.markResourcesDirty();
276:   }
277: 
278:   grant(cost, silent = false) {
279:     for (const [k, v] of Object.entries(cost || {})) {
280:       this.resources[k] = (this.resources[k] || 0) + v;
281:     }
282:     this.ui?.markResourcesDirty();
283:     if (!silent) this.ui?.pulseAll();
284:   }
285: 
286:   stats() { return this.castle.stats(); }
287: 
288:   productionMultiplier() {
289:     const st = this.stats();
290:     let factor = 0.8 + st.happiness / 250;
291:     if (this.hasUpgrade('bounty')) factor *= 1.4;
292:     factor *= 1 + this.rankIndex * 0.02;
293:     return factor;
294:   }
295: 
296:   tickEconomy() {
297:     const st = this.castle.stats();
298:     const mult = this.productionMultiplier();
299:     const gained = {};
300:     for (const [k, v] of Object.entries(st.production)) {
301:       if (v <= 0) continue;
302:       let amount = v * mult;
303:       if (k === 'gold' && this.hasUpgrade('tax')) amount *= 1.5;
304:       this.resources[k] = (this.resources[k] || 0) + amount;
305:       gained[k] = Math.round(amount * 10) / 10;
306:     }
307:     if (Object.keys(gained).length) {
308:       this.ui?.markResourcesDirty();
309:       this.ui?.pulseResources(Object.keys(gained));
310:     }
311:     this.tickTimer = TICK;
312:   }
313: 
314:   getCost(type) {
315:     let cost = { ...costFor(type, 1) };
316:     if (this.hasUpgrade('stone') && (type === 'wall' || type === 'gate')) {
317:       cost.stone = Math.max(1, Math.round((cost.stone || 0) * 0.75));
318:     }
319:     return cost;
320:   }
321: 
322:   getUpgradeCost(st) {
323:     let cost = upgradeCostFor(st);
324:     if (!cost) return null;
325:     if (this.hasUpgrade('stone') && (st.type === 'wall' || st.type === 'gate')) {
326:       cost.stone = Math.max(1, Math.round((cost.stone || 0) * 0.75));
327:     }
328:     return cost;
329:   }
330: 
331:   canStaff(type, level = 1, oldLevel = 0) {
332:     if (this.sandbox) return true;
333:     const stats = this.stats();
334:     const delta = workerCostFor(type, level) - workerCostFor(type, oldLevel);
335:     if (delta <= 0) return true;
336:     return stats.used + delta <= stats.capacity;
337:   }
338: 
339:   staffMissing(type, level = 1, oldLevel = 0) {
340:     const stats = this.stats();
341:     const delta = workerCostFor(type, level) - workerCostFor(type, oldLevel);
342:     return Math.max(0, stats.used + delta - stats.capacity);
343:   }
344: 
345:   hasUpgrade(id) { return this.upgrades.includes(id); }
346: 
347:   combatBonuses() {
348:     return {
349:       towerDamageMult: (this.hasUpgrade('fletch') ? 1.25 : 1) * (1 + this.rankIndex * 0.04),
350:       fireRateMult: this.hasUpgrade('rapid') ? 1.2 : 1,
351:       siegeDamageMult: this.hasUpgrade('siege') ? 1.35 : 1,
352:       heroHpMult: (this.hasUpgrade('medic') ? 1.4 : 1) * (this.hasUpgrade('hero') ? 1.3 : 1),
353:       heroDmgMult: (this.hasUpgrade('hero') ? 1.5 : 1),
354:     };
355:   }
