502:   tryPlace(type, i, j) {
503:     if (!type) return;
504:     if (this.state !== 'build' && this.state !== 'sandbox') return;
505:     if (this.castle.structures.length >= 140) { this.ui.toast('Your castle is at capacity.', 'bad'); return; }
506:     const valid = this.castle.canPlace(type, i, j);
507:     if (!valid.ok) { this.audio.error(); this.ui.toast(valid.reason, 'bad'); return; }
508:     const cost = this.getCost(type);
509:     if (!this.canAfford(cost)) {
510:       this.audio.error();
511:       const missing = this.missingResources(cost);
512:       const txt = Object.entries(missing).map(([k, v]) => `${Math.ceil(v)} ${RESOURCES[k].name.toLowerCase()}`).join(', ');
513:       this.ui.toast(`You need ${txt}.`, 'bad');
514:       return;
515:     }
516:     if (type !== 'road' && !this.canStaff(type, 1)) {
517:       this.audio.error();
518:       this.ui.toast(`Not enough workers. Build a house for ${this.staffMissing(type, 1)} more people.`, 'bad');
519:       return;
520:     }
521:     const st = this.castle.place(type, i, j, { force: true });
522:     if (!st) return;
523:     this.spend(cost);
524:     this.undoStack.push({ type, i, j, cost });
525:     if (this.undoStack.length > 40) this.undoStack.shift();
526:     this.audio.place();
527:     this.saveSoon();
528:     this.ui.markCityDirty();
529:     this.checkQuests();
530:     if (!this.defsHintShown && type === 'house') {
