535:   demolishAt(i, j, quiet = false) {
536:     const st = this.castle.getStructureAt(i, j);
537:     if (st) {
538:       if (st.type === 'keep') { this.ui.toast('The keep cannot be razed.', 'bad'); return; }
539:       const refund = this.refundFor(st);
540:       this.castle.removeStructure(st);
541:       this.grant(refund, true);
542:       if (this.selectedStructure === st) this.clearSelection();
543:       this.saveSoon();
544:       this.ui.markCityDirty();
545:       if (!quiet) {
546:         this.ui.toast(`Razed ${STRUCTURES[st.type].name}. Recovered ${this.costText(refund)}.`, 'good');
547:         this.audio.raze();
548:       }
549:       return;
550:     }
551:     const key = cellKey(i, j);
552:     if (this.castle.roads.has(key)) {
553:       this.castle.removeRoad(i, j, { quiet: quiet });
554:       if (!this.sandbox) this.resources.stone += 1;
555:       this.saveSoon();
556:       this.ui.markCityDirty();
557:     }
558:   }
