560:   refundFor(st) {
561:     const def = STRUCTURES[st.type];
562:     const refund = {};
563:     const add = (cost, factor) => {
564:       for (const [k, v] of Object.entries(cost || {})) refund[k] = (refund[k] || 0) + Math.floor(v * factor);
565:     };
566:     add(costFor(st.type, 1), 0.5);
567:     for (let l = 1; l < st.level; l++) add(costFor(st.type, l + 1), 0.35);
568:     return refund;
569:   }
