708:     this.wavesSurvived = Math.max(this.wavesSurvived, n);
709:     this.bestWave = Math.max(this.bestWave, n);
710:     try { localStorage.setItem(BEST_KEY, String(this.bestWave)); } catch {}
711:     this.wave = n + 1;
712:     const loot = { gold: 80 + n * 25, wood: 50 + n * 18, stone: 60 + n * 22, food: 35 + n * 12 };
713:     this.grant(loot, true);
