736:   rewardChoices() {
737:     const pool = UPGRADES.filter(u => !this.hasUpgrade(u.id));
738:     for (let i = pool.length - 1; i > 0; i--) {
739:       const j = (Math.random() * (i + 1)) | 0;
740:       [pool[i], pool[j]] = [pool[j], pool[i]];
741:     }
742:     const out = pool.slice(0, 3);
743:     while (out.length < 3) out.push({ id: 'spoils', name: 'Spoils of War', icon: 'i-coin', desc: 'Gain 250 gold, 160 wood and 160 stone immediately.' });
