596:     rows.push(`<div class="bld-stat"><span>${icon('i-shield')}Integrity</span><b>${Math.ceil(st.hp)} / ${st.maxHp}</b></div>`);
597:     if (def.population) rows.push(`<div class="bld-stat"><span>${icon('i-people')}Population</span><b>+${populationFor(st.type, level)} capacity</b></div>`);
598:     if (def.workers) rows.push(`<div class="bld-stat"><span>${icon('i-people')}Workers</span><b>${workerCostFor(st.type, level)}</b></div>`);
599:     const prod = productionFor(st.type, level);
600:     if (Object.keys(prod).length) {
601:       const txt = Object.entries(prod).map(([k, v]) => `${icon(RESOURCES[k].icon)} +${(Math.round(v * 10) / 10)}`).join(' ');
602:       rows.push(`<div class="bld-stat"><span>${icon('i-farm')}Per 6s</span><b>${txt}</b></div>`);
603:     }
604:     if (def.happiness) rows.push(`<div class="bld-stat"><span>${icon('i-happy')}Happiness</span><b>+${happinessFor(st.type, level)}</b></div>`);
605:     if (def.garrison) rows.push(`<div class="bld-stat"><span>${icon('i-captain')}Garrison</span><b>${garrisonFor(st.type, level)} guards</b></div>`);
606:     const tower = towerStatsFor(st.type, level);
