631:         Costs ${g.costText(cost)}${def.workers ? ` · +1 worker` : ''}${missingWorkers > 0 ? ` · <span style="color:#e08b7b">needs ${missingWorkers} more population</span>` : ''}.</p>
632:         <div class="up-cost">${this.costHTML(cost, true)}</div>
633:       </div>`;
634:     } else if (def.maxLevel) {
635:       upgradeHTML = `<div class="bld-up"><h4>${icon('i-star')}Masterwork</h4><p>This building is at its highest level. It stands as a monument to your city.</p></div>`;
