638:     const html = `
639:       <button class="modal-close" data-close aria-label="Close">${icon('i-x')}</button>
640:       <div class="bld-head">
641:         <div class="bld-art">${icon(def.icon)}</div>
642:         <div class="bld-headtext">
643:           <div class="modal-kicker">${def.category} · Level ${level}${def.maxLevel ? ` / ${def.maxLevel}` : ''}</div>
644:           <h2 class="modal-title">${def.name}</h2>
645:         </div>
646:       </div>
647:       <p class="modal-sub">${def.desc}</p>
648:       <div class="bld-stats">${rows.join('')}</div>
