230:     if (!def) return { ok: false, reason: 'Unknown building' };
231:     if (!def.road && this.structures.length >= 140) return { ok: false, reason: 'Castle is at capacity' };
232:     if (i < 0 || j < 0 || i + def.w > GRID || j + def.h > GRID) return { ok: false, reason: 'Outside the island' };
233:     if (def.road) {
234:       if (this.roads.has(cellKey(i, j))) return { ok: false, reason: 'Road already paved' };
235:       if (this.cells[cellKey(i, j)]) return { ok: false, reason: 'Blocked by a building' };
236:       return { ok: true };
237:     }
238:     for (let a = 0; a < def.w; a++) {
239:       for (let b = 0; b < def.h; b++) {
240:         const s = this.cells[cellKey(i + a, j + b)];
241:         if (s) return { ok: false, reason: 'Something is already built here' };
242:       }
243:     }
244:     // keep a one-tile breathing space around buildings, except walls/roads
245:     if (type !== 'wall' && type !== 'gate' && type !== 'tower') {
246:       for (let a = -1; a <= def.w; a++) {
247:         for (let b = -1; b <= def.h; b++) {
248:           if (a >= 0 && a < def.w && b >= 0 && b < def.h) continue;
249:           const s = this.getStructureAt(i + a, j + b);
250:           if (s && s.type === 'keep') return { ok: false, reason: 'Leave room around the keep' };
251:         }
252:       }
253:     }
254:     return { ok: true };
255:   }
256: 
257:   // ---------------- building / demolishing ----------------
258:   place(type, i, j, opts = {}) {
259:     const def = STRUCTURES[type];
260:     if (!def) return null;
261:     if (def.road) return this.paintRoad(i, j, opts);
262:     if (!opts.force) {
263:       const valid = this.canPlace(type, i, j);
264:       if (!valid.ok) return null;
265:     }
266:     const level = opts.level || 1;
267:     const st = {
268:       id: this.nextId++, type, i, j, w: def.w, h: def.h,
269:       level,
270:       maxHp: this.calcMaxHp(type, level),
271:       hp: opts.hp ?? this.calcMaxHp(type, level),
272:       group: null, bar: null, height: 4,
273:       aimGroup: null, arm: null, muzzleY: 2,
274:       smokeTimer: 0, spawnAnim: opts.animate === false ? 1 : 0,
275:       selected: false,
276:       wallSlot: null,
277:     };
278:     if (opts.hp != null) st.hp = Math.min(st.hp, st.maxHp);
279:     for (let a = 0; a < def.w; a++) for (let b = 0; b < def.h; b++) this.cells[cellKey(i + a, j + b)] = st;
280:     // remove roads underneath
281:     let removedRoad = false;
282:     for (let a = 0; a < def.w; a++) for (let b = 0; b < def.h; b++) {
283:       if (this.roads.delete(cellKey(i + a, j + b))) removedRoad = true;
284:     }
285:     if (removedRoad) this.roadDirty = true;
286: 
287:     const c = this.centerOf(st);
288:     st.group = type === 'keep' ? this.buildKeep(st) : this.buildVisual(type, level, st);
289:     st.group.position.set(c.x, 0, c.z);
290:     this.scene.add(st.group);
291:     if (st.spawnAnim < 1) st.group.scale.y = 0.05;
292: 
293:     this.structures.push(st);
294:     this.byId.set(st.id, st);
295:     if (type === 'wall') this.wallDirty = true;
296:     if (type === 'wall' || type === 'gate') this.markNeighborWalls(i, j);
297:     if (!opts.quiet) {
298:       dustBurst(this.fx, new THREE.Vector3(c.x, 0.5, c.z), 0xc6b89b, 16, 2.2);
299:       this.audio?.build();
300:     }
301:     if (type === 'keep') this.ensureBar(st, true);
302:     this.game?.onCityChanged();
303:     return st;
304:   }
305: 
306:   paintRoad(i, j, opts = {}) {
307:     if (i < 0 || j < 0 || i >= GRID || j >= GRID) return null;
308:     const key = cellKey(i, j);
309:     if (this.roads.has(key) || this.cells[key]) return null;
310:     this.roads.set(key, { i, j });
311:     this.roadDirty = true;
312:     if (!opts.quiet) this.audio?.place();
313:     return { type: 'road', i, j };
314:   }
315: 
316:   removeRoad(i, j, opts = {}) {
317:     const key = cellKey(i, j);
318:     if (!this.roads.delete(key)) return false;
319:     this.roadDirty = true;
320:     if (!opts.quiet) this.audio?.place();
321:     return true;
322:   }
323: 
324:   markNeighborWalls(i, j) {
325:     this.wallDirty = true;
326:   }
327: 
328:   removeStructure(st, opts = {}) {
329:     if (!st || st.type === 'keep') return false;
330:     const def = STRUCTURES[st.type];
331:     for (let a = 0; a < st.w; a++) for (let b = 0; b < st.h; b++) {
332:       const key = cellKey(st.i + a, st.j + b);
333:       if (this.cells[key] === st) this.cells[key] = null;
334:     }
335:     this.structures = this.structures.filter(s => s !== st);
336:     this.byId.delete(st.id);
337:     if (st.group) {
338:       const c = this.centerOf(st);
339:       dustBurst(this.fx, new THREE.Vector3(c.x, 0.8, c.z), 0xb3a487, 26, 3.2);
340:       this.scene.remove(st.group);
341:       st.group.traverse(o => { if (o.isMesh) o.geometry?.dispose?.(); });
342:     }
343:     if (st.bar) { this.scene.remove(st.bar.group); st.bar = null; }
344:     if (st.type === 'wall') {
345:       this.wallDirty = true;
346:       // refresh neighbours in next rebuild
347:     }
348:     if (this.selection === st) this.select(null);
349:     if (!opts.quiet) this.audio?.raze();
350:     this.game?.onCityChanged();
351:     return true;
352:   }
353: 
354:   upgrade(st) {
355:     const def = STRUCTURES[st.type];
356:     if (!def || !def.maxLevel || st.level >= def.maxLevel) return false;
357:     st.level++;
358:     st.maxHp = this.calcMaxHp(st.type, st.level);
359:     st.hp = st.maxHp;
360:     const c = this.centerOf(st);
361:     if (st.group) {
362:       this.scene.remove(st.group);
363:       st.group.traverse(o => { if (o.isMesh) o.geometry?.dispose?.(); });
364:     }
365:     st.group = this.buildVisual(st.type, st.level, st);
366:     st.group.position.set(c.x, 0, c.z);
367:     st.group.scale.y = 0.72;
368:     this.scene.add(st.group);
369:     sparkBurst(this.fx, new THREE.Vector3(c.x, st.height * 0.6, c.z), 0xffd27a, 30);
370:     dustBurst(this.fx, new THREE.Vector3(c.x, 0.5, c.z), 0xd9c9a8, 16, 2.4);
371:     if (st.bar) this.updateBar(st);
372:     this.game?.onCityChanged();
373:     return true;
374:   }
375: 
376:   calcMaxHp(type, level) {
377:     return Math.round(maxHpFor(type, level) * (1 + (this.bonuses.masonry || 0)));
378:   }
379: 
380:   applyMasonry() {
381:     for (const st of this.structures) {
382:       const oldMax = st.maxHp;
383:       const newMax = this.calcMaxHp(st.type, st.level);
384:       if (newMax > oldMax) {
385:         st.hp += (newMax - oldMax);
386:         st.maxHp = newMax;
387:       }
388:       this.updateBar(st);
389:     }
390:   }
391: 
392:   // ---------------- combat damage ----------------
393:   damage(st, amount, source) {
394:     if (!st || st.hp <= 0) return;
395:     st.hp = Math.max(0, st.hp - amount);
396:     if (st.type === 'wall') this.updateWallColor(st);
397:     if (st.type === 'keep') this.ensureBar(st, true);
398:     if (st.hp > 0) {
399:       if (st.hp < st.maxHp && !st.bar) this.ensureBar(st, st.type === 'keep');
400:       this.updateBar(st);
401:       if (Math.random() < 0.28) {
402:         const c = this.centerOf(st);
403:         this.fx.burst(new THREE.Vector3(c.x + rand(-1, 1), 1 + Math.random() * st.height, c.z + rand(-1, 1)), {
404:           count: 3, color: 0xc9bda3, speed: 2, life: 0.7, size: 5, gravity: -2, drag: 1, up: 0.4, alpha: 0.7,
405:         });
406:       }
407:     } else {
408:       if (st.type === 'keep') {
409:         this.game?.onKeepDestroyed();
410:         return;
411:       }
412:       const c = this.centerOf(st);
413:       dustBurst(this.fx, new THREE.Vector3(c.x, 0.8, c.z), 0xb3a487, 30, 3.6);
414:       sparkBurst(this.fx, new THREE.Vector3(c.x, 1.4, c.z), 0xd9a24c, 12);
415:       this.soundCrumble();
416:       this.removeStructure(st, { quiet: true });
417:       this.game?.onStructureDestroyed?.(st);
418:     }
419:   }
420: 
421:   soundCrumble() {
422:     this.audio?.raze();
423:   }
424: 
425:   repairAll(frac) {
426:     let healed = 0;
427:     for (const st of this.structures) {
428:       if (st.hp >= st.maxHp) continue;
429:       const add = Math.min(st.maxHp - st.hp, st.maxHp * frac);
430:       st.hp += add;
431:       healed += add;
432:       this.updateBar(st);
433:       if (st.type === 'wall') this.updateWallColor(st);
434:     }
435:     if (healed > 0) this.game?.onCityChanged();
436:     return healed;
437:   }
438: 
439:   ensureBar(st, force = false) {
440:     if (st.bar) return st.bar;
441:     const w = st.type === 'keep' ? 4.4 : Math.max(1.8, Math.min(3, (st.w + st.h) * 0.55));
442:     const group = new THREE.Group();
443:     const bgMat = basic(0x15181a, { transparent: true, opacity: 0.72, depthTest: false, depthWrite: false });
444:     const bg = new THREE.Mesh(new THREE.PlaneGeometry(w, st.type === 'keep' ? 0.34 : 0.2), bgMat);
445:     bg.renderOrder = 90;
446:     const fillMat = basic(0x78af5a, { depthTest: false, depthWrite: false });
447:     const fill = new THREE.Mesh(new THREE.PlaneGeometry(w - 0.08, st.type === 'keep' ? 0.24 : 0.11), fillMat);
448:     fill.position.z = 0.002;
449:     fill.renderOrder = 91;
450:     group.add(bg, fill);
451:     group.renderOrder = 90;
452:     group.visible = false;
453:     this.scene.add(group);
454:     st.bar = { group, fill, fillMat, bgMat, w, force };
455:     this.updateBar(st);
456:     return st.bar;
457:   }
458: 
459:   updateBar(st) {
460:     if (!st.bar) return;
461:     const ratio = Math.max(0, st.hp / st.maxHp);
462:     st.bar.fill.scale.x = Math.max(0.02, ratio);
463:     st.bar.fill.position.x = -(st.bar.w - 0.08) * (1 - ratio) / 2;
464:     const c = st.bar.fillMat.color;
465:     if (ratio > 0.55) c.setHex(0x78af5a);
466:     else if (ratio > 0.28) c.setHex(0xd2a84a);
467:     else c.setHex(0xc45542);
468:     st.bar.group.visible = st.hp < st.maxHp || st.type === 'keep';
469:   }
470: 
471:   // ---------------- city stats ----------------
472:   stats() {
473:     let capacity = 10;
474:     let used = 0;
475:     let happiness = 55;
476:     const production = { gold: 0, wood: 0, stone: 0, food: 0 };
477:     let garrison = 0;
478:     for (const st of this.structures) {
479:       const def = STRUCTURES[st.type];
480:       capacity += populationFor(st.type, st.level);
481:       used += workerCostFor(st.type, st.level);
482:       happiness += happinessFor(st.type, st.level);
483:       garrison += garrisonFor(st.type, st.level);
484:       const prod = productionFor(st.type, st.level);
485:       for (const [k, v] of Object.entries(prod)) production[k] += v;
486:     }
487:     const popPenalty = Math.max(0, (used - 36) * 0.25);
488:     happiness = Math.max(5, Math.min(100, happiness - popPenalty));
489:     return { capacity, used, happiness, production, garrison: Math.min(8, garrison) };
490:   }
491: 
492:   splendor(wavesSurvived = 0) {
493:     let score = 15 + wavesSurvived * 25 + this.roads.size * 0.2;
494:     for (const st of this.structures) {
495:       if (st.type === 'wall') score += 0.8;
496:       else if (st.type === 'keep') score += 10;
497:       else score += 5 + st.level * 4 + (STRUCTURES[st.type].tower ? 3 : 0);
498:     }
499:     return Math.round(score);
500:   }
