502:   // ---------------- serialization ----------------
503:   serialize() {
504:     return {
505:       structures: this.structures.map(st => ({ type: st.type, i: st.i, j: st.j, level: st.level, hp: Math.round(st.hp) })),
506:       roads: [...this.roads.values()].map(r => [r.i, r.j]),
507:     };
508:   }
509: 
510:   reset(opts = {}) {
511:     this.clearAll();
512:     const st = this.place('keep', KEEP_I, KEEP_J, { force: true, quiet: true, animate: false });
513:     if (st) st.hp = st.maxHp = this.calcMaxHp('keep', 1);
514:     this.wallDirty = true;
515:     this.roadDirty = true;
516:     return st;
517:   }
518: 
519:   load(data) {
520:     this.clearAll();
521:     if (data?.structures?.length) {
522:       for (const s of data.structures) {
523:         const def = STRUCTURES[s.type];
524:         if (!def) continue;
525:         this.place(s.type, s.i, s.j, { force: true, quiet: true, animate: false, level: s.level || 1, hp: s.hp });
526:       }
527:     }
528:     if (!this.getStructureAt(KEEP_I, KEEP_J)) {
529:       this.place('keep', KEEP_I, KEEP_J, { force: true, quiet: true, animate: false });
530:     }
531:     if (data?.roads) {
532:       for (const [i, j] of data.roads) this.paintRoad(i, j, { quiet: true });
533:     }
534:     // place() may have removed roads under structures; re-add only valid ones
535:     this.wallDirty = true;
536:     this.roadDirty = true;
537:     this.game?.onCityChanged();
538:   }
539: 
540:   clearAll() {
541:     for (const st of [...this.structures]) {
542:       if (st.group) {
543:         this.scene.remove(st.group);
544:         st.group.traverse(o => { if (o.isMesh) o.geometry?.dispose?.(); });
545:       }
546:       if (st.bar) this.scene.remove(st.bar.group);
547:     }
548:     this.structures = [];
549:     this.byId.clear();
550:     this.cells.fill(null);
551:     this.roads.clear();
552:     this.banners = [];
553:     this.windmills = [];
554:     this.selection = null;
555:     this.selectedRing.visible = false;
556:     this.wallDirty = true;
557:     this.roadDirty = true;
558:   }
