560:   // ---------------- visual builders ----------------
561:   buildVisual(type, level, st) {
562:     switch (type) {
563:       case 'tower': return this.buildTower(level, st);
564:       case 'gate': return this.buildGate(level, st);
565:       case 'house': return this.buildHouse(level, st);
566:       case 'farm': return this.buildFarm(level, st);
567:       case 'lumber': return this.buildLumber(level, st);
568:       case 'quarry': return this.buildQuarry(level, st);
569:       case 'market': return this.buildMarket(level, st);
570:       case 'tavern': return this.buildTavern(level, st);
571:       case 'chapel': return this.buildChapel(level, st);
572:       case 'garden': return this.buildGarden(level, st);
573:       case 'barracks': return this.buildBarracks(level, st);
574:       case 'ballista': return this.buildBallista(level, st);
575:       case 'catapult': return this.buildCatapult(level, st);
576:       default: return new THREE.Group();
577:     }
