588:   buildTower(level, st) {
589:     const g = new THREE.Group();
590:     const h = 6.6 + level * 1.05;
591:     cyl(g, 2.45, 2.75, 0.7, COLORS.stoneDark, 0, 0.35, 0, { seg: 12 });
592:     cyl(g, 2.05, 2.35, h, COLORS.stone, 0, 0.7 + h / 2, 0, { seg: 12 });
593:     cyl(g, 2.55, 2.55, 0.34, COLORS.stoneLight, 0, h + 0.9, 0, { seg: 12 });
594:     // merlons
595:     const topY = h + 1.08;
596:     for (let k = 0; k < 9; k++) {
597:       const a = (k / 9) * Math.PI * 2;
598:       box(g, 0.56, 0.58, 0.42, COLORS.stoneLight, Math.cos(a) * 2.28, topY + 0.29, Math.sin(a) * 2.28, { ry: -a });
599:     }
600:     // door and windows
601:     box(g, 1.02, 1.8, 0.16, COLORS.woodDark, 0, 1.55, 2.22);
602:     box(g, 1.18, 2.0, 0.1, COLORS.stoneLight, 0, 1.6, 2.29);
603:     box(g, 0.96, 1.65, 0.2, COLORS.woodDark, 0, 1.5, 2.34, { cast: false });
604:     for (let k = 0; k < 3; k++) {
605:       const a = 0.55 + k * 1.5;
606:       box(g, 0.52, 0.95, 0.12, 0x3b3630, Math.cos(a) * 2.12, 3.2 + k * 0.6, Math.sin(a) * 2.12, { ry: -a, cast: false });
607:     }
608:     // little archer silhouette
609:     if (level >= 2) {
610:       cyl(g, 0.18, 0.24, 0.95, 0x6d7f92, 0.9, h + 1.3, 0.3, { seg: 5 });
611:       sphere(g, 0.18, 0xd8b38c, 0.9, h + 1.95, 0.3, { detail: 0 });
612:     }
