646:   buildHouse(level, st) {
647:     const g = new THREE.Group();
648:     const wallH = 2.2 + (level - 1) * 0.32;
649:     box(g, 4.7, 0.3, 4.3, COLORS.stoneDark, 0, 0.15, 0);
