653:     for (const sx of [-1, 1]) for (const sz of [-1, 1]) box(g, 0.19, wallH, 0.19, timber, sx * 2.1, wallH / 2 + 0.3, sz * 1.9);
654:     for (const sz of [-1, 1]) {
655:       box(g, 4.45, 0.16, 0.12, timber, 0, wallH + 0.22, sz * 2.03);
656:       box(g, 4.45, 0.16, 0.12, timber, 0, 0.48, sz * 2.03);
657:       for (const sx of [-1.1, 1.1]) box(g, 0.15, wallH, 0.12, timber, sx, wallH / 2 + 0.3, sz * 2.03);
658:     }
