667:     // chimney
668:     box(g, 0.62, 1.7, 0.62, COLORS.stoneDark, 1.55, wallH + 1.35, -0.9);
669:     // door & windows
670:     box(g, 1.0, 1.8, 0.14, COLORS.woodDark, 0, 1.2, 2.08);
671:     box(g, 0.78, 0.9, 0.06, 0xf2c777, -1.35, 1.55, 2.08, { cast: false, mat: new THREE.MeshStandardMaterial({ color: 0xf2c777, emissive: 0x5a3c10, emissiveIntensity: 0.7, roughness: 0.8 }) });
672:     box(g, 0.78, 0.9, 0.06, 0xf2c777, 1.35, 1.55, 2.08, { cast: false, mat: new THREE.MeshStandardMaterial({ color: 0xf2c777, emissive: 0x5a3c10, emissiveIntensity: 0.7, roughness: 0.8 }) });
