687:   cropGeometry(rows, cols, color) {
688:     const parts = [];
689:     for (let r = 0; r < rows; r++) {
690:       for (let c = 0; c < cols; c++) {
691:         const g = new THREE.ConeGeometry(0.16, 0.62, 4);
692:         g.translate(-3.2 + c * 0.92, 0.35, -3.0 + r * 0.82);
693:         const col = new THREE.Color(color);
694:         const arr = new Float32Array(g.attributes.position.count * 3);
695:         for (let i = 0; i < g.attributes.position.count; i++) { arr[i * 3] = col.r; arr[i * 3 + 1] = col.g; arr[i * 3 + 2] = col.b; }
696:         g.setAttribute('color', new THREE.BufferAttribute(arr, 3));
697:         parts.push(g);
698:       }
699:     }
700:     const merged = mergeGeometries(parts, false);
701:     parts.forEach(p => p.dispose());
702:     return merged;
703:   }
