347:   update(dt, enemies, active, keepPos) {
348:     if (!this.group.visible) {
349:       if (!this.alive && active) {
350:         this.respawnTimer -= dt;
351:         if (this.respawnTimer <= 0) {
352:           this.alive = true;
353:           this.hp = this.maxHp;
354:           this.x = keepPos.x + 2.4; this.z = keepPos.z + 6.4;
355:           this.group.visible = true; this.ring.visible = true;
356:           this.command.set(this.x, 0, this.z); this.hasCommand = false;
357:         }
358:       }
359:       return;
360:     }
361:     if (!this.alive) return;
362:     this.attackCd = Math.max(0, this.attackCd - dt);
363:     this.attackAnim = Math.max(0, this.attackAnim - dt * 3.4);
364:     let target = null;
365:     let best = Infinity;
366:     for (const e of enemies) {
367:       if (e.hp <= 0) continue;
368:       const d = Math.hypot(e.x - this.x, e.z - this.z);
369:       if (d < best) { best = d; target = e; }
370:     }
371:     if (target && best < 10.5) {
372:       this.target = target;
373:       const dx = target.x - this.x, dz = target.z - this.z;
374:       const dist = Math.hypot(dx, dz);
375:       this.yaw = Math.atan2(dx, dz);
376:       if (dist > 1.75) {
377:         this.x += (dx / dist) * this.speed * dt;
378:         this.z += (dz / dist) * this.speed * dt;
379:         this.anim += dt * 8;
380:       } else if (this.attackCd <= 0) {
381:         this.attackCd = 0.78;
382:         this.attackAnim = 1;
383:         this.audio?.sword();
384:         // cleave nearby enemies
385:         let hits = 0;
386:         for (const e of enemies) {
387:           if (e.hp <= 0) continue;
388:           const d2 = Math.hypot(e.x - this.x, e.z - this.z);
389:           if (d2 < 3.1) {
390:             hits++;
391:             this.hitEnemy(e, this.damage + rand(-5, 8));
392:             if (e.hp <= 0) this.onKill?.(e);
393:           }
394:         }
395:         if (hits) sparkBurst(this.fx, new THREE.Vector3(target.x, 1.1, target.z), 0xffd27a, 8);
396:       }
397:     } else {
398:       this.target = null;
399:       const tx = this.hasCommand ? this.command.x : keepPos.x + 2.4;
400:       const tz = this.hasCommand ? this.command.z : keepPos.z + 6.4;
401:       const dx = tx - this.x, dz = tz - this.z;
402:       const dist = Math.hypot(dx, dz);
403:       if (dist > 0.7) {
404:         this.yaw = Math.atan2(dx, dz);
405:         this.x += (dx / dist) * this.speed * dt;
406:         this.z += (dz / dist) * this.speed * dt;
407:         this.anim += dt * 7;
408:       } else if (this.hasCommand) {
409:         this.hasCommand = false;
410:       }
411:     }
412:     // keep inside reasonable area
413:     this.x = clamp(this.x, -43, 43);
414:     this.z = clamp(this.z, -43, 43);
415:     this.group.position.set(this.x, 0, this.z);
416:     this.group.rotation.y = dampAngle(this.group.rotation.y, this.yaw, 12, dt);
417:     const bob = Math.sin(this.anim) * 0.045;
418:     this.group.position.y = bob;
419:     this.legL.rotation.x = Math.sin(this.anim) * 0.4;
420:     this.legR.rotation.x = -Math.sin(this.anim) * 0.4;
421:     this.armR.rotation.x = -this.attackAnim * 2.3;
422:     this.armR.rotation.z = -0.2 + this.attackAnim * 0.8;
423:     this.armL.rotation.x = -0.15 + Math.sin(this.anim * 0.7) * 0.05;
424:     this.cape.rotation.x = 0.18 + Math.sin(this.anim * 0.8) * 0.1 + Math.min(0.6, Math.abs(Math.sin(this.anim * 0.4)) * 0.3);
425:     this.ring.position.set(this.x, 0.07, this.z);
426:     this.ring.rotation.z += dt * 0.4;
427:     this.ring.material.opacity = 0.4 + Math.sin(performance.now() * 0.004) * 0.12;
428:   }
