433: function dampAngle(a, b, lambda, dt) {
434:   let d = b - a;
435:   while (d > Math.PI) d -= Math.PI * 2;
436:   while (d < -Math.PI) d += Math.PI * 2;
437:   return a + d * (1 - Math.exp(-lambda * dt));
438: }
