491:   startWave(n, callbacks = {}) {
492:     this.waveNumber = n;
493:     this.callbacks = { ...this.callbacks, ...callbacks };
494:     this.clear();
495:     this.active = true;
496:     this.time = 0;
497:     this.allSpawned = false;
498:     this.hornTimer = 0;
499:     this.totalSpawned = 0;
500:     const wave = WAVES[n - 1] || WAVES[WAVES.length - 1];
501:     const total = Object.values(wave.comp).reduce((a, b) => a + b, 0);
502:     const spawnIdxs = wave.boss ? [0, 1, 2] : [n % 3, (n + 1) % 3];
503:     const list = [];
504:     let idx = 0;
505:     for (const [type, count] of Object.entries(wave.comp)) {
506:       for (let k = 0; k < count; k++) {
507:         list.push({ type, spawn: spawnIdxs[idx % spawnIdxs.length] });
508:         idx++;
509:       }
510:     }
511:     // shuffle but keep boss last
512:     const bossTypes = list.filter(e => e.type === 'warlord');
513:     const rest = list.filter(e => e.type !== 'warlord');
514:     for (let i = rest.length - 1; i > 0; i--) {
515:       const j = (Math.random() * (i + 1)) | 0;
516:       [rest[i], rest[j]] = [rest[j], rest[i]];
517:     }
518:     const ordered = [...rest, ...bossTypes];
519:     this.queue = ordered.map((e, i) => ({
520:       ...e,
521:       delay: 0.7 + i * Math.max(0.52, 1.0 - total * 0.008) + rand(-0.2, 0.25),
522:     })).sort((a, b) => a.delay - b.delay);
523:     this.spawnDefenders();
524:     const keep = this.castle.centerOf(this.castle.structures.find(s => s.type === 'keep') || { i: KEEP_I, j: KEEP_J, w: 4, h: 4 });
525:     this.hero.reset(keep);
526:     this.hero.maxHp = Math.round(720 * (this.callbacks.heroHpMult || 1));
527:     this.hero.hp = this.hero.maxHp;
528:     this.hero.damage = 46 * (this.callbacks.heroDmgMult || 1);
529:     this.boss = null;
530:   }
