532:   spawnDefenders() {
533:     for (const d of this.defenders) this.defenderCrowdCull(d);
534:     this.defenders = [];
535:     const barracks = this.castle.structures.filter(s => s.type === 'barracks');
536:     let count = 0;
537:     const posts = [];
538:     for (const b of barracks) {
539:       const c = this.castle.centerOf(b);
540:       const n = garrisonFor('barracks', b.level);
541:       for (let k = 0; k < n && count < 8; k++) {
542:         const a = (k / n) * Math.PI * 2;
543:         posts.push({ x: c.x + Math.cos(a) * (2.2 + (count % 2) * 0.8), z: c.z + Math.sin(a) * 2.2 });
544:         count++;
545:       }
546:     }
547:     const keepSt = this.castle.structures.find(s => s.type === 'keep');
548:     const keep = keepSt ? this.castle.centerOf(keepSt) : { x: 0, z: 0 };
549:     if (!posts.length) {
550:       for (let k = 0; k < 2; k++) posts.push({ x: keep.x + (k ? 2.5 : -2.5), z: keep.z + 6.2 });
551:       count = 2;
552:     }
553:     for (let k = 0; k < count; k++) {
554:       const post = posts[k % posts.length];
555:       const d = {
556:         x: post.x + rand(-0.4, 0.4), z: post.z + rand(-0.4, 0.4), yaw: 0,
557:         hp: 155, maxHp: 155, scale: 1.02, radius: 0.42,
558:         color: 0x3d6b94, shieldColor: 0x31566f, shieldScale: 1.0,
559:         anim: Math.random() * 6, attackAnim: 0, flash: 0, deathT: 0,
560:         attackCd: rand(0, 0.4), target: null, post, speed: 2.45, damage: 13,
561:         isHero: false,
