569:   spawnEnemy(type, spawnIdx, hpMult = 1, dmgMult = 1) {
570:     const def = ENEMIES[type];
571:     if (!def) return;
572:     const spawn = SPAWNS[spawnIdx % SPAWNS.length];
573:     const x = spawn.x + rand(-2.2, 2.2);
574:     const z = spawn.z + rand(-2.2, 2.2);
575:     const si = clampCell(Math.round((x + HALF) / CELL - 0.5));
576:     const sj = clampCell(Math.round((z + HALF) / CELL - 0.5));
577:     const path = findPath(this.castle, si, sj, KEEP_I + 2, KEEP_J + 2);
578:     const e = {
579:       x, z, yaw: Math.atan2(-x, -z), hp: def.hp * hpMult, maxHp: def.hp * hpMult,
580:       type, def, scale: def.scale, radius: def.radius,
581:       color: def.color, shieldColor: type === 'shield' ? 0x6c3a28 : 0x72472f,
582:       shieldScale: def.shield || 0.001,
583:       anim: Math.random() * 6, attackAnim: 0, flash: 0, deathT: 0,
584:       speed: def.speed, damage: def.damage * dmgMult, attackCd: rand(0, 0.7),
585:       structureDamage: def.structureDamage || 1, siege: !!def.siege, boss: !!def.boss,
586:       isRam: type === 'ram',
587:       path, pathIdx: 1, pathTimer: rand(1.5, 3), targetStructure: null,
588:       combatTarget: null, state: 'walk',
589:     };
590:     this.enemies.push(e);
591:     this.totalSpawned++;
592:     if (e.boss) {
593:       this.boss = e;
594:       this.callbacks.onBossSpawn?.(e);
