599:   update(dt, gameBonuses = {}) {
600:     this.time += dt;
601:     this.hornTimer = Math.max(0, this.hornTimer - dt);
602:     if (this.markerTime > 0) {
603:       this.markerTime -= dt;
604:       this.commandMarker.visible = true;
605:       this.commandMarker.scale.setScalar(1 + (1 - this.markerTime / 1.2) * 1.6);
606:       this.commandMarker.material.opacity = Math.max(0, this.markerTime / 1.2) * 0.8;
607:     } else {
608:       this.commandMarker.visible = false;
609:     }
610:     if (!this.active) {
611:       this.hero.group.visible = false;
612:       this.hero.ring.visible = false;
613:       this.enemyCrowd.render(this.enemies);
614:       this.updateDeaths(dt);
615:       this.renderProjectiles(dt, false);
616:       return;
617:     }
618: 
619:     // spawn queue
620:     while (this.queue.length && this.queue[0].delay <= this.time) {
621:       const item = this.queue.shift();
622:       const hpMult = 1 + (this.waveNumber - 1) * 0.11;
623:       const dmgMult = 1 + (this.waveNumber - 1) * 0.075;
624:       this.spawnEnemy(item.type, item.spawn, hpMult, dmgMult);
625:     }
626:     this.allSpawned = this.queue.length === 0;
627: 
628:     for (const e of this.enemies) {
629:       if (e.hp <= 0) continue;
630:       this.updateEnemy(e, dt);
631:     }
632:     this.updateDefenders(dt);
633:     const keepSt = this.castle.structures.find(s => s.type === 'keep');
634:     const keepPos = keepSt ? this.castle.centerOf(keepSt) : { x: 0, z: 0 };
635:     this.hero.update(dt, this.enemies, this.active, keepPos);
636:     this.updateTowers(dt, gameBonuses);
637:     this.renderProjectiles(dt, true);
638:     this.updateDeaths(dt);
639:     this.enemyCrowd.render(this.enemies);
640:     this.defenderCrowd.render(this.defenders);
641:     this.heroCapeWave(dt);
642: 
643:     if (this.allSpawned && !this.enemies.some(e => e.hp > 0)) {
644:       this.active = false;
645:       this.hero.group.visible = false;
646:       this.hero.ring.visible = false;
647:       this.callbacks.onWaveComplete?.(this.waveNumber);
648:     }
649:   }
