653:   updateEnemy(e, dt) {
654:     e.flash = Math.max(0, e.flash - dt * 4.5);
655:     e.attackAnim = Math.max(0, e.attackAnim - dt * 3.2);
656:     e.attackCd = Math.max(0, e.attackCd - dt);
657:     e.pathTimer -= dt;
658:     e.anim += dt * (e.speed * 2.2);
659:     if (e.siege) e.combatTarget = null;
660: 
661:     // find a defender or the captain to fight
662:     if (!e.siege) {
663:       let best = null, bd = 5.2;
664:       for (const d of this.defenders) {
665:         if (d.hp <= 0) continue;
666:         const dist = Math.hypot(d.x - e.x, d.z - e.z);
667:         if (dist < bd) { bd = dist; best = d; }
668:       }
669:       if (this.hero.active) {
670:         const hd = Math.hypot(this.hero.x - e.x, this.hero.z - e.z);
671:         if (hd < 6.2 && hd < bd) { bd = hd; best = this.hero; }
672:       }
673:       if (best) e.combatTarget = best;
674:       else if (e.combatTarget && (e.combatTarget.hp <= 0 || Math.hypot(e.combatTarget.x - e.x, e.combatTarget.z - e.z) > 8.5)) e.combatTarget = null;
675:     }
676: 
677:     if (e.combatTarget) {
678:       const t = e.combatTarget;
679:       const isHero = t === this.hero;
680:       if (t.hp <= 0) { e.combatTarget = null; }
681:       else {
682:         const dx = t.x - e.x, dz = t.z - e.z;
683:         const dist = Math.hypot(dx, dz);
684:         e.yaw = dampAngle(e.yaw, Math.atan2(dx, dz), 9, dt);
685:         const reach = 1.65 + e.radius;
686:         if (dist > reach) {
687:           this.moveEnemy(e, t.x, t.z, dist, dt);
688:         } else if (e.attackCd <= 0) {
689:           e.attackCd = e.def.cooldown;
690:           e.attackAnim = 1;
691:           this.audio?.hit();
692:           if (isHero) this.hero.takeDamage(e.damage * 1.1);
693:           else {
694:             t.hp = Math.max(0, t.hp - e.damage);
695:             t.flash = 1;
696:             bloodBurst(this.fx, new THREE.Vector3(t.x, 1, t.z), 0x7d2a22, 6);
697:           }
698:         }
699:         return;
700:       }
701:     }
702: 
703:     // structure target from path
704:     let st = e.targetStructure;
705:     if (st && st.hp <= 0) { e.targetStructure = null; st = null; }
706:     if (!st && e.path && e.pathIdx < e.path.length) {
707:       const cell = e.path[e.pathIdx];
708:       const s = this.castle.getStructureAt(cell.i, cell.j);
709:       if (s && s.hp > 0) {
710:         e.targetStructure = s;
711:         st = s;
712:       }
713:     }
714:     if (st) {
715:       const c = this.castle.centerOf(st);
716:       const dx = c.x - e.x, dz = c.z - e.z;
717:       const dist = Math.hypot(dx, dz);
718:       e.yaw = dampAngle(e.yaw, Math.atan2(dx, dz), 9, dt);
719:       const reach = Math.max(st.w, st.h) * CELL * 0.48 + e.radius + 0.35;
720:       if (dist > reach) {
721:         this.moveEnemy(e, c.x, c.z, dist, dt);
722:       } else if (e.attackCd <= 0) {
723:         e.attackCd = e.def.cooldown;
724:         e.attackAnim = 1;
725:         this.castle.damage(st, e.damage * e.structureDamage, 'enemy');
726:         this.audio?.hit();
727:         if (e.isRam) {
728:           dustBurst(this.fx, new THREE.Vector3(c.x, 1.6, c.z), 0xb7a98e, 10, 2.6);
729:           this.audio?.build();
730:         }
731:       }
732:       return;
733:     }
734: 
