.panel-boss-ic .ic { font-size: 15px; }
.panel-boss b { display: block; font-family: var(--serif); font-size: 13px; color: #f0d2c8; margin-bottom: 1px; }
.panel-boss span { display: block; font-size: 10px; line-height: 1.4; color: #b9938d; }
.panel-section { margin-top: 10px; }
.panel-section h4 { display: flex; align-items: center; gap: 5px; margin: 0 0 5px; font-size: 8.5px; letter-spacing: .16em; text-transform: uppercase; color: #a2957e; font-weight: 700; }
.panel-section h4 .ic { display: none; }
.rew-loot.tight { gap: 5px; margin-bottom: 6px; }
.rew-loot.tight .loot-chip { height: 24px; padding: 0 8px; font-size: 10.5px; }
.panel-skin, .brief-skin { display: flex; gap: 8px; align-items: center; padding: 7px; border-radius: 8px; background: rgba(0, 0, 0, .2); border: 1px solid rgba(255, 255, 255, .05); }
.panel-skin .skin-swatch, .brief-skin .skin-swatch { width: 42px; height: 42px; flex: none; border-radius: 6px; }
.panel-skin b, .brief-skin b { display: block; font-family: var(--serif); font-size: 12px; color: #efe1c6; }
.panel-skin span, .brief-skin span { display: block; font-size: 9.5px; line-height: 1.35; color: #9b917f; margin-top: 1px; }
.panel-claim { display: flex; gap: 8px; padding: 9px 10px; border-radius: 8px; background: rgba(231, 195, 122, .09); border: 1px solid rgba(231, 195, 122, .28); color: #c9b995; font-size: 10.5px; line-height: 1.45; margin-bottom: 10px; }
.panel-claim .ic { font-size: 16px; color: var(--gold); flex: none; margin-top: 1px; }
.panel-note { font-size: 10.5px; line-height: 1.45; color: #8f8674; margin: 8px 0 10px; }
.panel-note b { color: #cdbb96; }
.panel-actions { margin-top: 11px; }
.panel-actions .btn { width: 100%; }
.panel-dungeon {
  display: flex; align-items: center; gap: 7px; width: 100%;
  padding: 7px 8px; margin-bottom: 5px;
  border-radius: 7px;
  background: rgba(255, 255, 255, .035);
  border: 1px solid rgba(255, 255, 255, .06);
  text-align: left;
  transition: border-color .15s, background .15s;
}
.panel-dungeon:hover { border-color: rgba(231, 195, 122, .5); background: rgba(231, 195, 122, .06); }
.panel-dungeon.locked { opacity: .55; }
.pd-ic { width: 24px; height: 24px; flex: none; border-radius: 6px; display: grid; place-items: center; background: rgba(184, 70, 51, .16); color: #e79b8a; }
.pd-ic .ic { font-size: 13px; }
.pd-name { flex: 1; min-width: 0; font-family: var(--serif); font-size: 11.5px; color: #e7d9be; line-height: 1.15; }
.pd-name i { display: block; font-family: var(--ui-font); font-style: normal; font-size: 7.5px; letter-spacing: .1em; text-transform: uppercase; color: #8f8571; }
.pd-state { font-size: 8px; letter-spacing: .1em; text-transform: uppercase; color: var(--gold-2); }
.map-legend { display: flex; align-items: center; gap: 13px; flex-wrap: wrap; margin-top: 11px; font-size: 8.5px; letter-spacing: .09em; text-transform: uppercase; color: #8f8674; }
.map-legend > span { display: flex; align-items: center; gap: 5px; }
.legend-dot { width: 8px; height: 8px; border-radius: 50%; display: inline-block; background: #6c6450; border: 1px solid rgba(231, 195, 122, .35); }
.legend-dot.claimed { background: var(--gold); }
.legend-dot.current { background: #d9705b; }
.legend-dot.locked { background: #4a4a46; }
.legend-dot.dungeon { background: #8a3f34; border-radius: 2px; transform: rotate(45deg); }
.legend-spacer { flex: 1; }

/* ============ Crown vault / shop ============ */
.modal-card.shop-modal { width: min(1000px, 95vw); }
.shop-head { display: flex; gap: 18px; justify-content: space-between; align-items: flex-start; padding-right: 30px; margin-bottom: 6px; }
.shop-head .modal-sub { margin-bottom: 8px; }
.shop-wealth { flex: none; }
.shop-tabs {
  display: flex; gap: 6px; overflow-x: auto;
  padding: 4px 1px 9px;
  border-bottom: 1px solid rgba(231, 195, 122, .16);
  margin-bottom: 12px;
  scrollbar-width: none;
}
.shop-tabs::-webkit-scrollbar { display: none; }
.shop-tab {
  display: flex; align-items: center; gap: 6px;
  height: 35px; padding: 0 12px; flex: none;
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, .07);
  background: rgba(255, 255, 255, .035);
  color: #a99f8c;
  font-size: 11px; font-weight: 700; letter-spacing: .03em;
  transition: background .15s, border-color .15s, color .15s;
}
.shop-tab .ic { font-size: 15px; }
.shop-tab:hover { color: #ddd0b7; border-color: rgba(231, 195, 122, .35); }
.shop-tab.active {
  color: #2a2012;
  background: linear-gradient(180deg, #e2ba6d, #b5883e);
  border-color: #f0d9a8;
  box-shadow: inset 0 1px rgba(255, 255, 255, .35);
}
.shop-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 9px; }
.shop-cat-blurb { grid-column: 1 / -1; display: flex; align-items: center; gap: 7px; font-size: 10.5px; color: #9c917b; padding: 0 2px 2px; }
.shop-cat-blurb .ic { font-size: 15px; color: var(--gold-2); }
.shop-cat-blurb b { color: #d8c9ad; font-family: var(--serif); font-size: 13px; margin-right: 5px; }
.skin-card {
  display: flex; gap: 10px;
  padding: 9px;
  border-radius: 10px;
  border: 1px solid rgba(231, 195, 122, .15);
  background: linear-gradient(168deg, rgba(48, 48, 43, .62), rgba(18, 20, 21, .8));
  transition: border-color .15s, transform .15s;
}
.skin-card:hover { border-color: rgba(231, 195, 122, .45); }
.skin-card.equipped { border-color: rgba(231, 195, 122, .62); background: linear-gradient(168deg, rgba(72, 64, 43, .7), rgba(22, 22, 20, .85)); }
.skin-swatch {
  width: 76px; height: 76px; flex: none;
  border-radius: 8px;
  position: relative; overflow: hidden;
  display: grid; place-items: center;
  border: 1px solid rgba(255, 255, 255, .1);
  box-shadow: inset 0 0 18px rgba(0, 0, 0, .35);
}
.skin-swatch .ic { font-size: 26px; position: relative; z-index: 2; }
.skin-swatch.livery {
  background:
    linear-gradient(90deg, transparent 0 12%, var(--cloth) 12% 88%, transparent 88%),
    linear-gradient(180deg, #1c2024, #101214);
  color: var(--trim);
}
.skin-swatch.livery::after {
  content: ""; position: absolute; left: 14%; right: 14%; top: 12%; bottom: 20%;
  border: 1px solid var(--trim); opacity: .55; border-radius: 2px;
}
.skin-swatch.roof {
  background: linear-gradient(165deg, #2a3036, #14181b);
  color: var(--swatch);
}
.skin-swatch.roof::before {
  content: ""; width: 66%; height: 58%;
  background: repeating-linear-gradient(180deg, var(--swatch) 0 5px, rgba(0, 0, 0, .2) 5px 6px);
  clip-path: polygon(0 18%, 50% 0, 100% 18%, 100% 100%, 0 100%);
  box-shadow: 0 3px 8px rgba(0, 0, 0, .4);
}
.skin-swatch.stone {
  background: repeating-linear-gradient(0deg, rgba(0, 0, 0, .16) 0 1px, transparent 1px 13px),
              repeating-linear-gradient(90deg, rgba(0, 0, 0, .16) 0 1px, transparent 1px 19px),
              linear-gradient(145deg, var(--swatch), #6d675c);
}
.skin-swatch.stone::after {
  content: ""; position: absolute; inset: 16% 12%;
  border: 3px solid rgba(0, 0, 0, .18);
  border-radius: 2px;
  box-shadow: inset 0 0 0 3px rgba(255, 255, 255, .12);
}
.skin-swatch.sky { background: linear-gradient(180deg, var(--s1), var(--s2) 58%, var(--s3)); color: rgba(255, 255, 255, .55); }
.skin-swatch.sky .swatch-sun {
  position: absolute; width: 22px; height: 22px; border-radius: 50%;
  right: 16%; top: 20%;
  background: radial-gradient(circle, #ffe9b0, rgba(255, 220, 140, .3) 60%, transparent 72%);
  box-shadow: 0 0 16px rgba(255, 225, 160, .55);
}
.skin-swatch.sky::after {
  content: ""; position: absolute; left: 0; right: 0; bottom: 0; height: 30%;
  background: radial-gradient(ellipse at 50% 100%, rgba(0, 0, 0, .38), transparent 70%);
}
.skin-swatch.captain {
  background:
    radial-gradient(circle at 50% 28%, var(--plate) 0 24%, transparent 25%),
    linear-gradient(180deg, transparent 0 60%, var(--cape) 60%);
  color: var(--trim);
}
.skin-swatch.captain::before {
  content: ""; position: absolute; left: 30%; right: 30%; top: 45%; bottom: 16%;
  background: var(--tunic);
  border-radius: 4px 4px 2px 2px;
  box-shadow: inset 0 4px 0 var(--plate);
}
.skin-body { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.skin-head { display: flex; align-items: baseline; justify-content: space-between; gap: 6px; }
.skin-head h4 { margin: 0; font-family: var(--serif); font-size: 14px; color: #f0e4cd; line-height: 1.1; }
.skin-tag { flex: none; font-size: 7.5px; letter-spacing: .1em; text-transform: uppercase; color: var(--gold-2); }
.skin-card p { margin: 0; font-size: 10px; line-height: 1.42; color: #a39a88; flex: 1; }
.skin-foot { display: flex; align-items: center; justify-content: space-between; gap: 6px; margin-top: 3px; }
.skin-source { display: flex; align-items: center; gap: 3px; font-size: 8px; letter-spacing: .05em; text-transform: uppercase; color: #8f8571; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.skin-source .ic { font-size: 11px; }
.shop-cols { display: grid; grid-template-columns: 1fr 1fr; gap: 9px; margin-top: 13px; }
.shop-block { padding: 12px; border-radius: 10px; background: rgba(255, 255, 255, .03); border: 1px solid rgba(255, 255, 255, .065); }
.shop-block h3 { display: flex; align-items: center; gap: 6px; margin: 0 0 3px; font-family: var(--serif); font-size: 15px; color: #eee1c8; }
.shop-block h3 .ic { font-size: 17px; color: var(--gold); }
.shop-block > p { margin: 0 0 9px; font-size: 10px; line-height: 1.45; color: #948a78; }
.pack-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; }
.crown-pack {
  display: flex; flex-direction: column; align-items: center; gap: 1px;
  padding: 9px 5px 7px;
  border-radius: 8px;
  border: 1px dashed rgba(231, 195, 122, .3);
  background: linear-gradient(180deg, rgba(231, 195, 122, .07), rgba(0, 0, 0, .18));
  transition: border-color .15s, background .15s, transform .1s;
}
.crown-pack:hover { border-color: rgba(231, 195, 122, .7); background: rgba(231, 195, 122, .1); }
.crown-pack:active { transform: scale(.97); }
.pack-amount { display: flex; align-items: center; gap: 3px; font-size: 14px; font-weight: 800; color: var(--gold); }
.pack-amount .ic { font-size: 14px; }
.crown-pack b { font-size: 8.5px; letter-spacing: .04em; color: #d6c7ab; text-align: center; line-height: 1.15; }
.crown-pack i { font-style: normal; font-size: 9px; color: #a99f8c; }
.crown-pack em { font-style: normal; font-size: 6.5px; letter-spacing: .12em; text-transform: uppercase; color: #7f7768; margin-top: 2px; }
.oath-block {
  background:
    radial-gradient(ellipse at 20% 0%, rgba(231, 195, 122, .13), transparent 60%),
    linear-gradient(165deg, rgba(58, 50, 34, .55), rgba(20, 20, 18, .7));
  border-color: rgba(231, 195, 122, .28);
}
.oath-price { display: flex; align-items: baseline; gap: 7px; margin: 2px 0 5px; }
.oath-price b { font-family: var(--serif); font-size: 19px; color: var(--gold); }
.oath-price span { font-size: 9px; letter-spacing: .08em; text-transform: uppercase; color: #9c917b; }
.oath-benefits { list-style: none; margin: 0 0 9px; padding: 0; display: grid; grid-template-columns: 1fr 1fr; gap: 4px 8px; }
.oath-benefits li { display: flex; gap: 4px; align-items: flex-start; font-size: 9.5px; line-height: 1.35; color: #b8ab94; }
.oath-benefits li .ic { font-size: 11px; color: var(--gold-2); flex: none; margin-top: 1px; }
.oath-block .btn.wide { height: 34px; }
.demo-mini { text-align: center; font-size: 8px; letter-spacing: .06em; text-transform: uppercase; color: #7f7768; margin-top: 6px; }
.demo-note {
  display: flex; align-items: flex-start; gap: 7px;
  margin-top: 12px; padding: 8px 10px;
  border-radius: 8px;
  background: rgba(159, 216, 239, .06);
  border: 1px solid rgba(159, 216, 239, .16);
  color: #93a8ad; font-size: 9.5px; line-height: 1.45;
}
.demo-note .ic { font-size: 14px; flex: none; margin-top: 1px; color: #8fbcc9; }
.demo-note b { color: #c3d6d9; }

/* ============ Dungeon brief & clear ============ */
.modal-card.dungeon-brief-card { width: min(700px, 94vw); }
.dungeon-brief { text-align: center; }
.brief-emblem {
  width: 64px; height: 64px; margin: 0 auto 9px;
  border-radius: 14px; transform: rotate(45deg);
  display: grid; place-items: center;
  background: radial-gradient(circle at 36% 28%, rgba(184, 70, 51, .32), rgba(0, 0, 0, .3));
  border: 1px solid rgba(184, 70, 51, .55);
  box-shadow: 0 0 30px rgba(184, 70, 51, .14);
  color: #e79b8a;
}
.brief-emblem .ic { font-size: 31px; transform: rotate(-45deg); }
.dungeon-brief .modal-sub { margin-left: auto; margin-right: auto; }
.brief-cols { display: grid; grid-template-columns: 1fr 1fr; gap: 9px; text-align: left; margin-top: 12px; }
.brief-block { padding: 11px; border-radius: 9px; background: rgba(255, 255, 255, .035); border: 1px solid rgba(255, 255, 255, .07); }
.brief-block h4 { display: flex; align-items: center; gap: 5px; margin: 0 0 4px; font-size: 8.5px; letter-spacing: .16em; text-transform: uppercase; color: #a2957e; }
.brief-block h4 .ic { font-size: 13px; color: var(--gold-2); }
.brief-block > b { display: block; font-family: var(--serif); font-size: 15px; color: #f0e2c9; margin-bottom: 2px; }
.brief-block > p { margin: 0; font-size: 10.5px; line-height: 1.45; color: #a99f8c; font-style: italic; }
.brief-hp { display: flex; align-items: center; gap: 4px; margin-top: 6px; font-size: 9.5px; letter-spacing: .06em; text-transform: uppercase; color: #c98e80; }
.brief-hp .ic { font-size: 12px; }
.brief-skin { margin-top: 7px; }
.first-clear {
  display: flex; gap: 11px; align-items: center; text-align: left;
  padding: 10px; margin: 2px 0 4px;
  border-radius: 9px;
  background: rgba(231, 195, 122, .09);
  border: 1px solid rgba(231, 195, 122, .32);
}
.first-clear .skin-swatch { width: 54px; height: 54px; }
.fc-kicker { display: flex; align-items: center; gap: 4px; font-size: 8px; letter-spacing: .16em; text-transform: uppercase; color: var(--gold-2); margin-bottom: 2px; }
.fc-kicker .ic { font-size: 11px; }
.first-clear b { display: block; font-family: var(--serif); font-size: 15px; color: #f3e4c6; }
.first-clear span { display: block; font-size: 10px; color: #b3a68e; }
.dungeon-win .rankup-crest { color: #e79b8a; border-color: rgba(184, 70, 51, .5); background: radial-gradient(circle at 40% 30%, rgba(184, 70, 51, .24), rgba(0, 0, 0, .3)); box-shadow: 0 0 40px rgba(184, 70, 51, .12); }
.loot-chip.crown { border-color: rgba(231, 195, 122, .4); color: var(--gold); }
.claim-banner {
  display: flex; align-items: center; gap: 9px;
  padding: 9px 11px; margin: 0 0 11px;
  border-radius: 9px;
  background: linear-gradient(90deg, rgba(231, 195, 122, .12), rgba(231, 195, 122, .04));
  border: 1px solid rgba(231, 195, 122, .33);
  text-align: left;
}
.claim-icon { width: 30px; height: 30px; flex: none; border-radius: 50%; display: grid; place-items: center; background: rgba(231, 195, 122, .16); color: var(--gold); }
.claim-icon .ic { font-size: 16px; }
.claim-banner > div { flex: 1; min-width: 0; }
.claim-banner b { display: block; font-family: var(--serif); font-size: 13px; color: #f0e1c3; }
.claim-banner div span { display: block; font-size: 10px; line-height: 1.35; color: #a99f8c; }
.claim-crowns { display: flex; align-items: center; gap: 3px; flex: none; font-size: 10px; font-weight: 700; color: var(--gold); }
.claim-crowns .ic { font-size: 12px; }
.chronicle-line {
  display: flex; gap: 6px; align-items: flex-start;
  margin: 0 0 11px; padding: 0 2px;
  font-family: var(--serif); font-style: italic;
  font-size: 11.5px; line-height: 1.45; color: #b9ac93;
}
.chronicle-line .ic { font-size: 13px; color: var(--gold-2); flex: none; margin-top: 1px; }
.oath-line + .story-body { margin-top: 12px; }

/* ============ Responsive ============ */

files.patch:
Index: src/style.css
===================================================================
--- src/style.css
+++ src/style.css
@@ -769,8 +769,576 @@
   background: rgba(13,15,17,.9); border: 1px solid rgba(231,195,122,.3);
   font-size: 12px; color: #d8c9ad;
 }

+/* ============ Crowns & premium ============ */
+.premium-btn { position: relative; }
+.premium-btn .ic { color: var(--gold); }
+.crown-badge {
+  position: absolute; top: -5px; right: -7px;
+  min-width: 19px; height: 16px; padding: 0 4px;
+  border-radius: 9px;
+  background: linear-gradient(180deg, #e8c77e, #b5883e);
+  border: 1px solid rgba(255, 235, 190, .7);
+  color: #2a2012;
+  font-size: 9px; font-weight: 800; letter-spacing: 0;
+  display: grid; place-items: center;
+  box-shadow: 0 2px 6px rgba(0, 0, 0, .55);
+  pointer-events: none;
+}
+.crown-pill {
+  display: inline-flex; align-items: center; gap: 6px;
+  height: 34px; padding: 0 11px;
+  border-radius: 999px;
+  border: 1px solid rgba(231, 195, 122, .35);
+  background: linear-gradient(180deg, rgba(63, 53, 33, .85), rgba(24, 23, 19, .9));
+  color: #f0e1c3;
+  box-shadow: inset 0 1px rgba(255, 255, 255, .08);
+}
+.crown-pill .ic { font-size: 16px; color: var(--gold); }
+.crown-pill b { font-size: 15px; font-variant-numeric: tabular-nums; }
+.crown-pill em { font-style: normal; font-size: 8.5px; letter-spacing: .14em; text-transform: uppercase; color: #a99a7d; }
+.crown-pill.big { height: 42px; padding: 0 14px; }
+.crown-pill.big b { font-size: 19px; }
+.btn.small { height: 30px; padding: 0 11px; font-size: 10.5px; border-radius: 6px; }
+.btn:disabled { opacity: .5; cursor: default; transform: none !important; }
+
+/* ============ Prologue ============ */
+.modal-card.story-modal-card {
+  width: min(660px, 94vw);
+  background:
+    radial-gradient(ellipse at 50% -10%, rgba(231, 195, 122, .14), transparent 55%),
+    linear-gradient(165deg, rgba(32, 33, 31, .99), rgba(14, 15, 17, .99));
+  border-color: rgba(231, 195, 122, .5);
+}
+.story-modal { position: relative; text-align: center; padding: 4px 2px 0; }
+.story-glow {
+  position: absolute; top: -40px; left: 50%; transform: translateX(-50%);
+  width: 300px; height: 180px; pointer-events: none;
+  background: radial-gradient(ellipse at 50% 50%, rgba(231, 195, 122, .16), transparent 68%);
+  filter: blur(8px);
+}
+.story-modal .modal-kicker { position: relative; }
+.story-title {
+  position: relative;
+  font-size: clamp(38px, 7vw, 58px);
+  color: #f7ecd3;
+  text-shadow: 0 4px 30px rgba(0, 0, 0, .6);
+  margin-bottom: 2px;
+}
+.story-lead {
+  font-family: var(--serif); font-style: italic;
+  font-size: clamp(15px, 2.4vw, 18px);
+  color: var(--gold);
+  margin: 2px 0 16px;
+  letter-spacing: .03em;
+}
+.story-body {
+  text-align: left;
+  border-top: 1px solid rgba(231, 195, 122, .18);
+  border-bottom: 1px solid rgba(231, 195, 122, .18);
+  padding: 12px 2px;
+  margin-bottom: 14px;
+}
+.story-body p {
+  margin: 0 0 9px;
+  font-family: var(--serif);
+  font-size: 13.5px;
+  line-height: 1.62;
+  color: #c9bda6;
+}
+.story-body p:last-child { margin-bottom: 0; }
+.story-body p:first-child { color: #e7d8bc; }
+.oath-line {
+  font-family: var(--serif); font-style: italic;
+  font-size: 13px; line-height: 1.5;
+  color: #d8b979;
+  max-width: 520px; margin: 0 auto;
+  letter-spacing: .02em;
+}
+
+/* ============ Tutorial ============ */
+#tutorial {
+  position: absolute;
+  left: 50%;
+  bottom: calc(180px + var(--safe-b));
+  transform: translateX(-50%);
+  z-index: 48;
+  width: min(500px, calc(100vw - 26px));
+  pointer-events: none;
+  transition: opacity .2s ease;
+}
+#modal:not(.hidden) ~ #tutorial { opacity: 0; pointer-events: none; }
+.tut-card {
+  pointer-events: auto;
+  padding: 12px 14px 13px;
+  border-radius: 11px;
+  border: 1px solid rgba(231, 195, 122, .5);
+  background:
+    radial-gradient(ellipse at 20% 0%, rgba(231, 195, 122, .14), transparent 60%),
+    linear-gradient(165deg, rgba(38, 38, 34, .97), rgba(15, 17, 19, .98));
+  box-shadow: 0 16px 46px rgba(0, 0, 0, .55), inset 0 1px rgba(255, 255, 255, .08);
+  animation: tutIn .32s cubic-bezier(.2, .9, .3, 1) both;
+}
+@keyframes tutIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: none; } }
+.tut-top { display: flex; align-items: center; justify-content: space-between; margin-bottom: 8px; }
